/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100309-3","meetingId":"h22-c-budget","date":"2010年3月9日","dateIso":"2010-03-09","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問","question":"私は１５３ページ、１目一般管理費の国際交流推進事業について、１６３ページ、イメージアップ運動についてお伺いをしたいと思います。平成２２年度、そこの中で、また国際都市を目指すということをどのようにお考えなのかなということを１点ちょっとお伺いしたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"今まで３都市との国際交流を市民活動ということで推進してまいりましたけれども、地域の国際交流のほうを進めていくという形で、その二つを今後も進めていきたいというふうに考えております。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"ということは、これからも先ほど答弁にありました、地道にということなんですけれども、しっかりと前向きにといいますか、さらに進めていくようなお気持ちというのはきっとあると思うんですけれども、そこのあたりのやはり意気込みというのを再度ちょっと確認をさせていただきたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"意気込みですけれども、これまでも続けてまいりました友好・姉妹都市、それから地域の国際化、これに関しては今後とも力を入れていきたいと、基本構想の一つの中に国際化というのも入れてありますので、もちろん進めていくという考えでおります。","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ国際交流というのはこれから必ず必要になってくる、ぜひそこのあたりの交流を活発に進めていっていただきたいと考えています。それと同時に、そこのあたりの今後の展開というのを、この２点をお伺いしたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"それから、地域でのいろんなイベントに外国人の方が参加していただけるような方法で今後進めていきたいというふうに考えております。なかなか好評であったというふうに聞いております。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問・要望","question":"参加をしていただくとあったんですけれども、促すための何か工夫というのを今後お考えであれば、お聞かせいただきたいと考えています。やはり交流というのは最初の壁を突破するのが一番大変だと思うので、そこのあたりのところをちょっとお聞かせいただきたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"通常の広報以外で口コミというのは外国人の方の中でコミュニティがありますので、その辺をうまく利用させていただいて、地域の事業等に参加するように促していきたいと考えています。","id":"exchange-004"},{"speaker":"井桁委員","kind":"質問・要望","question":"この質問は以上です。次に１６３ページ、今年減になっているんですが、これは理由があれば教えていただきたいと考えています。","respondent":"中川原広報広聴課長","answer":"今年度は基本デザインの見直しということで、運動が開始しましてから２０年近くたっておりますので、イメージアップの運動の道具をリニューアルしたということで、その分のお金が減っているところです。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"この平成１９年に改正されたこの法律の要綱を、私も少し見ましたところ、機能を果たしていくよう求めるというようなところで文面が載っておりました。なぜ今回だったのかな、計画を立てていくわけですから、それを説明するよう求めました。","respondent":"中山人権啓発課長","answer":"今回この基本計画を策定するに当たりまして、今まで区のほうで対応してきたことを改めまして基本計画ということでまとめていきたいと考えています。実際の計画のスタートとしましては、平成２３年４月ということで考えております。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"先ほどのご説明によりますと、区民相談あるいは子育て支援相談、これまで従前やられていたことを一つの施設という形でされるんでしょうか。それとも、このままの体制で、いわゆる横断的にコーディネーターの方などがいて、相談窓口というふうになるんか尋ねました。","respondent":"中山人権啓発課長","answer":"配偶者暴力相談支援センターについてのお訪ねですが、子育て支援課のほうで東京都のウィメンズプラザですとか。そういった流れの中でできるだけこの相談支援センターの機能を果たしていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"いろんなところの相談の窓口に、このようにしてくださったという声を聞いておりますので、大変よく相談に乗ってくださっていることを伺っております。そういった方のご相談もぜひ受けていただけるような体制をお願いしたいと思うんですが、いかがか尋ねました。","respondent":"中山人権啓発課長","answer":"虐待という言葉にはなっておりますが、委員ご指摘のとおり暴力の中には身体的な暴力だけではなく、精神的な被害というものも当然入ってまいります。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"東品川の清掃作業所、これはお聞きしているところで、それとも現状のままでも一時的な活用であればいいのかというところを少しお聞かせを願いたい。１０年間遊ばせるというのは余りにも杓子定規な考え方だとは思うんですけれども、その辺、具体的なところもお聞かせを願いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"行政需要についてですけれども、私どもが精力的に進めていかなければならないといった行政需要のものだというふうに考えております。それと、１０年間のしばりというものはありますけれども、よりよい方向での有効活用を図っていきたいというふうに考えているところです。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点目でお聞きをしたのは、住民要望というのが行政需要にどういうふうに取り入れられるのかということなんです。当然住民の要望がどういうふうに取り入れられるかということもあるんでしょうけれども、不満を持つということは十分考えられるわけですよね。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度からは新たな仕組みの事務事業評価も実施していくですので、決算に至る過程の中でも十分各事業の見直しを図っているです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"私は、基本的に区民要望というのは、大きくは満たされていないと思うんですよね。基本的には住民が要望する、今何が必要だ、これを取り入れてこそ行政需要じゃないかというふうに思うんです。","respondent":"久保田行財政改革担当課長","answer":"行政需要についてですけれども、私どもこの長期基本計画、１０年間の行政計画ということで作成させていただきました。ただ、この長期基本計画を１本の大きな柱としてそれぞれ柔軟に対応していきたいというふうに考えているところでございまして、今鋭意準備を進め。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"現状の声は聞きませんよと言っているのと同じことではないかなというふうに思うんですね、今の答弁というのは。どうやって今現実に挙がっている住民の要望、ニーズというのをとらえるのかというところをもう一度お聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"日々の仕事を通じまして、職員一人ひとりが区民の声に耳を傾けまして区民の要望というものを取り入れているところです。例えば先ほどもご説明しましたけれども、区民の声につきましては十分組み入れた形で施策を進めているというふうに考えております。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"緊急的な課題としてしっかりと区民の要望に沿って位置づけるということがまず大前提なんではないかと思うんですね。東品川の清掃作業所についても、こうした見地からやっぱりしっかりとどんな活用が必要なのかということを考えていくべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"稲川委員","kind":"質問","question":"１６９ページ、１８７ページの初期消火体制強化費の中の街頭消火器格納箱等補修、１９９ページの外国人登録費についてお伺いをいたします。１年たちまして、この制度の感想と助成対象町会が何町会あったのか、その町会が具体的にどういった形でこの助成金を使われたのかを説明するよう求めました。","respondent":"中山地域活動課長","answer":"この地域コミュニティ活性化助成金ですけれども、新たに町会の果たす地域コミュニティの活動を一層支援するために本年度から実施した事業です。ということで、現在２０３町会・自治会すべてに規模に応じた配分がされているです。","id":"exchange-014"},{"speaker":"稲川委員","kind":"質問","question":"ここになるかわからないんですが、町会・自治会館の建設の補助とかさまざまな補助をやられていて、本当に地域の方は助かっているです。今後検討するお考えがあるかどうか、どっちかわからないんですが、ご答弁をお願いします。","respondent":"中山防災課長","answer":"上物につきましては、町会費で建てていただくというのが原則です。今のところ補助は考えてございません。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"続きまして、１７３ページの荏原町安全安心ステーションの運営経費についてお伺いをいたします。それとあと運営体制が今までと変わるのか変わらないのか、その２点、お伺いします。","respondent":"藤橋都市整備下水道課長","answer":"荏原町安全安心ステーションの工事につきまして説明申し上げます。内装の工事を行い、３月３１日までには完了させる予定で現在進めておりますが、今の予定ですと３月３１日までに終わらせる予定で進めております。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"続きまして、１８７ページの初期消火体制について、消火器の格納箱補修についてお伺いいたします。そして、関連はすると思うんですが、区内に街頭消火器というんですか、何カ所設置しているのか説明を求めました。","respondent":"中山防災課長","answer":"それが１,１２６万７,０００円ということで、場所につきましては、これはそれが出てきた時点でこれに対応するということで、予測です。それから、街頭消火器の数ですけれども、今日現在で、本日現在で区内５,７２１カ所です。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"５,７２１カ所なんですが、どの地域に何カ所かという、その詳細がわかれば教えてください。そしてあと、何年前から設置されているのかわからないんですが、何をもとにその消火器を設置しているのかというところを説明するよう求めました。","respondent":"中山防災課長","answer":"それから大崎地区が１,３３４本、それから大井地区が１,４２３本、それから荏原地区が２,０４９本です。これの消火器の設置の根拠ですけれども、それに従いまして事業開始年度が昭和４７年、約３５年ぐらい前から設置しているものです。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"荏原地区が２,０４９本ということで、非常に多い本数が設置されている。この必要性が非常に私はあると考えているんですが、今後そういった増設のお考えがあるかどうか、お伺いします。","respondent":"中山防災課長","answer":"１５５カ所、ふたをあけて、水が減っていないかどうかというのを確認してもらっています。それから、消火栓の増については私どもの範疇ではございませんので、お答えすることができません。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"消火栓は消防署になるのかな。一つ地図に落として、ここに消火器がありますよといった地図の作成というのはされているかどうか、される思いがあるのか説明を求めました。","respondent":"中山防災課長","answer":"今のところ、地図はありません。ただ、配置箇所については一覧表で出せるかどうかはわかりませんけれども、配置場所は出せるということで考えていただいて結構です。","id":"exchange-020"},{"speaker":"稲川委員","kind":"意見","question":"その辺、区民全員が共有できるような情報提供をしてください。３年以内に施行しなければいけないというところなんですが、品川区としてはどういう形で進めていくのか、お願いしますとの意見を述べました。","respondent":"梶戸籍住民課長","answer":"入管法等の改正法の施行日ですけれども、公布後３年以内の政令で定める日ですので、これは全国一斉です。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"提案","question":"どんなあらましか伺いたいのが１点と、品川区のトップページに入るアクセス数というのは、どのような変化があるのか教えてください。テーマにしろ、そんな特色を出していってもいいんじゃないかという提案があったので、この辺について何かお考えがあれば説明を求めました。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長","answer":"経年変化で役所として２年ごとに変化を聞いていくという項目と、所管課とのヒアリングを繰り返しまして、項目を精査して実施するものです。調査は世論調査だけではありませんで、世論調査は昭和４９年からこの方法を積み上げまして… 区で言いますと、いろいろな歴史の紹介ですとか、それから地域の方々の主催による講座の展開なども行っています。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"確認","question":"現状に対しての評価をどのようにされているのかを伺いたいのと、意見交換のやりとりも、メールというものの比重が高い方が増えていると思います。匿名性はやはり匿名なものに対して応対をする必要は私はないと思うんですが、その辺の確認をできたらと思います。","respondent":"中川原広報広聴課長","answer":"ただし、この４月にもう一回そういったことも含めてアンケートも繰り返して、ちょっとトップページはリニューアルをしようかと考えています。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、１８３ページの区民斎場運営費についてお伺いさせてほしいと求めました。毎年補修工事というんですかね、行われているというのはどういうことなのか教えてほしいと求めました。","respondent":"梶戸籍住民課長","answer":"なぎさ会館のご質問です。そこの中の維持補修費というものは、建物ですので、例えば小破修理、いわゆる壁の壊れたところを直したりとか、そういったものをしています。","id":"exchange-024"},{"speaker":"山元委員","kind":"質問","question":"すみません、その下の維持用消耗品等というのは、細かくて申しわけないんですが、その消耗品というのはどういうことを指しているのか教えていただけますか。","respondent":"梶戸籍住民課長","answer":"消耗品費のほうは、細かく申しますと、例えば紙とか、ペーパーとか、書類作成とか、そういった細々したものです。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問","question":"私も何度かなぎさ会館を利用させていただいたこともあるんですけれども、実は３階のお清めに行くところなんですが、靴を脱いで畳のお部屋に入ります。その辺は区としてはどのように思っていらっしゃるのか、また何か対策を考えていらっしゃるか教えていただけますか。","respondent":"梶戸籍住民課長","answer":"高齢者の方等が通れるように手すり等というお話なんですが、例えば階段とかトイレ等にはそういったものを取りつけてあります。今後の改修とか日々やっていく中で、区民の声をお聞きしながら改善するものは改善していきたいと、検討してまいりたいと思います。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"一歩間違いますと大変な事故につながるかなと思いますので、その辺もご検討ほしいと求めました。実は畳というのは正座をしなければいけなくて、その辺もできればいすのようにはならないのかなと思っているんですが、その辺はいかがか尋ねました。","respondent":"梶戸籍住民課長","answer":"この前畳等の替えをしてございまして、そちらのほう、テーブルとかという形にするのは今後の課題と考えています。そこらのところについては利用者の声を聞きながら、また何らかの対策が、すぐできるものは検討をしてまいりたいと思います。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"気持ちよく帰っていただくためにもいろいろ考えてほしいと求めましたので、どうか要望としてよろしくお願いいたします。オープニングにはまだまだ時間がかかりますが、この概要といいますか、教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"ご質問は設置までの対応というご質問でよろしいでしょうか。工事に入りますので、地域の方々に今までどおりスポーツ等にご利用いただくという形で説明をいたしまして、そういうことで考えております。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"本当に地元のメンバーは待ちに待って楽しみにしているわけですけれども、実はちょっと気になるのが喫茶コーナーというのがございまして、ここに地域住民団体で運営ということで、何かこれは具体的に何か予定をされているものがあるのか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"その中で運営をやっていただける団体がいらっしゃらないかということで募集をさせていただいて、公募の団体がございましたので、来年度新規開設以降こちらの喫茶コーナーの運営を区と協働で行っていくです。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"もう一つお聞きしたいんですけれども、ちょっと具体的になってしまうんですが、使用するのは可能なのでしょうか。それともう一点、ここをお借りする場合、駐車場の予定というのは何か予定しているのかどうかもお聞きしたいと思っているんですけれども。","respondent":"堀越文化スポーツ振興課長","answer":"ただ、特別養護老人ホーム側の必要な台数等もありますので、できる限り公共交通機関等をご利用いただきたいというふうに考えてあります。詳細についてはこれから検討します。","id":"exchange-030"},{"speaker":"山元委員","kind":"意見","question":"遠くの方も使えるのかなと思いますと、大変楽しみにしております。平成２３年２月にオープンということで、それでも何かイベント内容というか、何かお考えになっていらっしゃいますかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"地域の方々にご参加いただきながらイベントをやりたいというふうに考えていまして、具体的には、これから検討させていただきたいと考えています。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"八潮には太鼓とか高校生たちのバンドとかがありますので、ぜひ使ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６１ページの町会回覧板用統合ちらしと先ほどもありましたが、１７３ページ、荏原町安全安心ステーション事業でお伺いします。その辺のご要望もさせていただいたんですが、２月、３月になりました。","respondent":"中川原広報広聴課長","answer":"１月にモデル実施いたしました統合ちらしですが、よかったという、まずはやってくれてありがとうということでした。デザインも先ほどのお話のように好みもありますが、一覧性を大事にしながら今後より見やすいものにしていこうということで考えているところです。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは４月から月１回ご案内が入っていくと思うんですが、それができることによって、実際どれぐらい枚数が減らせるのかというのを知りたい。用紙のサイズの統一、実は各町会に回る回覧板が読みやすくなるというような呼びかけをぜひしていただきたいと思うんですが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"広報広聴課長が説明した統一的なものということですが、ほかにもそれぞれニュースであるとか、各所管で発行しているものがあります。さらにご質問にはありませんでしたけど、その結果、あるいはできる限り合わせてもらいたいという働きかけをしていきたいと考えています。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"警察に直接つながるような電話というんですか、ボタンを押したら電話がかかるとかという仕組みも引き継がれていくのでしょうか。今まで２年余仮設置をしていた中で、もしくは課題としてこういうことが残ったというようなところがあれば教えていただけますか尋ねました。","respondent":"矢部生活安全担当課長","answer":"そうしたことが、やはり地域の活性化にもつながっているんだと私は認識しております。この新ステーション、また今度立地条件がよくなりますので、そうした課題は解消されると考えています。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問・要望","question":"４月に開設をされまして、いよいよ本運用していく中で、ほんとうに有効に使われる安全安心ステーションであっていただきたい。例えば、このような安全安心ステーションを設けたいというような相談があった場合、区としてはどのように対応されていくか尋ねました。","respondent":"矢部生活安全担当課長","answer":"新ステーションがほかのところにも設置できるかというご質問だと思います。用地の関係、それから維持管理の関係がありますので、なかなかご要望にこたえることはちょっと現時点では難しいというふうに考えております。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひ、今はそのような形かもしれませんが、今後可能性として一応残してほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田委員","kind":"質問・要望","question":"１８５ページ、それと１８７ページ、中学校消火ポンプ配備についてお伺いをします。バー等を設置していただいて管理をしていただきたいんですが、どのような管理運営をしていくのか、何台ぐらいの規模になるのか示すよう求めました。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長、佐藤防災安全担当課長","answer":"目的ですけれども、ここのところ、外国人の方の数、品川区内で１万２,０００人、総人口の約３.３％程度ということになっております。… このうち管理用の駐車場等もありますので、コインパーキングで今想定しておりますのは８台の部分についてそういう形での運営を今予定しています。… それで、訓練日程については、学校側と消防署、または消防団で夏休み中に訓練を実施するように調整しております。","id":"exchange-038"},{"speaker":"石田委員","kind":"質問・要望","question":"地域の人たちの要望もあったので、ぜひその方向で進めてほしいと求めました。これは要望で終わります。","respondent":"佐藤防災安全担当課長","answer":"中学校に対しミニポンプを配備していきますが、現時点において全中学校の総合大会ということについては、検討もしていない段階です。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"１６１ページ、それから１６８ページのほうの地域活動費、地域活動費が大分増えているというところをまず私は評価したいと思います。町会の件数ですね、これはちょっと違っていたら教えていただきたいんですけれども、そこのところの数の問題を確認します。","respondent":"中山地域活動課長","answer":"おそらくご質問は、この予算の中に環境整備等助成に２０５町会と書いてある。こういうことで余裕を持っていると、こういうことですので、２０３町会が現在の数です。","id":"exchange-040"},{"speaker":"原委員","kind":"質問・要望","question":"区にとって町会は何なんだという基本的なというか、位置づけという考えですかね、その辺をお教えいただきたい。そこをお願いいたします。","respondent":"中山地域活動課長","answer":"本来、地域の方々がその地域のために、ありていに言えばボランティアとしてさまざまな活動をやっていただいているというのが一つです。","id":"exchange-041"},{"speaker":"原委員","kind":"質問・要望","question":"１３地区というここですね、２カ所出てきているんですけど、これは地域という解釈でよろしいんですかね。それで一番上だけが「等」という形がついているものですから、その辺のところをちょっとお教えいただければと思うんですけど。","respondent":"中山地域活動課長","answer":"区内をコミュニティブロックとしては１３地区に大きく分け、それから各地区の町会、自治会連合会の単位にもなっているです。それから防災関係の助成も含めた、ここで「等」という表現を使わせていただいていると、これが補助の要綱の表現にもなっているです。","id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、これから助成関係でまたちょっと増えていくような、次のステップであり得るのかどうなのか。まだ土地は高いものですから、実際にその辺の動き的なものを教えていただきたいという、お願いいたします。","respondent":"中山地域活動課長","answer":"葬祭等を行う場合、これは扱いとして購入価格の２分の１にする、そういうことでは総額での助成が実態として図れるというふうに考えております。最後に、これは修繕等も対応できるように５年に期間を分けていく、この３点を改善するというふうに考えておるものです。","id":"exchange-043"},{"speaker":"原委員","kind":"意見","question":"そうしましたらば、先ほどほかの委員からもお話が出たかと思うんですけど、ちょっと見方を変えまして、先ほど、町会と区はパートナーとありました。各地域センターでは、どういう状況でとか、現実に則した形の具体的なお話をちょうだいできればと思うんですけどとの意見を述べました。","respondent":"中山地域活動課長","answer":"各２０３の町会・自治会長は区政協力委員というお顔もお持ちいただいて、この方々との区政協力委員会というのは、年に３回あります。そのほかにいろんな事業に応じては、役員とも地域センターの職員を通じてのやりとりも行っていると、このような形になっております。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"核兵器廃絶を求める流れというのは、核廃絶を求める、そういう参加が各国々から行われるという状況もあるというふうに聞いております。この間の情勢の発展、区はどういうふうに持っておられるのか、そこから伺いたいと思います。","respondent":"山岡健康課長、伊勢総務課長","answer":"受動喫煙防止につきましての区における考え方等々は、どの時期までにやるのかという点を含めて検討してまいりたいというふうに思っております。この取りまとめられた結果をまた見ることで… オバマ大統領がプラハで行った演説ですけれども、これは大変大きな意義があると考えております。それ以降も明確に核実験の中止等を訴えており、品川区の立場はプラハ演説の趣旨と同じものであるというふうに考えてあります。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"そういう教育がどの程度行われているのか、どういうふうに強化しなきゃいけないのかと考えているかということをちょっと伺いたいと思います。こういうところも同様ですけども、そういう立場に立っているんですけれども、品川区はそういう点でどういう事業をやっているんか尋ねました。","respondent":"冠木指導課長、荒井生活衛生課長、伊勢総務課長","answer":"たばこによる害であるとか、そういうような指導をして、喫煙の防止に努めているところです。直ちに受動喫煙防止に取り組む、あるいは分煙ですというシールをお使いくださいということで、ただいま運動を進めているところです。… この宣言の目的であります核兵器の廃絶と恒久平和確立の精神を継続的に普及させるとともに、戦争の悲惨さ等を次代に伝え、大きく分けて三つあります。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"住民活動をどういうふうな場面で支えている事業をしているかということを聞いたので、ちょっとそこは明確にしてほしいと求めました。そこが大事なので、そこは外さないで、ぜひ具体的な検討を進めてもらいたいという要望をしたいと思います。","respondent":"伊勢総務課長","answer":"区民との関係、支援の関係ですけども、平和の運動をやっている方、いろんな考えの方があります。区は区の判断でやっていくということで、特別に平和の関係の事業だからということで特別に支援をするということはございません。","id":"exchange-047"},{"speaker":"南委員","kind":"意見","question":"核兵器廃絶をさせると、そこの１点でとらえるべきだというふうに思います。ぜひ姿勢を改めるべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"何点かまとめて、１６３ページの区民相談室、来年度より社会保険労務士の協力をいただいた区民相談が行われるというふうに伺っております。どういうことが区民の皆さんにとって相談ができるのか、周知の方法についても十分に行っていただきたいという意味でお話を伺いたいと思います。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長、鷹倉監査委員事務局長","answer":"この間、時間がたつ中で、ユニバーサルデザインとか景観とか観光等新たな要請が区役所に出てまいりました。… 科目の中で健康の科目を少し増設したりですとか、そのようないろいろなアンケート等もいただきながら科目の中身の変更等も図ってきております。… ただ、指摘なり、そういうものが確実に少なくはなってきてはいますが、まだ残念ながら指摘せざるを得ないものも幾つかあるというのが現状です。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"その中で、また７０代の高齢者の方、やはりニーズというものが随分と変わってきているんだろうなというふうにお話を伺いながら感じております。現状の職員の体制で果たして十分にそのニーズにこたえられるのかどうかというのを一つご見解をほしいと求めました。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長、鷹倉監査委員事務局長","answer":"広報紙で毎月１日に出しています定例の相談案内、それから区民相談室で発行しております相談室のパンフレット、周知には努めてまいりたいと思います。先ほどもお答えしましたが、アンケート等も行いながら、そういったことによって対応しております。職員だけでの対応というご質問ですけれども… これがわかるような形、これが自分の部局のことだというふうに受けとめていただけるようにこれを各所管のところに行ってお話をしています。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味で、これはどうなんでしょうか。さまざまな講師を呼ぶという、これに対しての外部的な委託のあり方について一言、検討するかどうかお聞かせいただきたい。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどご答弁申し上げた部分を入れつつやっておりますし、企業の貢献という意味で企業の方のいろいろな企画案等も採用しています。さまざまな部分を研究していきながら運営を図っていきたいと、このように考えております。","id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"これは２８１ページに１２１万円で計上しておりますが、款が違うからやはりその辺は明確な違いがあるかと思うんですけど、その辺を伺いたい。それについて、この里山についての固定資産税等はどうなっているのか、この辺を伺いたいと思います。","respondent":"中山地域活動課長、工藤環境課長","answer":"これに後ほど環境課のほうから環境の取り組みも平成２１年度から始めているですけれども、現在区民の方と参加型で話し合いをしながら進めていく。今月１８日にもその検討会をやっていくという予定です。私ども環境課のほうでも今年度からマウントしながわ活用事業、地域活動課と共同で事業を実施したものです。","id":"exchange-052"},{"speaker":"山内委員","kind":"質問・要望","question":"もう少し具体的に何かビジョンを見せていくということが必要なのかなというところをちょっと要望させてほしいと求めました。例えば、どういう形で周知をされて、それでどういう形で配置をされるのかというところを伺いたいと思います。","respondent":"伊勢危機管理室長","answer":"たまたま要綱を設置してからちょうど５年目になるんですけれども、一番最初に置いたのが新型インフルエンザの関係でございました。津波の場合は、災害対策本部を設置して、そこで仕事をしたです。","id":"exchange-053"},{"speaker":"山内委員","kind":"質問","question":"本部というのはどういう形で設置をされて、それが解除されるんですか。本部の考え方。","respondent":"中山防災課長","answer":"日曜日、２月２８日ですけども、津波に関する水防関係の本部は、防災まちづくり事業部が中心となって、水防本部を立ち上げます。この日は午後０時に６０名体制で水防本部、私どものほうで本部を立ち上げて、警報が解除されればそのまま解散となります。","id":"exchange-054"},{"speaker":"山内委員","kind":"質問","question":"非核平和都市品川宣言の事業について伺いますけれども、使節団を派遣している、１２月に我が会派で広島市の平和記念資料館に行ってまいりました。資料を見ていただくということ、過去に広島市との連携をとってそういうような展示会を開いたことがあるのかということを伺います。","respondent":"伊勢総務課長","answer":"必要に応じて歴史館にある四百数十枚のパネルだとか、あるいは場合によると過去あまりさかのぼってそこまで把握していないんですけれども、必要に応じてそういうところから貴重なものがあればお借りするという考えは当然あったと思います。","id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"１５５ページ、職員福利厚生費、決算特別委員会でも伺いましたけれども、役所の食堂の件がどういうふうに改善されたか教えてください。次に１７１ページの青少年育成ですけれども、以前にも伺いましたけど、青少年委員の所管はまだ別々になっているのか説明を求めました。","respondent":"榎本人事課長、中山地域活動課長、堀越文化スポーツ振興課長、梶戸籍住民課長","answer":"その後実際に現場の説明をした後、６社が辞退しましたので、９社で書類選考に入ったというところです。この後、契約の手続をとりまして… 結婚サポート事業における記念証の実施の背景ということですけれども、ご結婚されたことを記念したあかしとしてお渡しするものです。… それから協働支援、ＮＰＯの団体等への拠点の貸し出しというところもありますので、それぞれ事業ごとに担当の所管が担当しているです。","id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"食堂の件ですけれども、決算のときも伺いましたけれども、４社のプロポーザルのときに担当課長としてちゃんと試食はしたんでしょうかお尋ねします。そのノウハウ等を持っているわけですから、行財政改革担当サイドからちょっとお返事いただくよう求めました。","respondent":"榎本人事課長、中山地域活動課長、小林青少年育成課長、久保田行財政改革担当課長","answer":"実際には４社残った中で、最終的に決定通知を出す前に選定委員のほうで味の確認にそれぞれ現地のやっている業者のところへ行ったです。… 記念の品になるようなもの、またそういう意味では受け取って喜ばれるようなものを考えて、励みにしていきたいというふうに考えているところです。… 今ご説明のあったところですが、選出母体でありますところの地区委員会と実質的に活動のパイプ役として地域との連携を深めていく予定です。","id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"婚活に関しては、決算でどのぐらいの数が出たかというのをまたずっと追っていきたいと思いますので、よろしくお願いします。最後に食堂なんですけれども、今度の食堂は本当に期待していいでしょうか、その辺を最後にお願いします。","respondent":"榎本人事課長","answer":"私が視察してきた関係からいくと、大丈夫だと考えています。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"それからこの記念証というんですか、むしろ区民で結婚された方で希望された方がいらしたらフレームは要らないですから、区としてお祝いをするなら。それから２０３ページ、すみません、区長選なんですけれども、この経費というのは即日開票で計算をされているのか尋ねました。","respondent":"阿部経理課長、中山地域活動課長、久保田行財政改革担当課長、早津選挙管理委員会事務局長","answer":"お尋ねのパーク２４のことですけれども、具体的には予算書の１５７ページの真ん中あたりに、庁舎等維持管理費というのがあります。… ただし、これは結果としてです。ちなみにというか、当面この事業の中でまず早く第１号の方にお渡しできるように進めていきたいと考えております。次の公共施設有効活用プラン策定経費、こちらは中長期改修計画等と合わせまして区有施設の有効活用を検討していくですので。… 人材、職員の確保、人材確保の関係で人数が大量には確保できない。","id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"共通プロジェクトのほうですが、地デジのほうは１世帯当たり７,０００円かかるものなんですかね。半日いらいらと待つのはつらいとは思いますけれども、いま一度その検討の余地があるかどうかだけでも説明を求めました。","respondent":"阿部経理課長、早津選挙管理委員会事務局長","answer":"さまざまな事情で車で来られる方がおります。区役所に来なければ完結しない事務ですので、駐車場のある一定時間の無料というのは当然のことだというふうに思っております。 選挙の即日開票は、２３区の一部を除いてはほとんど即日開票でやっているのが実態です。","id":"exchange-060"},{"speaker":"山路委員","kind":"質問・要望","question":"２点目が１７１ページ、３点目が２０７ページ、国勢調査についてお伺いいたします。３階に掲示されまして、どういう形で写真を撮られているのか、まず教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"航空写真につきましては、昭和４７年から隔年ごとに撮影をしてまいります。高さはちょっとヘリコプターが飛びまして、今広報紙の１日号で航空写真を特集しているんですが、あの写真が撮れる高さです。","id":"exchange-061"},{"speaker":"山路委員","kind":"質問","question":"そして特に私がここで一番いいかなと思っているのは、区民まつりで各地域におきまして、品川音頭を区民の皆様がにぎやかに踊っていらっしゃる。あるいは区内の状況とか、にぎやかな新たな品川の魅力が出てくると思いますが、この新しい企画についてどのようにお考えか尋ねました。","respondent":"中川原広報広聴課長","answer":"では、また平成２２年度予算で航空写真を撮らせていただきますので、できるところから頑張ってやらせていただきたいと思います。」とか、そういった地に足をつけた番組から文化の発信をしていこうということでやっておりますので、どうぞよろしくお願いいたします。","id":"exchange-062"},{"speaker":"山路委員","kind":"質問・要望","question":"民間のコマーシャルとか、協働によるそういうビデオ作成も考えられると思いますので、今後ともどうぞよろしくお願いいたします。私がここで要望したいことは、そういう形での支援は考えられないか、これについてお伺いいたします。","respondent":"秋山協働・国際担当課長","answer":"融資ということは今現在品川区では持っておりませんが、融資ということになりますと、返済ということが当然出てまいります。なかなか返済の能力ですとか、融資制度につきましては、今後どういうふうにやっていくのか検討研究させていただきたいというふうに考えております。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"こういうできる範囲での新しい支援対策も今後必要になってくると思いますので、これは研究していただきたいことを要望しておきます。そういうところまで細かくやるというふうなうわさを聞いているんですが、特に特色、どういう形でやられるかお聞かせをほしいと求めました。","respondent":"中山地域活動課長","answer":"平成２２年度が５年に１回の国勢調査ですが、１０年に一度その調査項目の多い年になりますので、詳しい調査になるというふうに聞いております。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域コミュニティ活性化助成金についてお伺いをいたしますが、６月から９月の間に助成金の申請、それと請求という流れで来ております。５月、この地域コミュニティ助成金について、各町会にどのような周知をされているのかまず聞かせてほしいと求めました。","respondent":"中山地域活動課長","answer":"平成２１年度から実施しておりますので、品川区町会連合会の総会で連合町会長にご説明した後、書式等要綱を踏まえてご説明をしているです。したがいまして、平成２２年度も同様な形で基本的には、地域センターを通じて町会長を通じての周知をしていくのを基本に考えております。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"町会の役員の方になかなかそれが周知できないということは、こういう制度があるということを知らない方が出てくるおそれもあるんですけれども、そこのところについてどういうふうにお考えか尋ねました。","respondent":"中山地域活動課長","answer":"これも基本的には地域センターを通じてご説明しておりますが、地域運営係のほうに問い合わせがあり、答えているということもあります。こういう補助、ほかの環境整備助成も含めて補助制度についてご説明をし、ご質問にも答えていると。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"先ほど町会長に地域センターを通じてということで、そこの場合、添付資料、地域活動課からいただいた資料と、ならびに交付要綱、そして申請書の１、２、３、４、５、６という書式が１冊になって手元にありますけれども、まさにこのような形で町会長にお配りをし、説明をされているわけか尋ねました。","respondent":"中山地域活動課長","answer":"基本的には町会長の会議で要綱、書式を含めてご説明をするというのを基本にしております。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、先ほどの周知の方法ですけれども、これは広報しながわとかそういうのは、すみません、ちょっと私勉強不足でそこのところを承知していなんですけれども、広報しながわあるいは区のホームページ等々を通じても、それは周知をされていたということでいいか尋ねました。","respondent":"中山地域活動課長","answer":"基本的に町会への幅広い助成という形になっておりますので、広報紙等一般への広報はしてございません。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、一般へのということは、ニーズはやはり一般の中にニーズがあると思うんですよ。どうもそこのところには町会長と一般の、それについて事業をやりたい、そこのところの対策はどのように立てていらっしゃいますか尋ねました。","respondent":"中山地域活動課長","answer":"今のご質問の趣旨を踏まえまして丁寧な説明、それで実際そういう実務をおやりになっている役員の方等へ直接具体的な説明をすることも含めて、本庁を含めてきちんと周知を図っていきたいと考えております。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問","question":"１号様式から６号様式までありますけれども、申請する段において、そこのところというのは工夫できるものなのでしょうか。あくまでもお金のことですから、書類というか、簡素化できるような余地というのはあるんか尋ねました。","respondent":"中山地域活動課長","answer":"防災に関する助成、その２点の従前からやっている申請書との整合を図りながら申請いただいているということがあります。ただ、きちんとまた声を聞きながら改善できる、簡素化できる部分があれば心がけていきたいというふうに考えております。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"地区委員会のことでお伺いをしたいと思います。対象者は子どもたちですから、３６５日と言えば３６５日なんですけれども、活動を何日ぐらい年間でやるんか尋ねました。","respondent":"中山地域活動課長","answer":"単純に言うと、各地区で１０ぐらいの事業、毎月のように何らかの事業をやっている。いろんなまた調整を考えると、かなり毎週のように何らかの役割を果たされているということは、想像できる部分です。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"１２０以上の事業を地区委員の方たちが担われているということを今、１２０以上あるわけですから、どのようなセーフティネットを設けられているのか説明を求めました。","respondent":"中山地域活動課長","answer":"いわゆる地区委員会、地域活動ということでボランティアとしての保険に加入していただくというか、区のほうで委員会活動についてボランティア保険の加入の対象にしているです。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"事故を起こすほうと起こされた方の間の交渉を取り持つような方というのは、どのような方が、行政が入ってやるんでしょうか。それともどのような形で、示談なり事件を処理していくのか尋ねました。","respondent":"中山地域活動課長","answer":"これは当然区として一定のかかわりというか、そういう面での地区委員のサポートを、保険に入っているだけではなくてしていく必要はあるというふうに認識しております。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"まさに現代はクレーマー社会と言われて久しいんですけれども、ささいなことについてもクレームをつけてくる方がいらっしゃるわけです。そういう恐怖におびえながらも、不安を払拭するために何か区のほうでお考えになっていることがあれば説明を求めました。","respondent":"中山地域活動課長","answer":"連合会なんかでも話題が出ているのは、改めてそういう基本的な知識というんですか、役割をきちんと伝える場面が必要なんではないか。そういう流れの中で今、ご質問があったような、そういう新しい方の研修の場面等でも考えていく余地があるのかなというふうに考えております。","id":"exchange-074"},{"speaker":"大沢委員","kind":"提案","question":"それで私一つご提案申し上げたいんですけれども、先ほどもお話をさせていただきました会計処理についてはアドバイザーを派遣するということです。いろんな部分でかかわっている方がいらっしゃるのは承知をしておりますけれども、弁護士の活用というのはできないんか尋ねました。","respondent":"中山地域活動課長、伊勢総務課長","answer":"現段階で、弁護士の活用というのを即座に考えるという状況ではないんですけれども、区がきっちりトラブルがあった場合には支援していくというふうに。これは事例に則して… 訟務員が区にいらっしゃるわけですけれども、訴訟だけではなくて、所管でそういう法律問題、こういうことにつきましては日常から相談に乗っていただいているところです。","id":"exchange-075"},{"speaker":"大沢委員","kind":"意見","question":"ハンドボールをやっている人口が少ないがゆえに関心度が低いので、そこらあたりはどういうふうに、失礼しました。３年ありますけれども、その中でどういうふうにハンドボールをアピールしていくか、そこのところをどういうふうに段取りを立てていくかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"ハンドボールの種目に内定をいただいているというところでございまして、東京国民体育大会、多摩中心部に開催をする予定です。そういった中で、そういった方々ともお話をさせていただきながら国民体育大会に向けて気運を高めていきたいというように考えているところです。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひハンドボールを受け持つ方たちもすぐにスムーズにヘルプ、手伝いができるような形の体制をつくってほしいと求めましたけども、いかがか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"平成２２年度、今ご説明しましたイベントを手始めにいたしまして、先ほどの区内の企業とも実は少しずつ話をさせていただいてあります。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"品川区はこれだけのことをハンドボール、ぜひとも全体の組織作りをきちんとやってほしいと求めました。防災倉庫があるんですけれども、あれはなぜ公園の平米数によって防災倉庫を置ける置けないという違いがあるんでしょうか、説明を求めました。","respondent":"中山防災課長","answer":"３００m2以内であっても、例えば２５０m2ぐらいだったら構わないんじゃないかと、オーケーだと。それから、要するに５m2の資機材倉庫だったのを７m2ぐらいまでは認めようじゃないかということです。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"昇任試験についてお尋ねしたいんですが、これについての仕組みを正確というんでしょうか、受験資格等を簡単にお教えください。それから、ここ３年間の受験者と合格者数を教えてほしいと求めました。","respondent":"榎本人事課長","answer":"大体３０歳前ぐらい、だんだん若くなってきておりますけれども、３０歳前ぐらいが受験の時期になると思います。平成２１年度につきましては受験資格者がかなり増えてきまして、それに応じて合格者も増えてきたという状況です。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"そのことについてどうお考えか。逆に見ると、そういった方々からの合格者が少ないことについてどうお考えで、どんな分析をされているのかお願いします。","respondent":"榎本人事課長","answer":"それからあと技術職、土木・建築の技術職も別区分で試験をやっていますので、それが入っていないということです。は配置されている職員、その中での受験の結果という形で、特に合格に当たって何部にいるからという形での選考は一切しておりません。","id":"exchange-080"},{"speaker":"高橋委員","kind":"質問","question":"あるいは区長もそちらのご経歴をお持ちとお聞きしておりますけれども、そういった数を見て今お話を伺えばそういった状況があるんですが、そういった他の部署の方のモチベーションに関してどのようにお考えか尋ねました。","respondent":"榎本人事課長","answer":"そういった意味では、各所属長を通じて受験の通知を出すときについても積極的に受けるようにということで周知を徹底しています。その周知とは別に各所属長の中から優秀な人には個別に声をかけていただくという形で、特にその辺の部分は丁寧にやっているところです。","id":"exchange-081"},{"speaker":"高橋委員","kind":"質問・要望","question":"すぐに４月から行うのかということと、さらに基準でしょうか、事務事業評価をされていくのでしょうか。そして、あらかじめ事業数を幾つにするとか、あるいは予算上これだけ見直すとかという目標の設定等も行われるのかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"現在最後の詳細な仕組みを検討しているところでございまして、平成２３年、それに合わせて実施をしていきたいというふうに考えてあります。すべての事務事業をゼロベースから見直すという形で施政方針でもご説明させていただきましたように、例えば予算事務事業ベースで考えれば。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"横串の事務事業評価というんですか、そういった形を行っていただければと思うんですが、いかがでしょうか。例えば、シルバー大学や品川文化振興事業団でいろんな講座をやったりしていますが、そういった横串的なことに関してはいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価を行っていく上では、当然ながら縦の系列だけではなくて、横串といったものも重要なことだと考えていますので、そのような視点で企画部のほうでも考えているところです。","id":"exchange-083"},{"speaker":"市川委員","kind":"質問","question":"歩行喫煙防止推進経費で伺いますけれども、大きくは喫煙マナーアップ啓発事業が新規として載っていて、ここにかなりの予算がつけられている。平成２１年度の予算書と比較すると、ちょっと書き方が変わったんですけれども、まずこの書き方が変わったのには意味があるのか伺います。","respondent":"中山人権啓発課長、矢部生活安全担当課長、佐藤防災安全担当課長","answer":"交流室が実は自由に、今現在きゅりあんの受付が２階にあるものですから、全くあそこの３階フロアのところに職員がいないような状況になっております。… 週５日、または昼、夜で配置員をつけてマナーアップのキャンペーンをしたいというふうに考えております。それとあとどこに収入部分で入ってくるかというご… 総務省、消防庁が推進している施策で、この公募に当たっての審査基準として大きく分けて二つあります。","id":"exchange-084"},{"speaker":"市川委員","kind":"質問","question":"歩行喫煙防止のほうですけれども、この６,０００万円すべてがこの巡回の強化というところにまず使われるのかということをお聞きしたいのと。そういう申し出を受けたということがあるのかどうか、その辺を説明するよう求めました。","respondent":"中山人権啓発課長、佐藤防災安全担当課長、矢部生活安全担当課長","answer":"先日、２月２３日でしょうか、初めて私もあそこを使っていらっしゃる団体との懇談会を開催させていただきました。ただ、団体の方たち… なお、小中学校に配置するという予定ですので、保護者が参加する児童引き渡し訓練等においても訓練ができるように調整をしてまいりたいと思います。学校… これからも喫煙者の方のマナーアップの向上に努めることを目標としたいと考えています。","id":"exchange-085"},{"speaker":"市川委員","kind":"質問・要望","question":"ちょっとここはお考えを伺います。ちょっと唐突な考え方なんですけれども、このことについて区はどんな見解をお持ちなのかということを伺うのと、ちょっとこの辺を説明するよう求めました。","respondent":"矢部生活安全担当課長","answer":"映画とかの上映については、またちょっとこれも検討の余地をいただきたいと考えています。受益者負担の関係ですけども、これについては今のところ、考えはありません。","id":"exchange-086"},{"speaker":"市川委員","kind":"質問・要望","question":"では、歩行喫煙防止のほうは次年度に向けてもそういった企画については検討していただきたいというふうに思います。こういうことはきちんと検証して今後の進め方の材料にしていただきたいなというふうに思っておりますが、この辺について見解をお願いします。","respondent":"矢部生活安全担当課長","answer":"暮らしというところですけども、この辺につきましても、議員ご指摘のとおり児童を見守るシステムとしては非常にいいシステムだと考えています。今後につきましても、そういったところに活用できるとかという場面がありましたら検討していきたいと考えています。","id":"exchange-087"},{"speaker":"伊藤委員","kind":"質問","question":"区から具体的に登録に対する対処の仕方というんでしょうか、こうしてくださいということについて話があったのが２回だけです。後追いが全くできていない現状があると思いますので、まずこの二つの問題に対しての対応策をお伺いいたします。","respondent":"矢部生活安全担当課長","answer":"地域活動課といたしましては、年に４回協力者通信というのを発行して、現在のまもるっちの運用状況等についてお知らせをしています。","id":"exchange-088"},{"speaker":"伊藤委員","kind":"確認","question":"メールアドレスの変更について答弁がなかったので改めてお願いしたいのと、それから当然毎年４月の小学校、多くの保護者が登録になると思われますね。ですから、確認したいのが、つまり新しい保護者の方々に対して学校現場でどのようにされているかということをもう一度確認したいと思いますので。","respondent":"矢部生活安全担当課長","answer":"先ほど言いました協力者通信を通じまして、メールアドレスの変更があった場合には、当課のほうに連絡をお願いしています。４月入学の保護者に対する対処、新入生の保護者向けの案内をつくりまして、この案内によって新入生の保護者の方へのご協力をお願いしています。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"もう少し能動的な対処をしてみてはいかがでしょうかということの質問と、それから自分の、要するに子どもが卒業された保護者がいらっしゃいますよね。そういう方々についても引き続き協力員として協力していただけるシステムをつくっていけば、毎年毎年自動的に増えていくわけじゃないか尋ねました。","respondent":"矢部生活安全担当課長","answer":"年に１回再登録につきまして、３Ｇに移行した機会ということもありますので、これについては再登録のお願いを一斉にしていきたいと考えております。それと、これにつきましては、こういった方には引き続き協力員としての再登録を今後ともお願いしていきたいと思います。","id":"exchange-090"},{"speaker":"堺委員","kind":"質問","question":"私のほうからは、１７１ページにあります協働推進経費、それから同じく１７１ページのふれあいサポート推進経費に関連をいたしましてお伺いをします。この辺についてちょっと教えていただけますか。","respondent":"伊勢総務課長","answer":"昨年の１０月とそれから１月に区内企業、全部で２０社の方と２回に分けて懇談会をやったんですけれども、積極的なご発言がございました。そして、そういう形で区も参加するような形でこの協議会を今後立ち上げると、こういうような予定にしています。","id":"exchange-091"},{"speaker":"堺委員","kind":"提案","question":"区民提案事業が７件、決算のときにはこの件につきましてどういう成果があったのか、参考までに教えていただけますか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"区民と区が協働で事業を実施することで基本理念の先ほどもおっしゃられましたけれども、品川をつくるということを目的としてやっているものです。","id":"exchange-092"},{"speaker":"堺委員","kind":"質問","question":"そういう中で、その労苦にこたえるというんでしょうかね、いろんなところでこうした人たちをたたえていただければありがたいなと。こういう思いで、もう一回この辺について顕彰の仕方といいましょうかね、教えていただけますか。","respondent":"秋山協働・国際担当課長","answer":"先ほどご紹介があった介護の支援の仕組みですとか、こちらの方々がこういう活動をして区民との協働を進めているんだということを多くの区民の方々に周知をして、この活動の団体の方がもっと活性化するような形でやっていきたいというふうに考えてあります。","id":"exchange-093"},{"speaker":"堺委員","kind":"質問・要望","question":"今年の２月３日、午後１時半から区役所の第３庁舎６階の講堂でふれあいサポート活動体験発表会というのがございました。先ほどと同じように広くＰＲをしていただきたいなと思うんですが、出席されたときの感想と今後の対応について、ちょっと教えていただけますか。","respondent":"秋山協働・国際担当課長","answer":"出席させていただいて、それぞれの地区でいろんな活動をされているということを発表いただきました。その中では、聞いていらっしゃる方の感想としては、こういう活動があるんだということを喜んで聞いていただきました。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして２番目として、この二つそれぞれについて、区はどのような見解を持っておりますでしょうか。あわせて、自治体レベルで動きが広がっている中、国待ちにせず、区としても条例制定を目指すべきだと思いますが、いかがか尋ねました。","respondent":"阿部経理課長","answer":"価格面だけではなくて、施工能力、必ずしも公契約条例によらなければ確保できないというものではございません。３点目の全国的に広がっているという話ですけれども、私承知している限りでは、決して全国的に広がっているというふうには思っておりません。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問・要望","question":"その大きな一つの指標として、公契約条例の動きがあるわけですから、そこの認識はぜひ改めてほしいと求めました。実際どうなっているか、私は野田市長のような姿勢こそ市長としてあるべき姿だと考えますが、いかがか尋ねました。","respondent":"阿部経理課長","answer":"先ほど委員からもご紹介ありましたけれども、野田市でもこれは基本的には国の問題だ、公契約法の問題だというふうに述べているわけですね。国で解決すべき、全国一律に解決すべきことだというふうに思っておりますので、これが区の見解です。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこの違いというのは、私は野田市の姿勢こそ今求められるべきだというふうに思って、ぜひその立場に立っていただきたいんですね。こうした品川区としては現状としては公契約条例の制定の必要がある、こうした実態が存在するとお考えなんでしょうか、いかがか尋ねました。","respondent":"阿部経理課長","answer":"私どものところにそういう事例がございませんので、私どもとしてはそういうことはない、そういう法律違反はないというふうに思っております。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"それがあるんじゃないかと言っているわけですから、じゃあないと言うんだったら、ぜひ調査を求めますけどもいかがでしょうかというのが１点。生活保護基準のはるか下ですから、品川区としては最低賃金を下回らなければいい、問題ないというふうにお考えなんか尋ねました。","respondent":"阿部経理課長","answer":"先ほど申し上げましたとおり、私どもにはそういう実態が届いてございませんので、調査をする考えはございません。全国の賃金をどういう法律でやっていくか、これは極めて国の問題ですので、私どもとしてそういう認識です。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"去年の５月に公布されたものですが、必要な施策を講ずるように努めるものとする」とありますが、努めないんですか。品川区はこの国の公共サービス基本法を何だと考えているんですか、何かやらないんか尋ねました。","respondent":"阿部経理課長","answer":"公共サービスを確保するために、だからこそ先ほど申し上げているような施工能力がどうなのかという面を含めた総合評価を実施しているものです。その結果として最適の業者を選考していて、それで公共サービスを提供しているというふうに考えております。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"もう一回お伺いしたいんですけど、労働者が、人間らしく働けるような労働環境があって初めてそれというのは実現されるものなんじゃないでしょうか。待遇の改善なしに、私は公共サービスの質の向上はあり得ないと思うんですけども、区のお考えをお伺いします。","respondent":"阿部経理課長","answer":"私どもとしては、先ほどから申し上げているように、品質の確保というのは価格と同時に作業能力を含めて審査をしております。不当に安い価格をお支払いしているという考えはございませんので、その結果として働いている方も十分満足して働いているというふうに思っています。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ孫請け、下請け、実際に労働者にどういう環境が整っているのかぜひ見て調査していただきたい。公契約条例の制定を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"本間委員","kind":"質問","question":"最近の相談の件数について、およそで結構ですから、増減はどのようになっているでしょうか。話し合いは１回３０分ということで、税金相談等はなっておりますが、ほかの区民相談については時間等の制限があるのかどうかについてお尋ねします。","respondent":"中川原広報広聴課長","answer":"スタッフの増員はということで、今の稼働率を見ましても、８０％から９０％でやらせていただいていますので増員の予定はございません。区民相談員の時間ですが、専門相談員ではない、毎日行う区民相談につきましては、基本的には時間の制限はございません。","id":"exchange-102"},{"speaker":"本間委員","kind":"質問・要望","question":"やはりお清めの場所の３階のところですが、お清めをどうぞと勧めても、なかなか入らない。周りの役員さんの要望では、テーブルを用意できないかということがありますので、この件についてお答え願います。","respondent":"梶戸籍住民課長","answer":"例えば平成２０年度に畳の表替えをしたりとか、あるいは腰の悪い方には座いすをご用意したりとかしています。ただし、今後またいろいろなご意見を聞いてまいりまして、今後の改修とかそういったものについては検討材料とさせていただきたいと思います。","id":"exchange-103"},{"speaker":"本間委員","kind":"意見","question":"次に、２０７ページ、統計調査費の部分です。その件につきまして、その受けとめ方と今回改善をする中身について午前中も少しいただきましたけれども、その内容についてお知らせくださいとの意見を述べました。","respondent":"中山地域活動課長","answer":"手渡しで説明の上、３度ほど訪ねて会えなければ、ポスティングをしてもらって結構である。それから、細かく言えば封書等もプライバシーを確保してしっかりととめて出していただけるような形に改善する、このような内容です。","id":"exchange-104"},{"speaker":"本間委員","kind":"質問","question":"今、３度やってだめだったらというお話を聞きましたものですから、新たな取り組みの部分でご配慮されたと受けとめておきたいと思います。これまで２０年間にわたる歩みがあるわけですが、ポイントであるということがございましたら、幾つか挙げていただくよう求めました。","respondent":"中山地域活動課長","answer":"やはり距離的に遠いということがあり、広がりという面ではなかなかアクセスの課題というのがあるというのは一つあろうかというふうに思います。事業を超えて差し入れがあるとか、これは本当に早川ならではの交流があるというのは、一つここの町との交流の特徴かなと考えています。","id":"exchange-105"},{"speaker":"本間委員","kind":"意見","question":"最近ここ３年目ですが、これからシーズンになりますと、週末あたりでは３けた単位の人が繰り出すというような状況も私どもは把握しております。今後夢のあるような、夢が持てるようなことも含めて一言ご意見、ご感想がありましたらお願いしますとの意見を述べました。","respondent":"中山地域活動課長","answer":"これは町のほうとよく相談してその辺の工夫、レベルアップの可能性があるのかということについても十分協議をしていきたいと考えています。","id":"exchange-106"},{"speaker":"本間委員","kind":"意見","question":"私は先ほど子どもの例を挙げましたけれども、お年寄りですね、高齢者のほうに目を向けてもさまざまな受け皿になり得る素地があるような気がします。あるいはロケーションのあるところをフルに利用できるような今後の力強い前向きな取り組みについて、これからもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"１６９ページの地域活動基盤整備についてお尋ねします。だが、区がその地域に土地を持っていたりなんかして、そういうことの有効活用みたいなことは場合によっては考えられないか尋ねました。","respondent":"中山地域活動課長","answer":"区の公園なんかを地域の防災活動等のためには一定の面積で利用いただいているというのは既にあるわけです。今までいろいろご苦労されて確保している町会との関係からいうと難しいかなと考えていますが、いろんな可能性は検討していきたいと考えております。","id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"町会活動をやるときに、今担当課長がお話のように地域によってうまく活用できるところがあったら工夫をしてあげてほしいと求めました。それから１７５ページ、品川区民芸術祭なんですけども、これはどんな内容で、どんなことをやられるのか説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"こちらは中身といたしましては、そういった発表なども同じ時期に合わせて一体的な実施を図っていきたいというふうに考えております。平成２２年度が初回になりますが、平成２３年度以降も続けていきたいというような、このような内容です。","id":"exchange-109"},{"speaker":"須藤委員","kind":"質問","question":"１カ月公演をやるんだから、１日ぐらい区民の日みたいなのをつくって、こういう年にも一ついいかなと思うんだけども。秋には日本浪曲協会のメンバーがやっぱりきゅりあんでやったり、武士道などいろいろなイベントがあると思うんだけど、そのあたりはいかがか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"文化振興事業団とも連携をしておりますが、北島三郎さんのコンサートにつきましては、７月１日に区民の皆様にご優待をするような形で進めしています。そのほか、そういったものも幅広く視野に入れて検討を進めていきたいというように考えてあります。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問・要望","question":"その人たちと５区以外の利用者としっかり仕切りをつくってもらいたいと思うので、過日議長の報告からは、しっかり伝えてほしいと求めました。１０３ページの国庫補助委託金で、そこだけ、使うほうはこっちで使っちゃっているよということなのか説明を求めました。","respondent":"早津選挙管理委員会事務局長","answer":"これは同じものでございまして、国民投票にかかる選挙人名簿ということで、２０１ページのほうは、東京都の補助金制度のタイトルをそのまま持ってきている関係でこのようになっておりますが、内容的には今申し上げたとおり同一のものです。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"それが３カ月前からということにはならないだろうかということに対してのお考えをお聞きします。これはどういう経緯で協力をこれだけしていただけたものかなというところで、その経緯を知りたいと思います。","respondent":"堀越文化スポーツ振興課長、中山防災課長","answer":"初心者教室として、障害者の方のスポーツ教室もスポーツ協会の指定管理の業務の中で行っているというものです。地域スポーツ推進の事業の中で… 自衛隊に関しましては、昨年職員防災訓練のときに練馬の第１普通科連隊の協力を得まして、そこでヘリコプターの離着陸訓練をやったと。そういうことで… 大変失礼いたしました。","id":"exchange-112"},{"speaker":"西本委員","kind":"提案","question":"方針もいろいろ、議員提案の条例もありますし、やはり障害者というところのくくりもきちっと位置するべきではないかなというふうに思っております。来たのかな、防災フェアを機にいろいろと安全安心というところの啓発をぜひ進めてほしいと求めましたので、お考えを少しほしいと求めました。","respondent":"中山地域活動課長、堀越文化スポーツ振興課長、中山防災課長","answer":"システム上、３か月にできないのかというものは、プログラムを変えればできるかと思います。これはやはり一般利用２カ月前… それが地域スポーツの振興のあり方であるというふうに思っておりますし、そのような考えで進めております。予算書の記載等につきましては… 自衛隊と消防署が離れていたり、出し物とかが離れているような状況にありましたので、少し人数が少なかったと思います。","id":"exchange-113"},{"speaker":"武内委員","kind":"提案","question":"私は１５９ページの結婚サポート事業、それから１８４ページの防災対策費から２点ほどお伺いしたいと思います。こういう提案、要望をさせていただいて、この辺についてどうなっているか教えてほしいと求めました。","respondent":"中山地域活動課長、中山防災課長","answer":"少子化対策の中でいろいろ考えたというのがあるんですけれども、特に３０代の晩婚化、未婚化というのが２倍以上に上がってきていると。こういう中から、区として改めて結婚のお手伝いをする余地があるんではないかということで… 浅野委員にお答えしましたとおり、前向きに検討してまいりますということで、決して後ろ向きになってはございません。","id":"exchange-114"},{"speaker":"武内委員","kind":"質問・要望","question":"昨年の第１回定例会で大体どれぐらいいらっしゃるんでしょうかと質問したら、その上で５年経過したので、またこれもしっかりお願いしたいと思います。じゃあ行政の施策で、ほかの施策に総合的にどう位置づけていくのか、その辺のご見解をお伺いします。","respondent":"中山地域活動課長","answer":"それから平成２１年度、これは年度当初からで、３月上旬までの数値ですけど５７人、合計で１０４人の方がご相談に来られているです。なお、現在月２回の相談をやっておりますけれども、来年度は月１回の相談のほうに切りかえていくという形で見直していきたいと考えております。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"そして１５３ページ、あと１７７ページ、地域センター等管理運営費についてお聞きしたいと思います。これは実際あるかどうかいうことでお聞きしたいんですが、ＡＥＤが必要になった場合には、これは何か対策を考えているかどうか。","respondent":"山岡健康課長、秋山協働・国際担当課長","answer":"ＡＥＤの夜間対応のご質問だと思います。コンビニの運営会社、特に推進する予定はないということですけれども、何らかの形で我々のほうから働きかけていきたいというふうには考えております。 ただし、協会の事業その他について、区は支援をし、助成をしていますし、また公式の訪問団につきましては、区が実施をしています。こういうふうな役割分担で事業を進めているところです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"意見","question":"ならば、区で全面的にやってもいいんじゃないかなと。なぜそこで分ける必要があるのか、そこをもう一度だけちょっと納得できるように説明を求めました。","respondent":"秋山協働・国際担当課長","answer":"繰り返しになりますが、車の両輪という形で、区と協会と一緒になって国際交流は進めていくですし、協会は協会で啓発普及事業、その他広報という事業もやっておりますので、そういう形で役割分担はしっかりしているというふうに考えております。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"何で同じ事業でこういうふうに分けてしまうのかというのは、ちょっと区民にはわかりにくいのかなと思いまして質問させていただきました。続いて、地域センター等管理運営費なんですが、区内にある１３ある地域センターなんですが、区民の相談窓口として活用されているんか尋ねました。","respondent":"中山地域活動課長","answer":"あるいは本庁かもしれないけれども窓口はどうなんでしょうかと、このようなご相談が出ておりますので、そういう意味では一定の相談の役割も果たしていると考えております。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"区役所と地域センター間の飛脚便というんですかね、できるだけ多くの相談、申請業務を行うような私はシステムを構築すべきじゃないかな。は電話で対処するとか、そういうようなやはり品川区も区民サービスを私はやるべきだと思うんですが、その辺についてお考えがありましたら。","respondent":"中山地域活動課長","answer":"そのこと自体もある意味では各所管への取り次ぎといいますか、それを身近な窓口としてやっているという部分があるわけです。これはスキルの問題、体制の問題がありますけれども、いろいろ状況に合わせた対応ができるような努力はしていきたいと考えております。","id":"exchange-119"},{"speaker":"須貝委員","kind":"意見","question":"ご自宅に商品を届けるとか、とあるチェーン店では、ビール１本でもお宅に届けるというような仕組みを構築しております。終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"２項地域振興費、１目地域活動費の中の１６９ページ、改めてお聞きしたいと思います。上限、合計１,８００万円まで補助金が上限出ますよという形になっていますけれども、どれぐらいを考えているのかお聞きしたいと思います。","respondent":"中山地域活動課長","answer":"葬祭が可能な場合は５００万円増額、それからいわゆる準防火地域の対象の場合は３００万円増額、最大２,０００万円まで補助ができる。こういう場合には２,０００万円まで区が助成できますけれども、町会のほうで２,０００万円ご負担いただくと、こういうことになるわけです。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"マンションを購入できるということになると、町会会館をつくりたいというところが増えると思います。昨年は３,３００万円でしたかね、どこかに２件ぐらい会館をつくるという予定があるんでしょうか、その辺をお聞きしたいと思います。","respondent":"中山地域活動課長","answer":"２,０００万円程度の助成であっても、３件ぐらい出れば６,０００万円を超えるということがありますので、想定としては建築が３件ぐらい出てくる。これは具体的な予定が、その件数があるわけではございませんけれども、申請に耐えられるよう予算化したものです。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"予算の立て方として、これからたくさん出てきた場合には補正という考え方もあるわけですから、何となく予算の立て方としてはおかしいと思うんですね。まして、景気が悪くて大変だという中で、ここにじゃぶっと３,７００万円余分にあるような気がするんですが、その辺の考え方はいかがか尋ねました。","respondent":"中山地域活動課長","answer":"全く予定がないということではございません。しっかり助成をしていきたいという一つの意思のあらわれというか、意思も含めて予算を組んだですので、よろしくお願いいたします。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問・要望","question":"相談を受けているというので、まだまとまっていないからというふうに理解をいたします。次は、地域食事サービスですけれども、１,４７２万６,０００円、この事業内容というのはどうなっているのかお知らせほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"それから夏期の休業中、それから夕食の配食に関しましては区内の商店から夕食をお配りしておりますので、その辺の委託料というのが主な内容です。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"これは区内在住の６５歳以上の外出、調理が困難な高齢者を対象にボランティアの協力および区内業者を活用して、週２回学校給食等を配食するというふうになっていますけれども、これの対象人数というのは６５歳以上の外出、調理が困難な方、高齢者、どれくらいいるんか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"それに該当する方の総数というのは、ちょっと私どもでは把握はしてございません。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"堂々とこういうふうに地域食事サービスと項目を挙げてやっていますけれども、これはどういうことなんだろう。あるいは、その中で希望者だけだからこんな数になっているんだろうか、その辺、ちょっとしっかりとお答えほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"配食につきましては、高齢者福祉課等で在宅介護支援センターを経由して行っているサービスもあります。民間のサービスもありますので、私どもの地域食事サービスだけということではなくて、全体の中でサービスが行われているというふうに考えてあります。","id":"exchange-126"},{"speaker":"松澤委員","kind":"質問","question":"６,８５４万８,０００円、年次改革をやっていると思うんですが、いつごろに備蓄が完了するんでしょうか。それを聞きたいと思います。","respondent":"中山防災課長","answer":"１０万人を超えるというような状況にありますので、ここにあります６,８００万円はアルファ化米だとか、高齢者用の簡易トイレを買い始めてあります。総計しますと６,８００万円以上になるです。","id":"exchange-127"},{"speaker":"川西委員","kind":"質問","question":"１７３ページ、それからもう一つ質問したいのは、安全安心でよろしいんでしょうか。これだけの金額を増やしていただいたんですから、ビデオですか、そういう質問をいたします。","respondent":"榎本人事課長、矢部生活安全担当課長、冠木指導課長、諸石交通安全担当課長","answer":"それから、食育については、健康づくりという観点から食育の対応ということで幾つか入れてあります。もしくは個別栄養相談… それと帰宅時間、それから昼の時間ということで、この時間帯については今のところ変更する予定はございません。現在検討中なんですけれども… 自転車の乗り方についての指導ですけれども、すべての小学校で区内の４警察のご協力をいただきまして、自転車の乗り方の指導の授業をしています。","id":"exchange-128"},{"speaker":"川西委員","kind":"質問・要望","question":"入り口に喫煙所を設ける、そういうような予算を使っていただきたいというふうに思います。マナーというのは、やはりいろんな方に守っていただく、そして研修していただくということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区と区民１人ひとりの芸術活動の関係についてを中心に伺いたいと思います。行政の役割をどう考えているのか、今回の芸術祭にどうそれが反映するのか、ご説明ほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"支援などをつなげて文化芸術の振興を図るとともに、これらの活動を地域のにぎわいにつなげていきたいというふうに考えております。そのような形も一体的に運営をしまして、そのようなにぎわいづくりという観点で進めていきたいというように考えているところです。","id":"exchange-130"},{"speaker":"中塚委員","kind":"質問・要望","question":"楽しさ、区民の中にどういう状況があるのか、どういう実態があるのかというのをどう理解しているのか伺いたいと思います。先ほどコンサートの話がありましたけれども、そこの仕組みづくりにどう生かされているのか、少し具体的にご説明ほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"それからお仕事の都合ですとか、そういったさまざまな事情の中で、なかなか参加できないというような部分があります。そういった機会を広げていくような、そういう考え方で芸術祭を進めていきたいと、このように考えているところです。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"なかなかそういう機会がかなわない人、こうした区民の参加位置づけをどう具体化していくのか、どう保障していくのかというところが大事だと思います。７月１日ですか、権利としての文化芸術・スポーツをどう保障していくのか、その具体的な位置づけをご説明ほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどご説明させていただいたとおりでございまして、健康状態ですとか、そういった形の間口を広げていくというような形で考えてあります。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問・要望","question":"クラシックやポピュラーやジャズ、いろいろプレス発表にもありましたけれども、料金設定というのはどういう形になっているのでしょうか。所得が少ない人も、その具体的な中身が見えないので、ぜひそこは説明してほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"コンサートの料金設定というお話がございましたが、コンサートの料金設定については当然のことながら適正な料金設定という形で考えております。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区の文化振興事業団について伺うんですけれども、品川区はどういう役割を求めていくのか、その姿勢を伺いたいと思うんですね。指定管理者の更新も近づいていると伺っているんですけれども、今後どのような事業を求めていくのかご説明いただけますか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"そういった講座の展開ですとか、そういったこと、品川らしい特色を持った展開も考えているというふうに聞いております。これが財団の設立の目的ですので、これに寄与するようにいろんな事業に努めていただく、これが大事であるというふうに認識しております。","id":"exchange-134"},{"speaker":"中塚委員","kind":"質問・要望","question":"区として何を求めていくのかという姿勢を明確にする必要があると思うんですけれども、とても所得の少ない人にとって、私はとても思えません。どのような姿を事業として求めていくのか、区の姿勢をご説明いただけますか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"財団のやっているカルチャー講座とほかの民間の講座等を比べますと、決してそのようなことはない、適正な料金であるというふうに認識しております。それが区の役割であり、また文化振興事業団の役割ではないかと、このように認識しています。","id":"exchange-135"},{"speaker":"中塚委員","kind":"質問・要望","question":"で所得の少ない人にとっては１万２,５００円や２万２,０００円や、こういう価格が適正だというのは、私は改めるべきだなと思います。それをどう保障していくのか、だれもがに当たらないと思うんですけれども、今後の方向を改めてご説明してほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"それから、何もかも行政や文化振興事業団が安くして何かすればそれでいいというものではないと思います。委員の多くの方からこのような品川の特性を踏まえて、文化・スポーツ振興を図っていくべきだと、このようなご意見をいただいているところです。","id":"exchange-136"},{"speaker":"三上委員","kind":"確認","question":"それからちょっと午前中に山元委員が質問いたしました１８３ページのなぎさ会館と１７１ページの八潮南小学校跡区民活動交流施設活用経費ということ…どうなっているんでしょうか、とりあえずこの２点、お願いします。","respondent":"梶戸籍住民課長、堀越文化スポーツ振興課長","answer":"実は平成４年に建ち上げたときに、あるいは遠くから来られた方が仮泊できるようにという形であそこを和室にした経緯があります。工事が何カ月かかかりまして、今後こういった点については十分に検討して… 八潮の駐車場の件ですが、今八潮南中学校跡と両方あわせた段階で、管理用の車両の部分も含めて１８台程度を想定しております。それと八潮地区、そういった部分とあわせてご利用いただければというふうに思っております。","id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう要望が多くなってきているという現実を考えていただいて、そういう姿勢で臨んでいっていただきたいと、こう思いますよ。自分の身内のところに訪問すると、こういうことも大事なことですから、これは検討してほしいと求めました。","respondent":"榎本人事課長、吉岡保育課長","answer":"職員の研修ですけれども、あくまでも職員団体というのは区とは別の団体です。そういった意味で、新人に対しても別団体だということをきちんと明確になるように入区式の説明会等でも行っているところです。 来園についてお断りをするようにという指示を青少年育成課長、子育て支援課長、そして保育課長の３名連名で出したということがございました。そのことだろうと思います。","id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"同じ仲間内じゃないですか、区の職員というのは。そう思いませんか、どうか尋ねました。","respondent":"榎本人事課長","answer":"職員団体の活動に関しては、制限の特例の条例を設けております。なおかつ、明確に職員団体にも申し入れているところですので、そのルールを守るよう今後徹底していきたいというふうに思います。","id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"もう一つ、職員の研修については、十分そういった点で組合とのことについてもやっていっていただきたい。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"鈴木委員","kind":"質問","question":"その２点でお聞きしたいと思います。２４億６,８００万円、定年退職の方ですから、具体的な数字が出ているというふうに判断してよろしいんでしょうかというのが１点。","respondent":"榎本人事課長","answer":"定年退職者１０５人および特別職の任期満了者３人ということで、あわせて２４億余円を計上しております。定年退職者につきましては、勤務年数等が想定できますので、その積算に基づいてここに計上しているものです。","id":"exchange-141"},{"speaker":"鈴木委員","kind":"質問","question":"当時の記憶がなかったので、増やしていった目的とか、それから数字的には退職金に影響を及ぼしているんでしょうか。そこの２点を説明するよう求めました。","respondent":"榎本人事課長","answer":"課長１３年、部長を４年やると全部で２０年間で、加算額としては約３００万円が加算されるというような形です。より成績主義、実績主義をとるということで、こういう改正が行われたというものです。","id":"exchange-142"},{"speaker":"鈴木委員","kind":"質問","question":"例えば係長の方が再任用になったときは、役職は変わってしまうという形になるんですか、そのまま役職を引き継いでいくのか。そこら辺はどうでしょう。","respondent":"榎本人事課長","answer":"要は５０歳代の職員の比率が多い中で、定年退職が１００名を超えているということなので、係長級の退職が多い時期に差しかかっています。下から来る４０歳代、３０歳代が係長になる人数というのも限りがありますので、係長級の常勤職として残っていただくということが大半です。","id":"exchange-143"},{"speaker":"鈴木委員","kind":"質問","question":"それと、一つ逆の面で言うと、これから係長に育っていただく方が、上が詰まっているよと。どっちがいいのかちょっと私も判断がつきかねているんですけど、その辺で人事課長としてどういうふうに判断していくのか、ちょっと説明を求めました。","respondent":"榎本人事課長","answer":"それと、実は今からかなり前には係長級の合格者が多くて、どういうポストをつくっていくかという時代があったのが２０年ぐらい前だと思います。","id":"exchange-144"},{"speaker":"鈴木委員","kind":"質問","question":"立ち上げ、例えばペーパーかなんかで残っているのかもしれないけど、基本的な思いというのは伝わっていくのかなというのが私は懸念しています。ですから、どう考えていったらいいのかなというのは、その辺は事務事業評価を進めていく上で考え方を説明するよう求めました。","respondent":"久保田行財政改革担当課長","answer":"施設、今委員からもお話が出ましたように施設の当初の設置目的というものがありますので、これはこれで必要があって施設を設置したものですから。","id":"exchange-145"},{"speaker":"鈴木委員","kind":"意見","question":"施設はわかります。それと同時に、品川の政策として施策事業を展開していく中で、その事業の展開についてどう考えていくのか、そっちのほうが私は気になるんですけどとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"今施設のお話をさせていただきましたけれども、政策の面におきましても同様な形で、やはり当初の目的は尊重しながら、継承していきながらも、その時代に応じた、時代の区民ニーズに応じた形で施策も柔軟に対応していきたいというふうに考えているところです。","id":"exchange-146"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最初に立ち上げたときの担当の方の思いもあると思うんですよね。ちょっとその辺が気になっているところなので、うまく伝えていっていただきたいなということをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":122464,"voices":374}},{"id":"h22-20100311-3","meetingId":"h22-c-budget","date":"2010年3月11日","dateIso":"2010-03-11","committee":"予算特別委員会","time":"午前１０時０２分～午後６時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"私から２１５ページの地域福祉計画の改定、まずこれを伺いたいと思います。それから、経費が約１,０００万円ということなんですが、この内訳を教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"平成２２年度で終了です。今後の予定では、地域特性に合わせた仕組みということで、今回はつくってまいりたいと思っているところです。","id":"exchange-001"},{"speaker":"山内委員","kind":"確認","question":"民生委員、地域の福祉というものを計画していくということで、確認の意味でこれは質問させていただきました。今まで培ってきたものをどこか手直しをする部分があれば、そこを手直しをしていくというような形での認識でよろしいのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"助け合いと支え合いを進めていくということには変わりありませんが、先ほどございましたような、さまざまな地域の課題が増えています。それから助け合いということについては、社会福祉協議会の活動計画を含めて、変わっていないです。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、同じく２１５ページの紙おむつの支給についてを伺いたいんですが、紙おむつの種類が４種類支給をされておりますね。これは決まっていますけれども、その辺は、先ほど申し上げたように、人それぞれだと思うんですけれども、それについて伺いたい。","respondent":"冨岡高齢者福祉課長","answer":"２カ月に一遍でいいとか、そういうところの部分はまとめてお渡ししている。連絡をいただければ、そういう形で柔軟に対応しています。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"月１回必ずということだったのかなと思ったんですが、そういう要望にこたえていただけるということで、それはそれでいいと思います。台数等々の数を伺いたいというのがあるんですけれども、こういう意見もあったということを聞いておいていただきたいんですが、確かに高額なんですよ。","respondent":"安井子育て支援課長","answer":"こちらのほうについて、主体はシルバー人材センターのほうなんですけれども、そちらのほうへ助成をしていこうという考え方です。何台かですけれども、初年度については１５台を予定しております。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"なぜこれを質問するかといいますと、用紙１枚が、私はすごくいい事業だと思うんですね。ちょっとここはどうかなというのがあるのは、この事業に対して品川区としてはどのように周知をしていくかというところを伺いたいと思います。","respondent":"平澤生活福祉課長","answer":"ハローワークでやっているのは４つの事業がございまして、例えば委員がお話しになりました就職活動困難者支援事業、離職ということがあります。ご指摘の内容につきましてはハローワークに伝えたいと考えています。","id":"exchange-005"},{"speaker":"金野委員","kind":"提案","question":"こうしたときに、町会の会館へのこうした地域の協力要請をしていただく体制は、今現時点ではどのようになっていますでしょうか。今後こういったところへの支援体制というんでしょうか、このように提案をするものですが、ご見解を伺いたいと思いますとの意見を述べました。","respondent":"中山防災課長","answer":"もしそこを使わせていただけるのであれば、使わせていただくということで、支援物資等もそちらのほうへお運びするということは可能です。それがなかったら、ソレイユ戸越のほうに避難していただくと考えています。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問・要望","question":"こういった例も多分これからもあるのではないかなと思うので、ぜひそういった対応の協力要請、あるいは支援もお願いできたらなと要望をしておきます。保育施設が整ったところであるならば、やれるかなという人はいるのではないかなと考えるんですけれども、いかがか尋ねました。","respondent":"吉岡保育課長","answer":"今後形としては、ご家庭で保育をしていただく。自宅以外の場所での保育ママ的なものができないかどうかについても十分検討していく必要があろうかと考えているところです。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"例えば乳幼児ですから、３歳ぐらいまでのお子さんですと、やはりお風呂場も多分使うことが多いと思うんですね。そういったところでの、何か具体的にもうお考えであれば、教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"新しい仕組みを再構築する場合も、その辺、十分に配慮しながら進めていく必要があるのかなと考えているところです。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"レンタルの手続、簡素化というんでしょうか、簡単に皆さんが借りられるようなシステムをよろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは２２４ページから始まります障害者福祉につきまして、その支援策を中心にお伺いしたいと思います。改めてどういった課題だと認識しているのか、今どういう検討状況なのか、ご説明ほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"障害者を介助しています家族の高齢化というのは重要な課題ということで十分認識しています。来年度検討ということで、在宅の支援を強化していかなくてはならないかということで、その中でさらに検討を進めていくという状況です。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのためにはどんな支援が必要なのかというのを伺いたいなと思います。悲しいという思いをどう受けとめていらっしゃるのか、基本的な理念をご説明ほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"そういう中で、在宅生活を支えるということでは、まず、昼間については施設の通所をするということが１つあります。さまざまな在宅支援もありますので、今生活支援センターということで、相談していただければと思います。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"親もずっと子どもと接することはできませんから、そこの不安にどうこたえていくのか、どう理解しているのか伺いたいなと思います。グループホームへの体験入所ができる、こうした検討が私も必要ではないかと思うんですけれども、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"１人でまず最初宿泊できるのか、どうなのかというところから、ショートステイを利用なさるとかというところの段階的なことが必要かと思います。それと体験ルームということで、そういうところをご紹介しながら体験ルームを利用し、グループホームにということになるかと思います。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際は将来的には１人で生活をしていくわけですから、１カ月なりのそういう体験の入所が必要になってくるのではないかなと思います。１カ月間という体験ができるグループホーム、そういうのをしっかりと検討していく必要があるのではないかと思うんですけれども、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"私どもの相談の中で、どういう形でその方を支援していったらいいのかということで、その辺は家族の方を支援してまいりたいと思います。２度の方も、そういうことでは親の支援がかなり重要でして、その辺については障害者一人一人の状況に応じて支援してまいりたいと思います。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後どういう方向を考えていらっしゃるのかお考えを聞かせていただきたい。しっかり１カ月間、体験ができるような体験グループホームの整備が必要だと思うんですけれども、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"それぞれの障害の人がどういう支援が必要であり、ご本人の状況、それぞれの方の状況に応じてサポートしていくのが必要かと思います。一人一人の状況に応じて対応してまいりますので、ケアマネジメントを進めさせていただきたいと思いますので、よろしくお願いします。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、今の２所という、この状況で十分なのかと。こうした仕組みは、障害者、親の当事者参加で意見を聞きながら進める必要があると思うんですけれども、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"最初、体験ルームに入る前のケアマネジメントということで、ご本人の状況、家族支援がどうなのかというところが重要かと思います。その辺も含めまして、家庭生活のところから支援してまいりたいと思いますので、よろしくお願いします。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"規制緩和と言ったらいいんでしょうか、品川区では今後、軽費老人ホームについてどのようにお考えでしょうか。ほかに方法があるのなら教えてほしいですけれども、足りない分というのをどう考えているか、説明を求めました。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長、高橋障害者福祉課長、吉岡保育課長","answer":"けがのないような形で実施しているですので、運動というのは継続してやっていくことに価値があると思いますので、その後は。… どういうふうに考えておるかということだと思いますけれども、これ以上介護できないというときに、特別養護老人ホームと。ご指摘の部分につきまして… 森前のグループホームの入所の件ですが、１４人の方の中から６人、それと補欠ということで決めさせていただいている状況です。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問・要望","question":"それから、グループホームは、選考の基準について聞いたのではなくて、公募したかどうかについて伺ったので、それを端的に教えてください。まだ建物が新しければ、ほかに転用できるような形できちんと受け皿をつくっていくという発想も必要なのではないかと思って伺いました。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長、高橋障害者福祉課長、吉岡保育課長","answer":"それぞれ地域のほうに出てそういう運動が手軽にできるようになるというのが目標になっております。将来的にはボランティアになって… 現在このモデルを使って、計画していく、あるいは対応していくということについての考えはございません。従来から私どものケースワーカー、福祉士等にご希望があった方等を含めまして、１４人の方に対して選考したものです。","id":"exchange-017"},{"speaker":"阿部委員","kind":"質問","question":"１点、西大井のグループホーム、知的障害者の特性を勘案して、公募していないということなんですけれども、やはりこれは公募すべきだと思います。やはり行政なのですから、入った方の気持ちからいっても、そこは手続を踏んでいくべきだと思います。","respondent":"高橋障害者福祉課長","answer":"公募ですが、知的障害者の状況を、従来から私どもに寄せられている希望を踏まえまして、今回やったものです。公募の件につきましては今後検討します。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"２１３ページ、ホームレス対策、それから２５８ページ、民生費の中の扶助費ですかね、特に母子加算、その辺を関連してお聞きしていきたいと思います。ですから、品川区で具体的に特にとっているような方法があればお教えいただきたいんですけれども、。","respondent":"平澤生活福祉課長","answer":"去年の２月が３５人、去年の８月が４４人でございまして、今年のデータは、ちょっと申しわけございません。ただ、圧倒的に男性だです。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"全体的にお聞きしたいのは、これは約１００億円に近くなってきております。その辺のお考えと、１００億円近くになってきているという、この扶助費についてお話をほしいと求めました。","respondent":"平澤生活福祉課長","answer":"平成２０年度が３,３５３、平成２１年度が、平成２２年の２月なんですけれども、３,７９０ということで、１３％増えております。扶助費全体としましては、１７％強増やさせていただいているですが、これは来年度の増を見込んだ数字ということでお願いしている次第です。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"質問的には、担当セクションだけではなくて、すいません、その辺をお願いできればと思うんですけど。","respondent":"金子企画財政課長","answer":"国から４分の３の国庫支出金がありまして、区からは４分の１ということですので、４分の１のプレッシャーかなと感じています。当然私どもも対応しなければなりませんので、全体的な工夫をしながら、これに当たっていきたいと考えています。","id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたら、次に、母子加算についてお伺いいたします。その辺のところの２点についてお聞きできればと思うんですけれども、いかがでしょう。","respondent":"平澤生活福祉課長","answer":"国全体のご判断ということで、私どものほうでなかなか意見が言いづらい部分ではあります。自立の援助につきましては、私どものほうで就労支援の相談員、できる方にはできるだけやっていただくということを指導してまいりたいと考えています。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、その辺の受けとめを、十分に両方の意見を聞いて、今後の対処をしていっていただきたいという考えでおります。ですから、これは国のもともとの基準なのかもわかりませんけれども、品川区として父子家庭についてどう思われているかを一言ほしいと求めました。","respondent":"平澤生活福祉課長","answer":"初めに、私どものほうで、母子加算という名前なんですけれども、母子家庭というふうに誤解を受けてしまう名称、ネーミングなんですが、対象児に当たる父子のところにも出ております。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"そういう言い回しの部分が出てくるものですから、その辺についてお聞きしたかったものですから、今後もよろしくその辺のところをご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"去年立ち上がった３課の下に、保育園をまず地区割にした大きな大前提みたいなのが何かあれば教えてほしいのと、デメリットみたいなもの。今回、船頭がたくさんになっちゃっていないか、指示系統が複雑になったりしてないかという部分についてお教え願えますか尋ねました。","respondent":"古川子ども未来事業部長","answer":"最終的には品川区の方針をそれぞれの所管する保育課、あるいは子育て支援課が、児童センター、保育園を集中的な形で、一定の方針を持っていく。平成２２年４月から児童センターも含めた、この組織をよりわかりやすいものにしていきたいな、こう思ってあります。","id":"exchange-025"},{"speaker":"渡部委員","kind":"確認","question":"その確認と、行政から何か出る文章については、それぞれの保育園に対して課長名で出ることがあるのか。その辺の確認、２点お願いします。","respondent":"古川子ども未来事業部長","answer":"もう一つは、３つの課がそれぞれまた対応できます。地域における施設、そして３つの窓口、最終的にはそれぞれ所管する保育課、児童センターであれば、子育て支援課、そういう形になっています。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"後先になってしまいますが、２４５ページの病児保育についてお伺いします。昨年の７月に２カ所目の病児保育、利用数というんですか、教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"それから、利用の数ですけれども、２月の末の数字ですが、２月末までで延べ人数２３４人のご利用をいただいているところです。地域別の分析まではまだしてございませんので、申しわけございません。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"知っていますかと何人かの人にお聞きしましたら、周知の方法をもう少しご努力をしていただきたいなと思いましたので、この辺を要望します。２,０００円かかるというのは、何で２,０００円になったのかを教えていただきたいんですけど。","respondent":"吉岡保育課長","answer":"はしかですとか、そのようなものについて、ご利用はご遠慮いただいているところです。それから、料金、これは一応区でやっていますほかの施策です一時保育なんかと横引きの１日２,０００円という値段になってあります。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"実はこれも実際の話なんですけれども、お住まいは大田区で、お仕事は品川区にあると。お仕事は品川という、その方たちは、こういうところの病児保育に預けることというのはいかがなんか尋ねました。","respondent":"吉岡保育課長","answer":"考え方としては、基本保育にさらにつけ加えた付加のサービスですので、基本的には区内在住の方ということで考えているところです。大田区にも、病児保育をやっているところがありますので、そちらのほうなども適宜ご利用いただければありがたいかなと思っているところです。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"今、２,０００円のお話も伺いました。やはり利用なさっている方は、その辺の２,０００円というのをお考え直す、また変更するようなことというのはございませんか尋ねました。","respondent":"吉岡保育課長","answer":"利用料につきましては、現在のところ見直す予定はございません。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"場所が１つはキッズベル品川は戸越のほう、そして今回の酒寄医院は東大井二丁目にあります。そうしますと、小山とか荏原のほうにそういう施設がないんですが、何か予定といいますか、何かお考えはありますか。","respondent":"吉岡保育課長","answer":"やむを得ずお子様を預けて仕事に行かなければならない方の受け皿と考えてございまして、あるいはそうなってほしいと思ってございまして、現在の２カ所の体制をどんどん広げていくという考え方は区としては持ってございません。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"では、サポしながわについてご質問します。サポしながわは５５歳以上の方が求職をするわけですけれども、登録されている方の人数ですかね、その辺を教えていただきたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"ちなみに５５歳未満が９％、５５歳から５９歳が２２％。そのような構成です。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"何回か合同就職面接会等開催なさっておりますけれども、参加企業数とか、またそこで成立した、就職が決まったというんですかね、決まった方たちというのは、具体的に人数はおわかりになりますか。","respondent":"福島ものづくり・経営支援課長","answer":"第２回の就職面接会につきましては、１１月に行いました。参加企業につきましては、毎回大体２０社程度で行っているものです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"２２１ページ、その数字をどう分析しているかということと、その辺の数字的なことについてもどういうふうに理解しているか教えてください。２４７ページの保育園の職員についてお伺いしたいんですけれども、今回２次募集をしてまで、その理由について説明を求めました。","respondent":"永尾高齢者いきがい課長、吉岡保育課長","answer":"２割程度というような結果ですが、特定高齢者というふうにご自身のほうでなかなか認めてないという意識もありますので、その辺の把握の仕方について検討していかなければいけないと考えています。さまざまな待機児解消のための施策を検討してまいったわけですけれども、幼保施設と小学校の連携、あるいは保育園と小学校の連携の部分も含めて。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"やる場所があるのですから、その辺も生かしていけないかなという思いがあるので、その辺について教えてください。どういうふうに、どういうふうに生かしていくか、その辺を説明するよう求めました。","respondent":"永尾高齢者いきがい課長、吉岡保育課長","answer":"特定高齢者に対する介護予防というのは非常に重要なものですが、特定の把握の仕方というのが、今やっている方法に多少問題があるのかと思います。ただ、区といたしましては、協働の仕組みを生かしながら、声かけとか、またＰＲするとか… 従来の４歳、５歳は全部幼稚園児という形ではない中での幼稚園と保育園の連携を形づくっていく中で、特色を出していきたいと考えているところです。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"介護予防は期待していますので、この２割がもっともっと数字的にも上がっていくようによろしくお願いします。今後どういう展開をしていくのかということと、それともう１点は、来年の４月に向かってはどのような考えがあるかを説明するよう求めました。","respondent":"吉岡保育課長","answer":"単独の園につきましては、従来からそれぞれの園においても預かり保育を実施するなど、一定の就労のご支援も行ってまいりました。計画どおりの幼保一体施設の中での保育園の新設を含めて、それによらない形のものも含めながら対策は十分考えていきたいと考えているところです。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問・要望","question":"なぜ必要なのか、創刊号の表紙に部長のコメントが出ておりまして、こういう情報を皆さん求めているのかなという気がしました。訪問の方法の確認を伺いたいのと、その中でどれぐらい実際応対できていて、できないのがどれぐらいか説明を求めました。","respondent":"永尾高齢者いきがい課長、安井子育て支援課長","answer":"まずは普及するということからやっていって、その後、またその中からリーダー的なものが出てくるようにできればと考えております。在宅介護支援センターのほうと、あと、何かイベントのときに配布などできればと考えているところです。件数ですけれども、平成２０年度については、全体で２,２８８件で、保健センターのほうが２,０２２件、児童センターのほうが３０４件。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"虐待だとか、そんな事例もある中で、どんなことを想定されているのか。やむを得ないケースもあるのかどうか、最後説明を求めました。","respondent":"安井子育て支援課長","answer":"そういった意味で、育児についての不安であるとか、そういったものをお持ちになる方が非常に多いと聞いております。さらには、すくすく赤ちゃん訪問の際には、その地域の民生委員の方たちに一緒に訪問をしていただいているところです。","id":"exchange-038"},{"speaker":"本間委員","kind":"質問","question":"２２１ページ、２２３ページから２２４ページ、高齢者就業支援についてお尋ねしたいと思います。住宅手当緊急特別支援事業というのが７,７１３万円余という形で計上されておりますけれども、この中身についてお尋ねしたいと思います。","respondent":"平澤生活福祉課長","answer":"大きく分けまして、住宅手当の相談員の人件費、それと、こちらの実際の手当のほうの扶助費、こちらが主なものです。扶助費のほうの金額だけを申し上げますと、６,６００万円ほどとなっております。","id":"exchange-039"},{"speaker":"本間委員","kind":"意見","question":"その中で、今のような扶助費のほうにほとんど使われていた６,６００万円という形でございました。昨年もちょっと触れたかと思いますけれども、この具体的な内容と対象人数についてお知らせくださいとの意見を述べました。","respondent":"平澤生活福祉課長","answer":"こちらにつきましては、まず対象となる世帯数なんですけれども、現在２６世帯ほどあります。自立の支援ということで、そちらの手当、そういったところになっております。","id":"exchange-040"},{"speaker":"本間委員","kind":"意見","question":"世帯数は２６世帯ということで、自立支援のためにそのように国のほうで援助をするということが出ておりましたので、お尋ねさせていただきました。団体や個人、登録者の数について、あるいは、利用者の料金はいかほどになっているのか、そして、利用者の評判についてお尋ねしますとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"実施の回数は年に６回ということで、３９４件でございまして、平成２１年度は１２月末で３１３件です。コンスタントにご利用いただいているというところで伺っているところです。","id":"exchange-041"},{"speaker":"本間委員","kind":"質問","question":"利用者の評判についてお答えがなかったんですけれども、これは全くのボランティアなのかどうかということをお尋ねしたかったんですね。喜ばれているような事業のように聞こえてきましたものですから、今、お尋ねさせていただきました。","respondent":"冨岡高齢者福祉課長","answer":"こちらからは委託費でお願いをしています。ご本人からも半額負担をいただいております。","id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"７,３２０万円ですか、これまではマンパワーの拡大ということで、人材の育成を急いでいる。簡単で結構です。","respondent":"冨岡高齢者福祉課長","answer":"社会福祉カレッジというものを実施しておりますので、今の区の職員のレベルアップ、技術の向上も図っています。","id":"exchange-043"},{"speaker":"本間委員","kind":"質問・要望","question":"グループホーム等々の整備にこれからも品川区は力を入れていくわけですから、人材の確保、取り組みをさらに進めていただきたいと思っています。２２１ページの高齢者生きがい対策事業の中に幾つか事業がありますけれども、そういうのが入っていないのかどうか、お尋ねします。","respondent":"永尾高齢者いきがい課長","answer":"いきいきマージャンのほうは、こちらの表示には表に出していないんですけれども、高齢者の趣味・健康づくり事業の中に入っております。","id":"exchange-044"},{"speaker":"本間委員","kind":"質問","question":"そうしますと、いきいきマージャンの件につきましては、助成的な部分はここに表現されていないんですか。ほかにあるんか尋ねました。","respondent":"永尾高齢者いきがい課長","answer":"予算上は５万３,０００円ということで、登録カードの用紙代と郵送料ということで、あとは、すべて日本健康麻雀協会のほうでやっていただいているという状況になっております。","id":"exchange-045"},{"speaker":"本間委員","kind":"質問・要望","question":"８割５分から９割近くが健康な人が多いわけですから、さまざまなメニューを出しながら、ひとつ駆使してほしいと求めました。仕事が本当にないというのが私たちの周辺で日増しに聞こえておりますので、その辺の部分についてのお話を説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"まさにサポしながわなどは、資格を持っている者を民間の企業にあっ旋して、紹介しているという事業を行っております。シルバー人材センターにおきましては、来年度からは就労につながるような学習、そういったものも取り上げていこうと計画しているものです。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"大変大事な部分だと思います。６５歳以上、あるいは５５歳から６４歳までのこの部分は、何かお役に立ちたいという部分がありますものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"それから、続きまして、５２６ページの介護保険の主に介護予防についてお聞きしたいと思います。これについて現状、品川区の対応について一言、現状と対応を確認させてほしいと求めました。","respondent":"冨岡高齢者福祉課長、永尾高齢者いきがい課長、安井子育て支援課長","answer":"新しい課題にどういうふうに対応していくかということと、１３地域の課題を、どういうものか抽出をしていくということが大事かなと考えています。… この介護予防という事業をいろいろ進めたことによりまして、高齢者の中で大分この言葉が定着してきたんじゃないかなと考えています。… 品川区の児童虐待に対する現状と対応ですけれども、こちらのほうで３層構造でやっているんですけれども、子育て支援センター等に入った場合。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"時間がありませんので、端的に質問しますけれども、ここら辺、例えば地域福祉計画、そもそもの対象者というのを改めて伺っておきたいなと思います。平成２２年度に構築をして、新しい地域福祉計画の中に当然反映されていくべきだと思いますけれども、ここら辺の考え方を教えていただけますか。","respondent":"木下健康福祉事業部長、永尾高齢者いきがい課長","answer":"容易に到達することはできないかと思いますけれども、このことを今回出発点にしていくことが大事じゃないかなと考えています。これらの方々を中心にこの部分についてをまとめていくということを考えているです。 足の筋力を高めて、筋力をつけることによって、骨粗しょう症の予防にもつながるというようなものだと聞いております。","id":"exchange-049"},{"speaker":"井桁委員","kind":"質問・要望","question":"１目社会福祉総務費の福祉ショップ運営費についてと、２２７ページ、３目障害者福祉費の知的障害者ふれんどりー事業についてお伺いいたします。この事業というのは、私が間違っていたら教えていただきたいんですが、福祉ショップのテルベの経費なのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"これは福祉ショップテルベということで、大井町のイトーヨーカドーのご好意によって、平成９年から開始した、それの事務費ということで補助金を出しているものです。","id":"exchange-050"},{"speaker":"井桁委員","kind":"質問","question":"そこのあたりを１点お伺いしたいのと、平成９年からやられていて、そのあたりをどうお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"ただ、新しい製品を開発して、いろいろな形で現状を維持しているというのが今のところの現状です。それをやっているものとか、いろんな形で努力はしていますが、まだまだというふうには考えております。","id":"exchange-051"},{"speaker":"井桁委員","kind":"質問・要望","question":"都の補助金ということはわかりました。そして利益を上げていくんだぞというぐらいの意気込みで臨んでいただきたいなという思いがあるんですが、強い思いをぜひ。","respondent":"高橋障害者福祉課長","answer":"なかなか１つの製品として一般の製品になるには相当時間がかかるので、その辺については、徐々にということで考えていただければと思っています。それは区としても支援をしてまいりたいと思いますので、よろしくお願いします。","id":"exchange-052"},{"speaker":"井桁委員","kind":"質問","question":"何でしょうかね、働くことの楽しさの１つに、売り上げが伸びてくるというのも１つになってくると思うんですね。１つ疑問に思ったんですけれども、パンは販売されているのはお伺いをしておるんですが、どのようにお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"製品につきましては、１年に１回、施設の側が一堂に会しまして、今年度こういうものを製品として出したい。それについて１年間の売り上げの状況をその委員会に提示しまして、先ほど申し上げましたワゴンセール等を行いながら、徐々に伸ばしています。","id":"exchange-053"},{"speaker":"井桁委員","kind":"質問","question":"区役所内でのその他の商品の販売というのはいかがお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"区役所の中の販売につきましては、毎月、かもめ工房、精神障害者のところが月１回、昼休みを挟みまして、１日販売しています。売店でいろんな製品を販売させていただいています。","id":"exchange-054"},{"speaker":"井桁委員","kind":"質問","question":"売り上げアップのためには、露出、ＰＲというのが非常に大切になってくると思います。販売方法、少しでも売り上げを伸ばしていくという意味では、区役所内の設置というのは前向きに検討というのはしていただけるのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"ネットワーク事業ということで、障害者の施設作業所がネットワークを組みまして、販売の向上ということで検討を進めさせていただいてきたところです。","id":"exchange-055"},{"speaker":"井桁委員","kind":"質問・要望","question":"では、ぜひとも少しでもＰＲという意味では、ホームページ、品川区役所のホームページもあると思いますので、ぜひそこのあたりもリンクができるような形というのもとっていただきたいなと要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"実施計画をこれからつくるということになっていると思うんでけれども、どういうふうな計画の内容になっているのか、伺いたいと思います。昨年９月が入所申請５５０人ということでありましたけれども、３月はどういうふうな状況なのかというところを伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"第１次の総合実施計画の中で、あともう１所、整備検討という形で３年間で挙げさせていただいているです。５５０の申し込みがあって、審査が５３６でございましたが、それよりは下回るという見込みです。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"今、長期計画のところ、実施計画のところでは、整備検討ということで、３年間でつくるということなんですか。そうすると、用地確保をどういう方針でどういう考え方で今進めようとしているのかというところを伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"用地、一定規模の広さが必要であるということで、さまざまな用地情報を提供を受けながら、適地があれば、そういうところを政策化していくということで、整備検討に入っていければと考えていますが、残念ですけれども、現段階では、適地が見つかっていないという状況です。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"私はどういう基準でということを聞いているんですけれども、適地というのはどういうふうに考えているのかということを伺いたいと思います。単独での小規模特養というのはどうも考えていないというご答弁だったかと思うんですけれども、具体的に今、何を想定しているのかということです。","respondent":"冨岡高齢者福祉課長","answer":"大体８０人程度で、大体１,０００坪、一定の特別養護老人ホームとしての運営がしやすいのではないかという判断を持っているところであります。ほかの施設の併設ということであればいいですが、これにつきましても、土地の問題というのはあるかなと考えております。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"具体的に見当がついているのでしょうか。具体的な試算というのはやられたのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"ほかの施設についても大体４,０００とか５,０００ぐらいですので。具体的にシミュレーションの内容については、ちょっと今、申しわけありません。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"相手は、待っている方は、生きている人間ですからね。スピードだと区長は言っているのに、そういうふうになっていないと思いますが、どうか尋ねました。","respondent":"木下健康福祉事業部長","answer":"用地の容積率、広さ等も踏まえて、具体的にどういうものが検討できるのかということをその段階で精査するということになろうかと思います。したがって、漫然と構えているということではありませんので、ご理解をいただきたいと思います。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"質問","question":"結局やれる範囲でやればいいじゃないかということになっていくんじゃないですか。そこのところはどうなんか尋ねました。","respondent":"木下健康福祉事業部長","answer":"そういうようなものも１つの参考になるだろうと考えていますけれども、いずれにしましても、それだけでやっていくのは無理だと考えています。そうでない方と、そういうものを総合的に進める中で、２０２５年を見据えた施策展開を考えていきたいと思っているところであります。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ここのところは重ねて、この１０年間、長期計画の間でどこまで行くのかというところ、目標をはっきりさせてほしいと求めました。そのために、小規模でもつくるという姿勢が必要だと思うんですけれども、改めて考え方を伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"計画化ということについては、この間もお答えしておりますけれども、やはりこれは区民に対する約束になりますから、具体的な目鼻がついている中で計画化するのが行政としては正しいやり方だと考えております。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、そうすると、結局、では、どういう土地を確保するのか。そういう考え方もはっきりしてこないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"策定経費なんかはお伺いしたところなんですけれども、２００３年に策定された地域福祉計画の、達成度と課題をどういうふうに考えていらっしゃるのか。地域センターの副所長を新たに配置をして、ふれあいサポートの強化を図ったと考えていますけれども、この点について評価をお伺いしたいと思います。","respondent":"冨岡高齢者福祉課長、高橋障害者福祉課長、中山地域活動課長","answer":"それからあと、現場でのＯＪＴということで、新規雇用された代替職員の福祉スキルの向上というものを区内の法人へ委託をしてまいります。… ガイドヘルパーをヘレン・ケラー協会のほうに派遣する前提条件としまして、基本的技術がある２級ヘルパーの資格要件を設定しているものです。… 日帰り研修ということで実施しているところでございまして、研修につきましては、昭和５８年から開始しております。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"ヘレン・ケラーのところでもお伺いしているんですけれども、盲導犬と何がガイドヘルパーの人と違うのでしょうかといったときに、地域の状況とか。","respondent":"冨岡高齢者福祉課長、高橋障害者福祉課長","answer":"今回の品川第二地区で、支援安定事業ということで、ボランティアのコーディネーターという形でも社協の職員の配置ということを考えているところです。そういうのも含めまして、地域福祉計画の中で… 安心と安全を任せるということでは、最低限２級ヘルパーの基本的技術を持った人を基本に養成研修を受けた者で進めてまいりたいと考えておりますので、ご理解いただきたいと思います。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"改めて介護ニーズとしてヘルパーの方に看護領域の拡大を求めるという声が多くて、その理解でいいのかどうなのかをお伺いしたいと思います。ひとつこれは、品川区はその認識を持ってこの２つの計画をつくろうとされているのか、確認したいと求めました。","respondent":"冨岡高齢者福祉課長、木下健康福祉事業部長","answer":"日勤、夜勤も含めた人件費的な部分ですので、そういう形の中身であわせて実績について報告をしていただくです。お尋ねの施設との連携という部分では、それは例えば既存の地域センター等の社会資源も生かしながらということになってこようかと思います。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうふうなトータルなところで施設と一緒に検討していく必要をここには盛り込んでいただきたい。区全体で地域福祉を考えるというところに重きを置いてほしいという要望なので、その辺のことについて見解があれば、ぜひお伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"ご指摘のとおりだと思いますので、どこまでできるかというのはありますが、そういう視点で……。","id":"exchange-068"},{"speaker":"山路委員","kind":"質問・要望","question":"２点目が、２２４ページ、障害者福祉費の内部障害者支援についてお伺いいたします。高齢者住宅と住み替え住宅との部屋は全く同じものか、あるいは変えていくのか、この辺について教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"それから、高齢者住宅ですが、実施計画につきましては、今後詰めていくところです。大体２５m2以上という形では言われておりますが、あと、広さの最終的な数字についてはまだこれからです。","id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"大井林町住宅の部屋のことをお伺いしましたけど、私も知り合いから３人ほど相談を受けているんですね。もう１人は、３つの相談があるので、こういう方が入れるかどうか教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"ご指摘の３つの例、在宅介護支援センターを通じまして、それから場合によっては成年後見センターもご協力申し上げて対応する。そういうことで、私ども、受けさせていただきたいと思います。","id":"exchange-070"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっと、私、言葉が足りませんでしたけれども、申し込んで、入るということではなく、条件に当てはまるかどうかということを聞きたかったのです。八潮と密集住宅地域とアンケート調査をやられたということはお伺いしましたけれども、今後そのような経過があったら、教えてほしいと求めました。","respondent":"柏原住宅担当課長","answer":"密集住宅地域におきましては、住宅の建て直しもできないということで、この辺が区の施策として喫緊の課題だということでアンケートをとらしています。","id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"平成１８年第１回定例会と平成１７年予算特別委員会の款別審査でもお伺いをいたしましたが、その後、大変感謝をしているわけです。ハート・プラスマークを増やして、安心して出入りできるようなことを考えていただいてもいいんじゃないかと思いますが、どのようにお考えか尋ねました。","respondent":"高橋障害者福祉課長","answer":"そのうち２つが警察で発行しているものです。この辺の普及につきましては、区内の所管課と検討しながら進めしますので、よろしくお願いします。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"消費的経費ということをお伺いしたいと思いますが、消費的という名目ではなくて、むしろ義務的経費ということで表示をされております。消費的経費と書くには、何か意図があると思うんですけれども、そこのところを聞かせてほしいと求めました。","respondent":"金子企画財政課長","answer":"消費的経費と投資的経費等々に分けていく１つの分類方法ですが、私も勉強中ではありますが、大きく分けてまず消費的経費と投資的経費に分かれます。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"私、今、増減のことを伺ったのではなくて、なぜ義務的軽費……。それは書く上において、品川区の何かお考えがあると思うので、そのお考えは何かということで伺っています。","respondent":"金子企画財政課長","answer":"議案説明会資料のことだと思いますが、ここでは投資的経費が財政の自由度をあらわす１つの大きな尺度ですので、いろんなあらわし方で表現させていただいているところです。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと款が違ったら委員長のほうでご指示いただきたいんですけれども、決算のときにいただく最後の巻末のところに決算状況の一覧表があります。これは全国一律でということでのお話もいただいておりますけれども、ここのところの関係はどのように処理をされているのか教えていただきたいです。","respondent":"金子企画財政課長","answer":"そのときにもご説明申し上げたとおり、消費的経費を使い分けているところがありますので、ご理解いただきたいと思います。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"なぜ私がこれを出したかというと、次の質問にかかわってくるわけでありまして、生活保護ということで、今期、民生費に占める割合は４０％です。今後の見通しと対策について教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"子ども手当に関しては１０分の１０ですが、その他の民生費については、扶助費の部分でどうしても義務的経費という形で出さざるを得なくなります。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、確認させていただきました。３,０００余ということで、２年間、その中に占める割合を教えてほしいと求めました。","respondent":"平澤生活福祉課長","answer":"前年と比較しますと、平成２０年の７月１日が４４８人です。４０人弱増えているところですが、申しわけないんでけれども、わかりかねる次第です。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"根本的に考えていかなきゃいけない時期に、既に遅きに失していると思いますけれども、真剣に考えていかなきゃいけないと思います。今私がお話ししたように、そのようなコメントは区から発したことはあるんでしょうか、教えていただけますか。","respondent":"平澤生活福祉課長","answer":"新聞記事の中身だとは思うんですけれども、将来的な予測ということで、団塊の世代の方が、失礼しました……。雇用対策というのは重要だという意味合いです。","id":"exchange-078"},{"speaker":"川西委員","kind":"質問・要望","question":"これは１つの意見ですから、意見として聞いていただきたいんですが、そういうご相談もありました。この２点を先に伺わせていただきます。","respondent":"冨岡高齢者福祉課長","answer":"個々の場合はわかりませんが、標準でまいりますと、３５名までということで対応していただいているところです。それから、ヘルパー２級の研修について何人ぐらいの予算の見込みですが、平成２２年度につきましては、６０人ということで予定をしております。","id":"exchange-079"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、さわやかサービスのほうなんですけれども、希望する区民の皆様からの要望にこたえられる人数であるかどうか、そこだけ伺います。","respondent":"冨岡高齢者福祉課長","answer":"なかなかうまく充足しているかどうかというところは難しゅうありますが、対応は何とかできているだろうです。","id":"exchange-080"},{"speaker":"川西委員","kind":"質問・要望","question":"ホームヘルパー２級のことなんですけれども、もっと多くの方、就労をしていただくというのを研究をしていただきたいと要望いたします。親育ち支援事業の中身について伺います。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"スムーズに成長していくということを目指して実施をしている中身でございまして、幼稚園で乳幼児教育を実施しているというのが大きな骨格です。もう一つの親育ち支援ですけれども、保育園のＰＴＡと連携をいたしまして、食育。 そして、父親にとっても子育てが重要だということについて理解していただくために実施しています。子どもの成長、１年に３回ぐらいとか、自分がどういうふうに育ってきたかということも振り返っていただこうです。","id":"exchange-081"},{"speaker":"川西委員","kind":"質問","question":"講座に参加したりしておりますが、これは年間計画でホームページ等に掲載されるかどうか、そこだけ伺っておきます。これからもそのように考えていらっしゃるんか尋ねました。","respondent":"吉岡保育課長","answer":"空き店舗活用事業については、内容的には子育ての支援です。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"２５５ページの児童センター事業のうちのチャイルドステーション事業と２２７ページの知的障害者ふれんどりー事業についてお尋ねいたします。その点について、３点でしょうか、お尋ねいたします。","respondent":"安井子育て支援課長","answer":"公共施設での空きスペースについても同様に拡大していくという予定になっておるわけですけれども、そちらのほうに周知を図っているです。それぞれ各課に投げかけまして、場所の確保、設置等の進捗を図ってまいりたいと考えております。","id":"exchange-083"},{"speaker":"高橋委員","kind":"質問・要望","question":"２２７ページの知的障害者ふれんどりー事業についてですが、支援等の形で、円滑に進めていってほしいと考えています。その中でまず１つ目として、契約についてお尋ねしたいのですが、これは競争入札や指名入札が行われたのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"外出支援ということで、移動支援に続いて、真ん中のところをふれんどりー事業として支援していただけるということです。きちっとその辺の状況を踏まえた上で支援できるということで、指定の推薦をあげまして、ここと契約していただけるようにお願いするものです。","id":"exchange-084"},{"speaker":"高橋委員","kind":"質問","question":"ということは、随意契約ということになるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"今のところ随意契約でお願いをするところです。","id":"exchange-085"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、このような形の契約の例というんでしょうか、いろいろなＮＰＯとの契約については、このような例が多いのか。それとも、平成２２年度は区内ＮＰＯ法人との連携を拡大してというところで表現がとまっているんですが、どのような状況なのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"障害の部門では、思春期サポート事業ということで、例えば親の会として、パルレが長年やっていて、平成１９年度にＮＰＯ法人として立ち上げたものと単独で契約している例があります。","id":"exchange-086"},{"speaker":"高橋委員","kind":"質問・要望","question":"ヘルパーの研修のことについてお伺いします。その点、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"研修の件ですが、行動援護というところも含めまして行う研修がかなり厳しいものがあるということで、この金額で行うものです。継続的にずっと続けるものではなくて、今回については、立ち上げ費用と考えていただきたいと思います。","id":"exchange-087"},{"speaker":"高橋委員","kind":"質問","question":"どのような方が想定されていて、何のため、だれのためのコーディネーターなのでしょうか。これも同じなのですが、来年度以降もコーディネーター経費、２人分７９４万円について、継続して支援していっていただけるのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"その方を派遣していくということですので、来年度も状況を見まして、この辺の支援をしていくということはあり得るかと思います。ただ、永続的、将来的にすべてということではございませんので、その辺については円滑に動いた段階では、なくなる予定です。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"とすると、例えば区の元職員の方が派遣されるなんていうこともあるのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"今のところ、予定はありません。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"確認","question":"これは部長にぜひお伺いしたいんですが、確認しますけれども、行政はそのお手伝いをするべきであるということ。それから、その結果として、まずこのことについての品川区の大きな方向性の確認をお願いいたします。","respondent":"吉岡保育課長","answer":"就労支援も含めたさまざまな子育ち、親育ちの支援をしてまいると、そのように考えているところです。例えば幼児保育について、それをそのような意味で、そのようなことのないように十分に注意しながら施策は展開していきたいと考えているところです。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"１つのチラシ、福祉政策全般が見渡せるチラシが１つでもあれば、統合チラシを検討してみてはいかがでしょうかということの質問です。いかがか尋ねました。","respondent":"冨岡高齢者福祉課長、山田副区長","answer":"現在あるかどうかというのも含めまして、多分ないと思いますので、私は把握しておりませんので。では、どういうものをつくっていったらいいのかということも含めまして、課題とさせていただきたいと考えています。福祉全般にわたってということですから、施策の体系を含めて、区民便利帳という形で、まとめはしています。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"それから、２２３ページ、ひとり暮らし高齢者等生活支援に関連してなんですが、これはこの間も質問しました住宅用火災警報器に関連してです。ピンポイントでもいいから、まずは高齢者の皆様方について推進する施策を検討してみてはどうかということの質問ですので、ご答弁をお願いいたします。","respondent":"冨岡高齢者福祉課長","answer":"おかげさまで３,０００件を超える件数までご協力いただきまして、消防署とも町会ともお話をして、進めさせていただいた。年度内まだありますので、目いっぱい頑張らせていただきたい、そういうふうに思っているところです。","id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問","question":"すべての部屋につけなきゃいけないことになっているわけですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"堺委員","kind":"質問・要望","question":"確認をさせてほしいと求めましたが、ここで２２７万５,０００円計上されてありますが、これの事業内容を簡単にご説明ほしいと求めました。最初に、先ほど申し上げましたこども家庭あんしんねっと協議会の事業内容を簡単にご説明いただけますか尋ねました。","respondent":"安井子育て支援課長","answer":"対応については、子育て支援センターと児童家庭相談係のほうで調整等を行いながらやっていっているところなんですけれども、先ほど申しましたように。そういったことで虐待死をなくしていくというような対応を心がけているところです。","id":"exchange-094"},{"speaker":"堺委員","kind":"質問","question":"２月２７日の土曜日、ゆたか児童センターの４階の集会室におきまして、参加をしてまいりました。これの拡充というんでしょうか、こんな感想を持ちましたので、この辺についてご所見をお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"１３地域でそれぞれさまざまな講演会を開くことによって、委員たちの認識を高めていっていただくというようなことをやっているところです。","id":"exchange-095"},{"speaker":"堺委員","kind":"確認","question":"４８時間以内に目視して云々という、さらに連携強化をしていくというお話です。区として検討されているのかどうか、分析されたのかどうか、その辺確認しておきたいと思います。","respondent":"安井子育て支援課長","answer":"江戸川区の件につきましては、そちらを参考にさせていただきながら、それをさらに各分科会等にも流しながら理解を図っていきたいと考えております。報道等を通じて、事件の問題点を他山の石としながら、より虐待防止のために頑張っていきたいと考えております。","id":"exchange-096"},{"speaker":"堺委員","kind":"確認","question":"そこで、さっき品川区としては、起きた事件についてどう分析して、どう対応しようとしているのかということを確認ということで申し上げたわけですね。その辺も含めまして何かご見解がございましたら、教えていただけますか尋ねました。","respondent":"安井子育て支援課長","answer":"さまざまな対応、どうしても具体的に虐待という事実の確認等で、なかなか立ち入りというのが難しい場合もあります。それによって対応を考えていきたいと考えています。","id":"exchange-097"},{"speaker":"堺委員","kind":"質問・要望","question":"こういう思いから、この件について確認をさせていただきましたので、ぜひひとつ万全な体制でお取り組みをお願いしておきたいと思います。「中学生も居場所、よりどころを求め、毎日来館する子もいます。","respondent":"安井子育て支援課長","answer":"児童センターは、０歳から１８歳までご利用できる、異世代交流も図れる貴重な場所だと考えています。特に中高生の方たちの居場所というのが重要になっております。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"質問なんですが、区はそのように思っているのでしょうか。必要なサービスが受けられなくなってしまったような、そういった事態というのは区内で起こっているのかどうか、現状はいかがか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"これは７段階があるわけです。サービスに１割の負担がありますので、適切なケアプランがつくられれば、適切にサービスは提供されるです。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"認定制度が昨年４月に変わったわけですよ。さまざまな問題が指摘されている中で、区はそのような事態があってもいいと思っているのか、ないと思っているのかをもう一度お伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"認定におきましても、サービスのケアマネジメントにおきましても、適切なケアマネジメントがされていますので、そういった形のことはないと理解しております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"この方、Ａさんは、筋力も落ち、６４歳の方ですから、震えも強くなり、むせることが多くなってきた。伺いたいんですが、要介護３から要介護１に下がることにより、受けられる介護サービスにどのような変化があるのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"それが１点ということを申し上げたいのと、要介護３ですと２６万７,５００円、要介護１ですと１６万５,８００円という支給限度額があります。そういう形で、その限度までに介護保険からサービスをお受けになれるという仕組みになっております。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"もっと具体的に聞けばよかったんですが、車いすの利用というのは、要介護３から１になったことによっても認められるのでしょうか。そこはどうか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"要介護２以上ですけれども、個々の内容を判断させていただいて、対応可能の場合があります。そういうふうに扱わせていただいております。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"私が伺いたいのは、本人の状態がほとんど反映されなくなってしまったと思うんですが、このことについておかしいと区は思わないのでしょうか。認識をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問","question":"調査項目自体が、これに皆さんのっとってやるわけですから、なぜか車いすを認められない介護度に判定されるという現象が現実に起きているわけですよ。そこら辺、お伺いします。","respondent":"冨岡高齢者福祉課長","answer":"４月にテキストが出た段階で、さまざまなご意見をいただいて、それで改定ということでなったわけですね。平成２１年度の審査をしているわけでございまして、それに基づいて仕事をしているという意味においては、それは当然正しいと理解しています。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問・要望","question":"それにのっとってやっていますというだけでは、高い介護保険料を払って、なおかつ２０億円以上も介護保険料がため込まれているわけですよ。調査のあり方、よく分析、そして改善を求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"しながわ子育てメッセ２０１０、これは記憶違いだったら指摘していただきたいんですが、これはどういう事業だったでしょうか。協働事業の中のものではなかったのか尋ねました。","respondent":"安井子育て支援課長","answer":"こちらのしながわ子育てメッセにつきましては、在宅の子育てをやっていらっしゃる方たちの支援ということで、本年度についても行われております。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"ですから、それを品川区がバックアップするという意味合いであるならば、ここに載せるのはどうなんだろうなと非常に疑問があります。それに対していかがか尋ねました。","respondent":"安井子育て支援課長","answer":"ご支援というか、協働で立ち上げていくということで。子育て支援という形で、継続的にやっていらっしゃる団体ということで、それぞれの所管のほうで支援をするような形になっていくと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"主体はどこにあるんですかと考えたときに、あくまでも協働事業をやる上では、住民サイドが主体になっていかなければいけないのではないか。この記載とか、せっかくの協働事業という意味合いにならないんじゃないかということを思っているわけですが、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"それ以前から、保育課、あるいは子育て支援課のほうではかかわりを持ってきております。ですから、今後とも私どもはこの団体とさまざまな形で地域における子育て支援の１つの場面を設定していきたい、そのように考えております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今後考えていただきたい区の支援の仕方、どういう形をとると住民の自主的な行動として育っていけるのかということです。それを整理していただきたいなと思いますが、いかがか尋ねました。","respondent":"安井子育て支援課長","answer":"地域の子育て支援センター機能みたいなところで、そういった部分についても、０歳からの子育て支援という形で。お力を子育てにも生かしていただけるような機会に発展していっていただければよろしいかなと期待を込めて事業化を進めたものです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"これからどういうふうに位置づけとして、地域の位置づけとして児童センターはどうあろうとしているのかというのをお聞きしたいことと、それから。今でもかなりあると私は思っていますけれども、継承していくにはどういうふうな考えをされているのか、お聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"これから研修体制もしっかりと敷いて、新人も入ってくるであろうということも含めまして、指導体制をしっかりしていくようなことを考えております。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"１点目は、昨日お聞きしたんですが、こちらでもう一度質問します。１９.７８％もいると言われていますけれども、どれくらいいるのでしょうか、お聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"平成２０年度の実績ですけれども、学校給食の分が１０７人、夕食分が６０人ということで、１６７人です。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"実績じゃないんですよ。この高齢者給食サービスに該当する人数は何人いらっしゃるのですかということです。","respondent":"冨岡高齢者福祉課長","answer":"ひとり暮らし等高齢者の方の数は３万５,５４８名です。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"３万５,０００人もいる中で、この事業を行って、今お話がありましたよね、２００人ぐらいですか、これだけの方たちに給食サービスをしている。では、この人たちをどのような形でチョイスしているのか尋ねました。","respondent":"宮地地域振興事業部長","answer":"当初の計画ですと、全体で４００人ぐらいが本当に食事づくりに困っている人だろうということで、事業そのものはスタートしました。ちょうどモデル実施をしているところですので、今後もっといいやり方とか、把握の仕方ができてくるだろうと考えております。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問・要望","question":"ボランティア給食が２９０円と書いてあるんですけれども、学校給食３５０円、ボランティア給食が３５０円と書いてあります。この点についてお聞きしたいと思います。","respondent":"秋山協働・国際担当課長、宮地地域振興事業部長","answer":"平成２１年度より学校給食に関しましては、昼食３５０円、夕食に関しては４５０円、ボランティア給食については３５０円ということで改定をしております。 ２９０円だったのが値上がりして３５０円に平成２１年度からなっておりますので、統一的にお昼は３５０円、夕食は４５０円という形になっております。失礼いたしました。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"２点目、ほっとサロンです。ほっとサロンとはどういうようなものなのかについてお聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"あるいはさまざまな催し物に参加していただく。そういった場所と講座の提供等です。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"もう１カ所がどこかなということをお教えしていただきたいのと、先日ですかね、何団体か活発に活動していました。その辺の整合性をどう考えているのか、お聞きしたいと思います。","respondent":"永尾高齢者いきがい課長","answer":"グループのメンバーだけではなくて、地域の方のやりたい人すべて応募してやるという、そういう違いがあります。","id":"exchange-116"},{"speaker":"松澤委員","kind":"意見","question":"３点目に行きます。高齢者で希望する方はたくさんいると思うんですが、その辺について説明を求めました。","respondent":"永尾高齢者いきがい課長、秋山協働・国際担当課長","answer":"立ち退き料をもらっている人とか生活保護を受けている方というのは、助成の対象にならないので、そこからは外れてしまいます。平成２１年度の状況を見ると、経済状況の影響もあって、少なくなっているように見えます。 先ほどの金額の件ですけれども、地域振興事業部の事務事業概要につきましては、平成２０年度の実績のほうを記入していますので、平成２１年度の金額を私のほうでご説明させていただきました。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"福祉に対して、一般会計の品川区の総予算は１,３９１億円ということですから、民生費というものが約４０％に当たるわけですね。特に気になるのは、児童に対する予算が５５億円と著しく今回伸びているということを考えますと、企画としてどのようなご見解をお持ちか尋ねました。","respondent":"金子企画財政課長","answer":"子ども手当はご案内のとおり、国費ですので、国策として実施しているものを私どもが受託しているものであります。歳入、歳出、それぞれ工夫しながら今後とも編成してまいりたいと考えています。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"お話は、先ほどからもいろいろ出ていまして、お聞きしております。収入の多い方には、ある程度負担を増やすような考え方も必要じゃないかと思うんですが、その点についてご見解を説明するよう求めました。","respondent":"金子企画財政課長","answer":"基本的には受益者負担という考え方を基本のベースに置きながら、たしか昨年だったと思いますが、上限を上に伸ばした。個々の事業につきまして、そういった所得制限のあり方も考えながら、全体の政策について見直していきたいと考えています。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"約３,８００人ほどの方がいらっしゃるということですが、いろいろ指導したり、相談相手になるケースワーカーは品川区に何人ぐらいいるのでしょうか。そして、その方たちは、全員が社会福祉主事の資格を取っているのか尋ねました。","respondent":"平澤生活福祉課長","answer":"４０人なんですが、うち２人が面接相談をやっておりますので、現実のケースワークをしているのは３８名ということになっております。福祉事務所の職員としてやっているということでありますので、社会福祉主事の資格があるかということになりますと、それはない者もいるです。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"それが今、３８名で、相当の人数が品川区の中にいらっしゃるということですよね。それでいいんか尋ねました。","respondent":"平澤生活福祉課長","answer":"現在、ケースワーカーとしてはその人数ですけれども、そのほかに私どものほうで専門非常勤というのをお願いしています。それから就労を支援する専門員、また心の病といったようなもののご相談に応じる専門員、こういったもののお力も借りながら行っているです。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問・要望","question":"中には社会復帰していただきたい、生業についていただきたい、そういう方たちにも実際対応できる人数として区はしっかりやっていると考えてよろしいか尋ねました。","respondent":"平澤生活福祉課長","answer":"それこそ毎週のように電話がかかってまいりまして、地域の中で比較的安定して生活を送っていらっしゃる方もいらっしゃいます。そういった意味、それから、先ほど申し上げました専門員との連携、そういったところで現在仕事を進めているです。","id":"exchange-122"},{"speaker":"武内委員","kind":"質問・要望","question":"それから２４１ページのこども家庭あんしんねっと協議会と２５７ページの子育て支援センターについてお伺いします。見守りネットワークのほうが１１町会でやられているということですけれども、１２月ですか、教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"１１町会ということで、次の段階で、さらにほかの町会にもお呼びかけをして進めていきたいというところを思っているところです。内容を検討させていただいている… 家庭あんしんセンターの中の子育て支援センターのほうで行っております養育訪問事業ですけれども、あるいは、それで子育ての参考にしていただく。","id":"exchange-123"},{"speaker":"武内委員","kind":"質問・要望","question":"しっかり取り組んでいただきたいと思うんですけれども、定例会のほうで質問させていただいた、なかなか簡単に進んでいかないんですね。今確認したんですけれども、もう１回それについてのお答えをいただきたいのと、具体的なケースで何件ぐらいあったのかということを説明するよう求めました。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"１つどういうふうに詰めていったらいいのかというのは、全般ということもかかわってまいりますが、そういうものを含めて福祉計画の中でどういう形で対応できるかという部分を含めて検討してまいりたいと思っているところです。平成２０年度からの継続が１００件、それから新規受付が９７件ということで、１９７件を対象として扱っております。","id":"exchange-124"},{"speaker":"須藤委員","kind":"質問・要望","question":"２１７ページ、特別養護老人ホーム建設費助成についてお尋ねします。そのあたりを説明するよう求めました。","respondent":"冨岡高齢者福祉課長","answer":"この建設費助成によりまして、７０床のベッドを確保しています。債務負担行為が徐々にどんどん終わってまいりますけれども、引き続きお願いをしていくというところで、この部分については考えているところです。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"ですから、こういう考え方で、区外のほうに老人ホームをつくっていくという考え方はお持ちなのかどうか。債務負担行為があと五、六年で終わってきますので、その件について説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"これは相手方があることでもありますが、現実的にほかのほうからどうだという提案がございませんので、これ限りということで、今のところは考えているところです。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"次に、２１９ページに障害者ライフサイクル総合支援検討委託とあります。新しい事業ということなんですが、これはどういうふうに流れていくのか、ご説明お願いします。","respondent":"高橋障害者福祉課長","answer":"障害者の在宅支援を強化するということで検討を進めします。新たとは言いませんが、やはり障害として支援も必要じゃないかというところも含めまして、在宅の生活を支えるために検討するということで。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"検討委託というのは、委託先はどこかわかっていますか尋ねました。","respondent":"高橋障害者福祉課長","answer":"予算が決定された段階で、それから選定ということになります。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"２２３ページの品川区シルバー人材センター支援事業、今後ずっとシルバー人材センターについては支援していくというか、こういう形がとれるのかどうか説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"シルバー人材センターについてお答えします。今後ですけれども、シルバー人材センター、地域にとって大切な事業ですので、区としては支援は続けていくということで考えてあります。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"予算的にはここにあるけれども、直接的にシルバー人材センターの事業に対して国の補助が減ると、そういったマイナス点は出てくるのか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"実際には、国からの直接補助金が減っているです。さまざまな節約の措置をとっていくということで、何とか耐えていこうということで、来年度は何とかもつかと考えています。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問・要望","question":"２１９ページに介護職員、２２３ページに介護予防事業という表現があるんだけど、介護という言葉はどういうふうに理解していいのかなと。介護という言葉はいつごろつくられた言葉なんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"介護という言葉がいつつくられたか、申しわけございません、私、存じておりませんが、人をケアをする、お世話をするという意味の介護というふうに理解しています。","id":"exchange-131"},{"speaker":"須藤委員","kind":"意見","question":"２２３ページの介護予防事業というのが、こっちはいきいきどうのと、介護予防という言葉は使えるのかねと思うんだけど。そういう日本語があるのかなとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"これは第３期の介護保険事業計画といいますか、その時期に合わせた国の制度の変更で、法律用語にもなっていると理解しています。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど来いろんな難病があったり、こういう施設の振り分けというのは、どういう考え方でそれぞれの法人に託しているのでしょうか。同じ障害者でも、ちょっと違う仕組みで対応してくるんじゃないかなと懸念があるんだけど、そのあたりはいかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"家族のケアマネジメントを含めまして、そういうことを含めて適切な施設なり、適切なサービス事業を受けるというような状況になるかと思うんですが。","id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"２５９ページですか、２４１ページ絡み、この辺のところで扱い等についてお聞かせほしいと求めました。なぜ今回ここに出てくるのかということをお伺いをしたい。","respondent":"吉岡保育課長","answer":"一定の期間契約して預かるような、柔軟な子育て支援になっていますので、今後も継続していきたいと思っているところです。いろんな形も考えられると思いますので、どのような方式で再構築できるのか、今検討しています。","id":"exchange-134"},{"speaker":"土井委員","kind":"質問・要望","question":"そうすると、その余韻の部分を消し取った残りの芯の部分はわかるようにならないんですかということなんです。こういう仕組み、要するに相談も含めて来ているわけですから、そういう仕組みにしてもらいたいと思うんですけれども、その辺についていかがか。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"家庭において３人程度を限度とした、お子さんを預かっていただくような方をお一人お願いをする分の経費ということで計上しています。厳密に言えば、新しい時代の新しい形としては… まずは住民基本台帳のほうであれば、なるべく認定のトラブルというか、そこら辺のところを円滑に進めたい。","id":"exchange-135"},{"speaker":"土井委員","kind":"質問","question":"大変なときには、みんな集まってお母さん同士で何とかしようというのがあったわけですから、そこら辺まで行くかどうかは別として。頼られたのですから、公共の方との間の接触だったら、こちらの中で職務としてやっていただく。","respondent":"本城国保医療年金課長","answer":"補正の中でもご説明させていただきましたが、平成２１年度の補正の中で対応させていただきまして、精算分も含んだ額として表記させていただいているところです。","id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"そうすると、おととしのやつがまざっているということになるわけですね。それがわかりませんかとお伺いしているんです。","respondent":"本城国保医療年金課長","answer":"精算分ということで、内訳は書かせていただいてございませんでしたが、高額医療費共同事業につきましては、１億６,０００万円ほどの精算額、保険財政共同安定化事業のほうは、５億４,０００万円ほどの精算額となっているところです。","id":"exchange-137"},{"speaker":"南委員","kind":"質問","question":"２４６ページの児童福祉施設費について伺います。この定員拡大とはいつから始まったのか、まず伺います。","respondent":"吉岡保育課長","answer":"昭和６０年から昭和６１年比で定員が減になってございまして、その後しばらく平成８年までは、若干微増というようなことを繰り返してございました。平成１３年から定員の増が、例えば平成１３年度は対前年度比３３人、平成１４年が２６人というように上昇傾向に転じたものです。","id":"exchange-138"},{"speaker":"南委員","kind":"確認","question":"そのことを確認したいのと、当時、私立保育園というのは１０園あったんですね。それぞれ合わせて２８７人の定員拡大、平成１８年までの時点で２８７人増えたと、その辺の確認をしたいと思います。","respondent":"吉岡保育課長","answer":"私立保育園ですけれども、現在の園数は、現在１０園です。それから、平成１８年からの状況ということでいえば、年々定員としては、それぞれ四十数人から１００人以上増えているという状況です。","id":"exchange-139"},{"speaker":"南委員","kind":"確認","question":"したがって、違うということを確認したいと思います。その辺についてはいかがか尋ねました。","respondent":"吉岡保育課長","answer":"昭和６２年当時の定員については、３,５１６人ということでありますと、現在平成２１年度の定員が３,５００人ですので、ほぼ同じというのは間違っていないと思うところです。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"本会議の答弁のことを言っているのですから、平成２１年度の数字を持ち出さないでくださいよ。これは区が出されている資料に基づいてですから、５９人上回っているという、その確認をぜひしてほしいと求めました。","respondent":"吉岡保育課長","answer":"平成２０年度の定員は、３,４８５人で間違いございません。","id":"exchange-141"},{"speaker":"南委員","kind":"質問","question":"しかも当時の２２年前は定員割れ、こういう状況ですから、本会議でのそういう答弁は全くひどいなという印象を私は持ちました。そして、在席数も、どのくらい増えているのか、これについても伺いたいと思います。","respondent":"古川子ども未来事業部長","answer":"昭和６０年当時と平成２０年当時の中では、私立も含めた認可保育園という考え方での答弁ですので、何ら間違ってございません。話のすりかえではないか、そのように思っております。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"見て、今の質問になっているわけですから、そこは違うということをはっきり申し上げたいと思います。この関係で見ると、１６１人、定員を超えて入園していると思いますけれども、この点についてはどうなんか尋ねました。","respondent":"吉岡保育課長","answer":"平成２０年度の保育園在席数ですが、平成２０年４月１日現在で、公立が３,６４６人、私立が６７６人、合計４,３２２人となっています。","id":"exchange-143"},{"speaker":"南委員","kind":"質問","question":"私が聞いているのは公立園を聞いているんですからね。何人増えている状況なのかということも聞きましたので、正確に公立保育園の数字を言っていただくよう求めました。","respondent":"吉岡保育課長","answer":"平成２０年度の４月１日現在の公立保育園在席児３,６４６人です。３,４８５人、それから平成２１年４月１日現在の公立園の定員につきましては、３,５００人です。","id":"exchange-144"},{"speaker":"南委員","kind":"確認","question":"平成２０年のときに１６１人を定員オーバーして、在席児数として措置をしているという、このことは確認をしたいと思います。最低基準を見て、余裕があるんだとなっているのか尋ねました。","respondent":"吉岡保育課長","answer":"面積につきましては、一応区の考え方は、日本全国同じですけれども、保育所の面積基準、それに基づいて考えているもので、０・１歳児については１人当たり３.３m2、２歳以上のお子さんについては１.９８m2と考えているというものです。","id":"exchange-145"},{"speaker":"南委員","kind":"確認","question":"定数は３,５００人ですから、この年も２７４人を超えて、定員より超えて保育園に入園を受け入れておられます。どういうふうな保育になっているかということを、詰め込みそのものだと私は思うんですけれども、この点についての見解はどうか尋ねました。","respondent":"吉岡保育課長","answer":"初めに、メジャーではかったですけれども、私、昨年の４月からの着任で、そこまでは承知してございません。基準以上の子どもがいれば詰め込みですけれども、現在はそうではございませんので、そのように考えてはございません。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問・要望","question":"私は２４５ページ、どういう形になっていくのか、お知らせいただきたい。それから、２４９ページの保育園運営費の中で、大規模改修等施設整備、この計画の内容について簡単にお教えいただきたい。","respondent":"吉岡保育課長","answer":"今日現在で９３名の採用を予定していますけれども、保育園の５歳児を小学校と連携をして保育をするような部分等々含めまして、全体で９３名です。この中には、すまいるスクールの欠員の補充ですとか、あと、児童センターの欠員の補充の分も含まれての９３名です。","id":"exchange-147"},{"speaker":"三上委員","kind":"質問","question":"今年の採用人数については９３名ということで伺いましたが、どういう取り組みをしていくかということが最も大事になってくると思うんですね。そういったことについての取り組みについて、短い時間でいいですから、お願いしたい。","respondent":"吉岡保育課長","answer":"こちらはいずれも平成２３年度に耐震改修工事を実施する予定ということで、今、設計をやっているところです。ついては、しっかりした保育スキルもあわせて身につけていくという形で育成したいと思っているところです。","id":"exchange-148"},{"speaker":"三上委員","kind":"質問・要望","question":"１人の保育士が１人の子どもについて、ちょろちょろっと小さい声でしゃべると、その子は落ちついて、またいく。時間がありませんから、ご答弁いただかないで終わりますけれども、この次は決算特別委員会のときにでも、また同じような質問をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問","question":"それと関連して２２３ページのひとり暮らし高齢者等生活応援事業、２２７ページ、２４１ページの認証保育所関係でお聞きします。そこにも考えが及んでいくのか、その点、説明を求めました。","respondent":"高橋障害者福祉課長、市岡総務部長","answer":"自立支援医療のご質問ですが、実態としまして、当初予算で３億２,７００万円でした。それと、ＨＩＶの免疫治療につきましては、外国人の方が増えているという状況です。 配偶者暴力対策基本計画の中では、安心しながわネットワークという、そういう概念をご説明いたしました。こういう概念でつながっているものです。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区として１００億円近くになる中で、生活保護に出てない部分がまだあるのかなという、ほかにはないでしょうねというのを確認したかった。子どもに限らず、いろんな部分で出てくると思いますので、ひとつきちんとした計画を立てていただきたいなということをお願いします。","respondent":"高橋障害者福祉課長","answer":"平成２０年度で生保の方は８８人おりまして、平成２２年１月末現在で１００人ですので、１２人は確実に増えているものです。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問","question":"１,３９１億円の１００億円、約７％以上の数字が生保に出ていますということが区民の皆さんに伝わっているのかなというのが非常に気になります。これだけのものを占めているということは、もうちょっと知らせてもいいんじゃないかなと思うんですが、いかがか尋ねました。","respondent":"金子企画財政課長","answer":"今、委員のご指摘にありましたとおり、子ども手当の分も含めまして、非常に民生費、増えております。４分の１枠負担がありますので、財政状況の公表という形もありますので、何らかの形で区民の方にはきちっとお示しはしていきたいと考えております。","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、今度の活動に対しての高齢者福祉課と地域活動課の連携、どちらが主体になってこれからやっていくのかというのが１点。ここがやるんでしょうけれども、全体的な集約をどういうふうにしていくのか、その２点を、答えるよう求めました。","respondent":"冨岡高齢者福祉課長、宮地地域振興事業部長","answer":"地域センターの職員と連携しながら進めていくというところで、どちらがというのは、今後……。ただ、事業展開は私どものほうでやっておりますので、メインになるのはこちらかなです。 平成７年にスタートしたわけですけれども、すぐ地域センターのほうに、それぞれの地区での活動ということで移ってきました。計画づくりは福祉のほうです。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":122026,"voices":372}},{"id":"h22-20100312-3","meetingId":"h22-c-budget","date":"2010年3月12日","dateIso":"2010-03-12","committee":"予算特別委員会","time":"午前１０時０２分～午後５時４８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を131件整理しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"この４点についてお伺いしてまいります。これは認定の見直しの期間があるかどうか、それからあとは個人的な形での１人当たりの給付金額等のご説明をほしいと求めました。","respondent":"山岡健康課長、福島ものづくり・経営支援課長","answer":"１人当たりという形で出していないものですから、申しわけございません。どうぞよろしくお願いします。もともとは北品川五丁目第１地区の再開発ビルの一角につくる予定のものづくり産業支援施設、これの中身を検討しているものです。","id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"ほかの区からいただいているようなケースもどうやらあるような、私のところに間接的に入ってくるものですから、その辺について。ですから、お答えいただくのは公害のところと、それからもう１点が大崎周辺ものづくりのことについてお答えほしいと求めました。","respondent":"福島ものづくり・経営支援課長、山岡健康課長","answer":"実際の中身の検討につきましてはほとんど終わっておりまして、それについての検討とともに、実際に活動を始めていくというものです。新ビジネスということで、大崎発の日本… 認定の方が正しく認定されているかですけれども、更新は３年更新ですけれども、見直しは毎年やりまして、主治医の診療報告書等の資料で、審査会を通して専門家の意見を伺って審査をしておりますので、間違いないと思います。","id":"exchange-002"},{"speaker":"金野委員","kind":"質問","question":"高齢者の肺炎球菌、いよいよスタートということで、先ほどご説明いただきまして、１回につき３,０００円の助成ということで伺いました。周知方法などを説明するよう求めました。","respondent":"吉田保健予防課長","answer":"肺炎球菌につきましては、次年度より開始と考えておりますが、実際の方法については現在検討中です。恐らく夏以降に実施する予定というふうに考えております。","id":"exchange-003"},{"speaker":"金野委員","kind":"提案","question":"それから平成２１年度の予算書からすると、相談事業がこちらには記載をされていないのでその部分なのかなということでそれを確認したいと求めました。","respondent":"山岡健康課長、矢野品川保健センター所長","answer":"これは昨年の秋からスタートいたしまして、これまで２回の審査会を実施したところです。それぞれＡランクからＣランクまでのランクで認証さしあげたところです。内容として公開講座、運動の理論と実践の講座それから地域の健康づくり活動を推進するための参加型の講座の３本立てで講座を実施いたしました。","id":"exchange-004"},{"speaker":"金野委員","kind":"質問・要望","question":"お子さんが欲しい、私どもも国に保険適用を要望しているところですが、保険適用というところで区としても一緒に働きかけていただきたいなと思います。これは３２件ということで、今後周知をされながら健康づくりに努めていただきたいと、このように要望いたします。","respondent":"矢野品川保健センター所長","answer":"来年度の健康大学しながわについては、企画運営委員を出していただいて一緒にやっていくです。それから、それについても来年度の健康大学しながわの中の参加型講座に卒業後の方も一緒に入っていただいて考えていくという予定にしております。","id":"exchange-005"},{"speaker":"金野委員","kind":"確認","question":"ということは、インストラクター的な動きをされるということでいいんでしょうか。最後にそこを確認したいと求めました。","respondent":"矢野品川保健センター所長","answer":"様々な技能を持っている方もいらっしゃいますし、あるいは全くこれからやりたいという方もありますので、ある程度インストラクター的なものもやっていく可能性もありますが、地域の幅広い意味での健康づくりを進めていく推進役ということで考えております。","id":"exchange-006"},{"speaker":"金野委員","kind":"意見","question":"わかりました。どうかそのお力もいただきながら、健康づくりの増進のために皆さんの力を役立ててほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは２６９ページの健康診査費について、かかりつけ医と区民の健康診断の関係について伺いたいと思います。後半は子宮頸がんワクチン接種への全額助成実施を求めて質問したいと思います。","respondent":"本城国保医療年金課長、山岡健康課長","answer":"７５歳以上の高齢者の受診率につきましては、同じく３４.８４％という受診状況となっているところです。健診の周知・ＰＲだとか、受診しやすいものを目指すために、健診についてのＰＲに努めているところです。 ただ、まだまだかかりつけ医を持っていらっしゃらない方も多くいらっしゃいます。かかりつけ医の周知、これをより一層図っていく必要があろうかと考えております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域の方にお話を伺うと、信頼関係からもそのお医者さんで健診をすることで安心があるとお話を伺いますけれども、私も同感です。ぜひここを改善していただきたいと思うんですけれどもいかがか尋ねました。","respondent":"山岡健康課長","answer":"区境の方への対応です。これは私どもの区だけでは解決できない。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"研究していただきたいと思うんですけれども、かかりつけ医が大田区の場合、受けられないわけですよね。現状だと、品川区はそういう方はどこで健診を受ければ望ましいと思っているのか、お考えをお聞かせいただけますか。","respondent":"山岡健康課長","answer":"例えば乳がん検診等はそこの健診機関とかかりつけ医との連携というんでしょうか、情報のやり取りができる仕組みができればなと考えております。かかりつけ医の健診体制の問題もありますので、その辺は将来的な課題だというふうには考えます。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"里帰り出産でも可能だと伺いますけれども、これは区民にとってどういう事情があるからこうしているのかご説明いただきたい。遠くの場合は領収書があれば構わないという仕組みもあるそうですけれども、どういう仕組みでそれが可能なのかご説明いただけますか尋ねました。","respondent":"山岡健康課長","answer":"必ずしも今住んでいるところで出産ということを考えられないで、実家の方に帰られて出産という方が結構いらっしゃいます。それからもう一つは、今のところまだどうこうという段階になっておりませんので、将来課題というふうに考えているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"区境にいるということと、なぜ大田区のかかりつけ医かというと、要するに理由の一つが一番近いからということです。７５歳以上の方、他区でも利用が可能なように直ちに検討をしていただきたいと思うんですけれども、いかがかと。","respondent":"山岡健康課長","answer":"がん検診全体の案内をするとか、そういう周知をしていますけれども、より一層いい周知の仕方があればもちろん考えていきたいと考えています。こういう方に対しての働きかけも必要かなと考えています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"国内では年間１万５,０００人の方が子宮頸がんにかかって、残念なことに３,５００人の方が亡くなっていると伺っています。ただ、費用も４万円から６万円と自費では困難だと思いますけれども、ぜひ品川区でも無料接種助成制度を実施すべきだと思いますがいかがか尋ねました。","respondent":"吉田保健予防課長","answer":"三つほど挙げしますと、一つは感染後の予防効果が期待できないというふうに言われているところです。ターゲットをいつ何歳ぐらいから始めたらいいかというのがわかっていないという問題点がありますので、慎重に対応していく必要があると思っています。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん体のことですから、兵庫県の明石市、東京都では杉並区。ぜひ品川でも実施に向けて検討を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問","question":"３０１ページ、２９９ページ、空き店舗活用支援事業についてお伺いをします。この創業支援との関係というか、結びつきがあったら非常にいいのかなと思うので、その辺の関係もわかったら説明を求めました。","respondent":"榎本人事課長、福島ものづくり・経営支援課長、諸岡商業・観光課長","answer":"後期５年ということで新たに立てまして、それから、それから子育てを支える環境づくりという三つの目標に関して計画をつくっているものです。… 私からは、ワークライフバランス関連の事業所内育児施設整備費補助助成についてご説明します。中小企業でこういった本格的なといいますか… 商店街の方の予定を踏まえて、商店街と相談をしながら予算計上をいたしまして、支援の準備をしているものです。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"僕は非常にすばらしいものだと思って進めていってほしいという思いの中で、希望が多かったら、ぜひ予算を超えても支援を続けていっていただきたい。これは要望です。","respondent":"福島ものづくり・経営支援課長","answer":"この中身につきましてはこれから制度設計しながら検討していきますので、どういったものがこの助成として使いやすいのか検討してまいりますので。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"確認","question":"私は２７５ページ、健康づくり宣言認証制度、２９３ページの観光アクションプラン、そして２９９ページ以降の商店街のことで伺っていきます。その辺のお考えと、始まって間もない、そして研究事業という点を踏まえて伺えればと思います。","respondent":"山岡健康課長、諸岡商業・観光課長","answer":"先ほども申し上げましたように、できれば飲食店の栄養部門、あるいは禁煙部門を強調してこれから取り組んでいければと考えています。今のところは認証書… 昨年実施いたしましたつまみ食いウォークでは、区内が３割ということで、多くの方が区外からもおみえになりました。区外の方々には荏原地区の魅力を知っていただくような取り組みを、今、観光協会とともに計画しています。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"そういう意味の、区内の再発見という仕掛けに力を入れられたらどうかなと。そういう意味では、マネージャー的な専任スタッフ、専門スタッフの重要性、この辺のお考えをいただけたらと思います。","respondent":"諸岡商業・観光課長","answer":"一つ見せ方、そういうことも含めて、区内再発見ということでの取り組みをしていきたいと考えています。今、今後両区でもって活躍していただこうというようなことも進めておりますので、人材育成の方にも力を入れてまいりたいと思っているところです。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問・要望","question":"２９９ページになりますが、商店街ステップ・アップ支援事業のところから、これは人材、人づくりというテーマで伺いたいと思います。自民党の政策要望でもいつも挙げしていますが、事務局強化へのさらなる支援というのを自民党としていつも要望させていただいていますが。","respondent":"諸岡商業・観光課長","answer":"延べ４００人近い学生ボランティアの方に活躍していただいて、商店街の方々と一緒になって取り組んでいただいているところです。ボランティア等、より多くの方々に商店街のことを知っていただき、一緒になって活動していただくような取り組みを続けていきたいと考えています。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問","question":"まず減っているのかどうか、粗大ごみの推移を伺いたいのと、お願いしてからどのぐらい待つような状況になっているのか。実は粗大ごみ、大きいものになりますと１人で出せないですとか、例えば粗大ごみを出す日が決まって引っ越しが決まるというというケースも伺います。","respondent":"太田品川区清掃事務所長","answer":"これは平成１９年７月から実施をしていますけれども、平成１９年でいきますと、１開設日当たりでは平均２２件でございました。今申し上げたように１開設日当たり５０件ですので、日曜日の開設で大体１００件ぐらい受けられるということで、次の日曜日には可能かなです。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"この国内２回、海外１回、多分平成２２年でやることですから予定はもう組まれていると思います。どのような業種で行われるのか教えてほしいのと、その幹事会社という形で１社お願いして、複数まとめて出ていくのか教えていただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"新製品・新技術のクラスターフェアとして今年開かれたものについてご説明します。出店助成につきましては、今後も今まで同様、継続して進めてまいります。","id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"直接区で出していくのか、エージェントか何かで出していくのかというところを説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"こちらにつきましては、どのような形でやるかというのはこれから検討してまいりますけれども、区内のＮＰＯを使ったり、あるいはそういった専門業者がいればそういうところにも委託していきたいと思ってあります。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば４階の会議室とかを使って、いわゆるものづくりのブランドＰＲというのを、区を挙げてひとつ大きな形で。そのような形でできないかなと思いましたので、できるかできないかといいますか、ちょっと考え方だけお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"今後、できるかどうか検討していきたいと思います。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに２６９ページの各種がん検診について、また２点目には２７５ページの各種健康塾についてお聞かせほしいと求めました。一つはこの受診率がどの程度までアップされたのか教えていただきたいのと同時に、今回事業仕分けで削られてちょっと心配しておりました。","respondent":"山岡健康課長","answer":"平成２０年度が１７.９％でしたので、１月末現在で既にオーバーしておりまして、これも２０％を超える見込みです。平成２２年度も引き続き予算計上させていただきましたので、よろしくご審議お願いいたします。","id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"国としては５０％を目指して、今、着実に品川区も二十数％まで上がってきたということなので、この成果が上がっているのかなと思います。それから一つ、私自身よくわからなくて、どういうことなのかなと思いましてご説明をほしいと求めましたけれども。","respondent":"山岡健康課長","answer":"ただし数を増やしてまいりますと、そのやり方等を含めまして、がん検診全体について質を高めるための検討をしていきたい。あるいは、例えば自己負担の問題等々も含めていろいろと検討してまいりたいと考えて、新年度検討会を立ち上げることになりました。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味では本当によくよく検討していただいて、前進してほしいと求めましたが、実際、このがん撲滅といいますか、受診率はお伺いしましたけれども、実際の発生率というのはそちらの方でデータ的なものをお持ちか尋ねました。","respondent":"山岡健康課長","answer":"一応統計を私どもの方でとっているものにつきましては、例えば平成２０年度にがんで亡くなった方の数、８３３人の方。死亡原因のかなり高い割合をしめているということになっております。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"２７５ページの各種健康塾のことでお話を聞かせてほしいと求めました。実際、応募人数がいて、また２４回最後まで頑張って卒業できるのかという言い方は変ですが、実態はどうなのか教えていただけますか尋ねました。","respondent":"山岡健康課長","answer":"健康塾、それぞれのコースで、これは皆さん全員が最後まで、もちろん途中で何回か休まれる場合もありますけれども、全員の方が修了している状況です。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問","question":"最後に、下のところのしながわ出会いの湯事業のことでお伺いいたします。お風呂屋さんがなくなっちゃったらどこでやってくれるんだろうと、その辺の対応策といいますか、何かお考えになっていらっしゃいますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"稲川委員","kind":"質問","question":"２８３ページなんですが、改めてお伺いする形になると思うんですが、マイガーデンというのは今まで区内に何カ所あったかということ。南大井に５７区画ということなんですが、４地区ですか、様々な地域にマイガーデンの区画をつくるご予定があるかの３点をお願いします。","respondent":"藤田水とみどりの課長","answer":"応募についてですが、区画の数、それからそれに対する応募者で考えますと、近年はおおむね６倍、あるいは５倍というような形で応募があるところです。","id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"区内に今まで３カ所あったということで、場所も今お伺いをいたしました。では、減らした理由を。","respondent":"藤田水とみどりの課長","answer":"東五反田については建物計画があった、それから豊町については補助２６号線の道路整備の関係の土地ですので、その辺の整備の進捗にあわせて廃止になったです。","id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"先般の区民委員会の報告でも８月オープンと聞いていますが、きょう現在で工期の遅れなどがあるかどうか。６点お願いします。","respondent":"福島ものづくり・経営支援課長","answer":"確かに名称は創業支援センターですが、創業支援だけではなく、あるいは先ほど出ていましたような相談業務等についても幅広く行っていく予定です。","id":"exchange-031"},{"speaker":"稲川委員","kind":"質問・要望","question":"先日の款別の質問にありましたけど、駐車場、大体相談者がどれぐらい来るとかというのは概算的には出すべきだと僕は思っております。地域、その会の積極性に任せて、例えばその行政書士会とか税理士会の方々が区にアピールをしに来るものなのかどうなのかを説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"そちらにつきましては、両方あるかと思います。もちろん区の方としても働きかけは行いますが、会の皆様方の積極性にも期待しています。","id":"exchange-032"},{"speaker":"山内委員","kind":"質問・要望","question":"私の方からは衛生で２７５ページのかかりつけ医療定着促進事業と不妊治療相談・助成事業についてを伺います。具体的に、それから今年度の実績と、それから次年度の件数予測はどのようにお考えになられているのかというところをお伺いしたいと思います。","respondent":"山岡健康課長","answer":"それから実績ですけれども、この実績が増えたからいいのか減ったからいいのかというのはなかなか難しいところです。所得制限をなくすようにというのはなかなか難しいところです。","id":"exchange-033"},{"speaker":"山内委員","kind":"質問・要望","question":"そういう意味も込めて、１０万円とにかく助成するから病院に行ってみたらいかがですかというようなやり方の方が、これはそういう方に聞いたんですよ。続きまして産業経済費の方で、２９９ページの商店街の活性化のことについて伺います。","respondent":"諸岡商業・観光課長","answer":"小規模商店街とともにいろいろな活性化に向けた事業に取り組んでいるところですが、まず一つは知っていただくこと。一つはプレミアム付商品券もありますし、そのようなことを区としても考えているところです。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"これについてはまだ途中ですけれども、この２年間から見た課題や、また評価といったものをお聞きしたいと考えています。来年度、平成２２年度でのこの事業の変化、これもお聞きしたいと思います。","respondent":"諸岡商業・観光課長","answer":"これは３回ほど実施いたしまして、また今年度は大田区との連携事業として実施をいたしました。平成２２年度の事業変化ですけれども、平成２２年度におきましては、平成２１年度は事業年度の第１年目ということで事業を実施いたしました。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"感想がなかったので大変残念なんですが、この多重債務については消費者センターが中心となってやっていくんじゃないんですか。同じ所管になるかと思いますので１点、今年度で終わるというようなお話も聞いておりますので、ここら辺の評価をほしいと求めました。","respondent":"諸岡商業・観光課長","answer":"法的な問題を絡めますと、弁護士でないと法的な問題には対応できないとかといった権限等もあります。そういうことについてはきめ細かく対応させていただいているところですけれども、法的な部分については専門家への相談が必要となってくるです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"せっかく同じ事業部で課が一緒になったわけですから、その辺のデータを健康課としてどういうふうに生かしているかということについてお伺いします。それと２９５ページの広域観光まちづくりは、大田区との連携、この羽田をどう利用していくのかということをお伺いします。","respondent":"山岡健康課長、諸岡商業・観光課長、宮地地域振興事業部長","answer":"健診のデータの活用ですけれども、特定健診については国保で実施しているです。これから区内、いろいろな方面に働きかけて… 品川・大田の連携についてですけれども、その中で協議・検討を進めて、事業を進めていくという方法で進めております。年２回… 組織に関するご質問でしたので私の方からお答えします。背景も目的もそういったことで、この二つの組織の中で全開… あくまでも商店街振興という意味あいから大型店については除外いたしまして、商店街のみの使用ということで進めていきたいと考えています。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"組織についてお伺いしますが、今まで点と点を線に結んで、線と線を面にするという施策を産業振興という形でやってきたと考えています。このような質問をしているんですけれども、改めて二つの商業、工業が一緒であったよさがあったのにもかかわらず二つになった。","respondent":"宮地地域振興事業部長","answer":"いろいろな形で連携、常に連携しながら情報交換してやっていくことで、なお一層の力が発揮できると考えております。そうしなければせっかくつくった意味がありませんので、キャパシティーのある二つの力でやっていきたいと考えております。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"私は衛生費、ページはありませんけども、墓地の許可申請のことについて伺いたいと思います。もう一つは経済産業で、２９９ページ、小規模商店街活力づくり支援事業に関連して伺いたいと思います。","respondent":"荒井生活衛生課長","answer":"今お尋ねの件は、墓地の造成工事と許可が連動するかということだと思います。造成工事イコール許可ではありませんが、その届け出を受理したという事実のもとで造成工事が行われているという経過です。","id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問・要望","question":"造成工事イコール許可ということではないということは確認させていただきました。これが二つの角度から検討するということだと思うんですけれども、具体的にどういうことなのかお聞かせほしいと求めました。","respondent":"荒井生活衛生課長","answer":"墓地の許可に当たりまして大きく二つの点から検討するというお尋ねだと思います。地域の実情に関しましては、それぞれの地域の中でその墓地がどのような調和をもって設置できるか、経営できるかという視点になるかと考えています。","id":"exchange-040"},{"speaker":"宮崎委員","kind":"質問","question":"区の方はどういうふうにニーズを把握するのか、基準というのがあるのかないのか、そこのところを伺いたい。需給バランスということも言っていますけれども、その２点、具体的に判断するときにどういう基準になっているのか伺いたいと思います。","respondent":"荒井生活衛生課長","answer":"地方自治体が墓地を設置する場合につきましては、住民にとってのニーズの把握ということが必要になってくるかと思います。自治体が経営する場合と、寺院が経営する場合がありますので、先ほどの回答の中に含まれていると考えています。","id":"exchange-041"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、そこのところの把握というのはどういうふうにするのかというところをもう１回伺いたいと思います。これが今までのルールと若干変わったようなんですけれども、そこの考え方というのはどういうふうになったのか、伺いたいと思います。","respondent":"荒井生活衛生課長","answer":"協議会の中では、申請予定者の方からは具体的なものが提示されずに、申請時に提示されたということについての疑問かと思われます。その中で、墓地の経営予定者の方から檀家さんの方への確認をされて、名簿を提出していただいたという経緯があります。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこら辺の考え方がルールの中で若干変わってきているんじゃないかということで、その内容を伺いたいと思います。そういう角度で、単に設置予定者ができるということではないということを言っていますので、ぜひそこの考え方を聞かせてほしいと求めました。","respondent":"荒井生活衛生課長","answer":"丁寧に対応するようにということで、墓地の申請予定者にも強く指導してきてまいりましたし、そのように接してきたのではないかと思います。檀家活動の一環として墓地を設けたいというご希望もありましたので、そういった中での対応だと考えているところです。","id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ、慎重に検討いただきたい。今、例えばチャレンジショップ等で生鮮三品の店を誘導するとか、そういう対応というのはできないか尋ねました。","respondent":"諸岡商業・観光課長","answer":"空き店舗対策等で生鮮三品を商店街として開店しようという動きがありますので、支援をしてまいりたいと考えております。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"環境については、あえて環境課はと伺いますが、環境課では区民との協働についてどのようにお考えを持っていらっしゃるのかということをお伺いします。そういった意味で、日本間の維持とか、そういったところへもこのリフォームを使えないかということをお伺いしたいと思います。","respondent":"矢野品川保健センター所長、工藤環境課長、太田品川区清掃事務所長、柏原住宅担当課長","answer":"４カ月健診未来所の方についてですが、これにつきましては地区担当の保健師が、全数家庭訪問や電話等で情報把握に努めております。… 環境情報活動センターの運営に関しましても、環境ＮＰＯとの連携のもとにやっております。そういった意味では… ３点目の陶器・ガラス・金属ごみの収集回数変更のことに絡んでお答えをいたします。この部分は分別変更の実施前と実施後で… 我々が今考えていますのは、バリアフリー化等々を考えておるのですけれども、基本的には対象になってくるのではないかと考えております。","id":"exchange-045"},{"speaker":"阿部委員","kind":"質問・要望","question":"１分ありますので、最後に一つ別件で、要望を入れておきたいんですけれども、３０１ページ、大崎のものづくり施設。特にお考えがなければここまでで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"井桁委員","kind":"質問","question":"２８２ページ、２目緑化推進費について、その点についてお伺いをしたいと思います。それから２８５ページ、２８７ページ、資源中間処理事業の資源再商品化経費についてお伺いしたいと思います。","respondent":"荒井生活衛生課長","answer":"２月２８日現在、新しいものといたしまして１,１２０頭、現在１万５７６頭が登録されてあります。同じく平成２２年２月２８日現在になりますが、注射接種数といたしましては７,６３７件、これが注射済票の配布になってあります。","id":"exchange-047"},{"speaker":"井桁委員","kind":"質問・要望","question":"そうなってくると、なかなかかわいらしい、皆さんで考えていただいたのでぜひとも少しでもつけていただきたい。世田谷区では、少しでも多くの犬につけていただくことが啓発の一つにもつながると思いますので、そこの点をお願いいたします。","respondent":"荒井生活衛生課長","answer":"平成２１年４月に鑑札を変えまして、大型犬を想定していたようなものを、小型犬でもということでコンパクトなサイズにさせていただきました。","id":"exchange-048"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は以前質問で犬の住民票というようなものはどうなのかなということで質問させていただいて、先ほども登録数を聞いたんですが。そこのところでぜひ実態調査をしていただきたいと思っているんですが、そこの点についてお願いいたします。","respondent":"荒井生活衛生課長","answer":"品川区といたしましても検討はしておりますが、まず他区の推移を見ながら検討をさらに進めていきたいと考えているところです。実態調査につきましては、ペットショップの売り上げであるとか、そういったところに協力を求めながらということを考えていきたいと考えております。","id":"exchange-049"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ東京都のほうにも、２３区を挙げてといいましょうか、品川区も一丸となってそういう要望を出していっていただきたいと考えています。そこのあたりをお伺いしたいのと、平成２０年は６件、そこのあたりをお願いいたします。","respondent":"藤田水とみどりの課長","answer":"それによらない事業について、１０台未満のものについて助成をしていこうということで、何とか１０件に持っていきたいなと考えています。しかしながら、宣伝等にこれからも工夫しながら、効果的に事業ができるようなＰＲに努めていきたいと考えているところです。","id":"exchange-050"},{"speaker":"井桁委員","kind":"質問・要望","question":"少しでも品川区の緑を増やしていこうという意気込みの１つだとも思いますので、ぜひ積極的にＰＲをしていっていただきたいなと考えています。そこのあたりのお考えを１つと、それから２８７ページの資源中間処理事業の資源再商品化経費というのを、ぜひ教えていただけますか。","respondent":"太田品川区清掃事務所長","answer":"１点目のフリーマーケットの件ですけれども、区民の方のリサイクル意識を高めていただくとともに、ごみの減量を目的として実施しています。さらにフリーマーケットの部分について、広報等でＰＲをして、より多くの団体が実施していただけるようにしていきたいと考えています。","id":"exchange-051"},{"speaker":"山路委員","kind":"質問","question":"２点目が２８３ページ、３点目が３０１ページ、産業技術大学院大学との連携についてお伺いいたします。いろいろなコース型教室がありますが、品川区独自に、この指定管理者以外でやられているコース型というのはどういうものがあるかお伺いいたします。","respondent":"山岡健康課長","answer":"健康センターは指定管理者で運営を始めておりますので、そこでやっておりますコース型あるいはフリー、すべてこの指定管理者のほうでお願いしているものです。","id":"exchange-052"},{"speaker":"山路委員","kind":"質問・要望","question":"温水プールが平成２３年度に品川学園に誕生する予定になっていますが、当然一般開放もされると思うんですね。そこで品川学園でこの品川地区の中、高齢者の方のご希望している水泳教室とかの計画を立てては思いますが、どのようにお考えか尋ねました。","respondent":"山岡健康課長","answer":"伊藤学園、それから八潮と、こういうところを使って現在実施しています。新しいところができましたら検討してまいりたいと考えています。","id":"exchange-053"},{"speaker":"山路委員","kind":"提案","question":"もう１つ、心のリラクゼーションということで我が党のほうで提案させていただきましたが。これについても何かあったら教えてほしいと求めました。","respondent":"山岡健康課長","answer":"あるいはヨガであるとか、ピラティスであるとか、そういうゆったりとしたエクササイズ系もどんどん取り入れてまいりたいと考えております。現に幾つも入っておりますので、どうぞご利用なさってください。","id":"exchange-054"},{"speaker":"山路委員","kind":"質問・要望","question":"住民の方にもそのように伝えておきます。確認をちょっとさせていただきたいと思うんですけれども、この街なみ緑化助成の中に庭園等の芝生も含まれているかどうかお伺いいたします。","respondent":"藤田水とみどりの課長","answer":"先ほど申し上げました駐車場の緑化等が１つ、それからもう１つが屋上や壁面の緑化ということで、お庭の一部に芝生を張るというのは対象にはなってございません。","id":"exchange-055"},{"speaker":"山路委員","kind":"質問・要望","question":"すばらしい成果をおさめたという内容のケーブルテレビを見せていただきたいんですが、平成２２年度の展開についてお伺いいたします。都立高等専門学校は午前中の質問で細かくお伺いして、この辺の提携は今後どういうふうに展開していくのかお伺いいたします。","respondent":"福島ものづくり・経営支援課長","answer":"それだけではなく、専門講座ですとか、あるいは国際取引のための実務講座等幅広く進めていく予定です。産業技術大学院大学との連携ですが、こちらにつきましても、私どものところは積極的に働きかけていきたいと考えています。","id":"exchange-056"},{"speaker":"山路委員","kind":"質問","question":"今後の展開は今お伺いしましたが、私はここでもう１つ深めて考えたときに、人的交流というのも非常に重要になってくるのではないかと思うんですね。外国の生徒を受け入れて、国際インターシップ制度まで発展するような検討をされたらと思いますが、どのようにお考えか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"今、中小企業で海外進出されました企業で、現地採用した職員を品川区にある本社で研修させるということをかなり行っております。そういった場合、そういう形を含めて、産業振興とともに外国人の人的交流を含めた国際化支援をしていきたいと考えております。","id":"exchange-057"},{"speaker":"高橋委員","kind":"質問","question":"ただ華やぐとかにぎわうとかではなくて、どのような経済効果というんでしょうか、具体的なところをどうお考えかということですね。観光被害というんでしょうか、区としてのその辺のところを把握して、どのような対応をされているのか、答えるよう求めました。","respondent":"山岡健康課長、堀越文化スポーツ振興課長、諸岡商業・観光課長","answer":"それから１つ忘れました。ものによっては電子申請できるものも備えているところです。 劇団四季との今後の連携についてのお尋ねです。そういったことを含めて検討しているところでございまして、いろいろな協議… 助成の予定です。騒音等、あるいは注意看板を立てたりということで対応したり、近隣の方々にご理解をいただきながら進めてまいりたいと考えています。","id":"exchange-058"},{"speaker":"高橋委員","kind":"質問","question":"それから四季のほうの話では、貸し付けの状況で今、お話を伺ったんですが、予算書のどこに載っているんでしょうか。プレミアム付商品券は、印刷はやはり助成も兼ねて区内業者なんか尋ねました。","respondent":"山岡健康課長、諸岡商業・観光課長、阿部経理課長","answer":"一番見てもらえるのが広報紙だと考えておりますので、もちろん検討の材料にはしますけれども、従来どおりの方法を強化していきたいと考えております。平成２１年度の印刷につきましても区内業者でございましたし、平成２２年度につきましても区内業者にお願いする予定です。四季への貸し付けの件ですけれども、今、去年７月から１０年間の貸し付けを行っております。","id":"exchange-059"},{"speaker":"高橋委員","kind":"意見","question":"プレミアム付商品券のちょうど１万１,０００円で、一番高い席が９,８００円で入れるんですが、これは共通商品券では入れないんですよね。","respondent":"堀越文化スポーツ振興課長、阿部経理課長","answer":"まだ具体的なお話のできる段階ではありませんが、そのようなお申し出もいただいております。連携など何かできないかというお話し合いも順次していますので、また働きかけを引き続き継続していきたいと考えています。 先ほどご答弁申し上げたとおり、そういう区民への還元があるので、先ほど申し上げたような貸付料の措置を図っているです。","id":"exchange-060"},{"speaker":"市川委員","kind":"質問・要望","question":"２８９ページの陶器・ガラス・金属ごみ収集回数変更について、東京エコサービスの小中学校への電力小売り事業のことについて伺いたいと思います。それからここ三、四年でのことですけれども、保健師の人数というのはどのように変化しているのか、このことを伺います。","respondent":"矢野品川保健センター所長","answer":"平成１８年度はまだ児童センターとの連携がございませんで、１,３１２件です。品川保健センターが１２名、荏原保健センターが１１名、大井保健センターが５名で地区の活動をしています。","id":"exchange-061"},{"speaker":"市川委員","kind":"質問・要望","question":"保健師の人数の推移なんですけれども、ここ３年ぐらいで増えているのかどうなのか、それを教えていただきたいんですけれども。","respondent":"矢野品川保健センター所長","answer":"組織改正等はありますが、事業数に対応して配置されておりますので、増減はしておりません。","id":"exchange-062"},{"speaker":"市川委員","kind":"質問・要望","question":"この数がどのようになってきているのかと、それから相談の内容について、どんな傾向があるのかというところを教えてほしいと求めました。","respondent":"矢野品川保健センター所長","answer":"保健師の相談数ですが、電話相談につきましては、３保健センター合計での総数、延べ５,５０３件です。これは心の健康相談や感染症や、赤ちゃんから高齢者まですべての数です。","id":"exchange-063"},{"speaker":"市川委員","kind":"質問・要望","question":"対応していただきたいと思うんですけれども、どのように支援をしていこうと考えていらっしゃるのか、そこのところを伺います。","respondent":"矢野品川保健センター所長","answer":"保健所の仕事というのはいろいろなものがありますが、地域の住民の方が健康に生活していけるような支援ということをしています。いろいろあってなかなか大変なんですが、育児不安やうつ病の予防、地域の健康づくり等に今のところは力を入れているということです。","id":"exchange-064"},{"speaker":"市川委員","kind":"質問・要望","question":"次に、資源持ち去り防止対策費のところで伺います。このパトロールというのはどういう方が行っているのかを伺います。","respondent":"太田品川区清掃事務所長","answer":"それから非常勤職員という形で１名、非常勤は１６日勤務ですので、不足の場合は他の職員が応援でやるという体制になってあります。非常勤職員１名のところを２名増やして、非常勤職員３名の体制でやっていきたいということで、その経費２名分で約６７０万円ほどの増があるです。","id":"exchange-065"},{"speaker":"市川委員","kind":"質問","question":"そこのところはわかりました。８００万円、そして２０１０年度の予算が１,０００万円と変化しているんですけれども、この予算が動くというのはどういう理由からなんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"さらにパトロールを実施している上でも、専任体制を充実させる必要があるということで、非常勤職員１名から３名に２名を増加したです。","id":"exchange-066"},{"speaker":"市川委員","kind":"質問","question":"次に、陶器・ガラス・金属ごみの収集回数の変更についてです。チラシと冊子作成経費が計上されているんですが、どのようなチラシとか冊子をつくられていくのかというイメージができないものですから、伺います。","respondent":"太田品川区清掃事務所長","answer":"広報の関係ですけれども、今まで週１回ということで、陶器・ガラス・金属ごみの収集を実施してまいりました。これから検討していきたいと思ってありますが、年内に１度、その部分で周知をしていきたいということが１点あります。","id":"exchange-067"},{"speaker":"市川委員","kind":"質問","question":"前段の分別変更のときは、この週１回を月２回に変更するというのに準備を１年もかけるというのは何かなとちょっと思いましたもので、お聞きしました。そうであれば、できればもっと早く変更されたほうが経費がかからないと思うんですけれども、ちょっとここのところはご見解をお聞きしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"そうすると、今度は今言っている収集車が減りますから、そうすると、地区割の変更が必要になってくる。その変更になったことに伴って、収集時間にも影響が出てくるということになってまいりますので、来年４月から実施をするというものです。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"次に、東京エコサービスの小中学校への電力小売り事業について伺います。品川区はどのように計画しているのか伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"品川区におきましては、５つの学校で電気を受け取るという予定です。そしてその受け取る電気の量ですけれども、現在予定しているのは約４７０キロワットという予定です。","id":"exchange-069"},{"speaker":"市川委員","kind":"質問","question":"５つの学校ということで、学校の名前を教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"４校目が鈴ケ森中学校、５校目が中延小学校ということになってございまして、こちらの学校を選択させていただいたという次第です。","id":"exchange-070"},{"speaker":"市川委員","kind":"質問","question":"東京エコサービスからの電気購入は、どんなメリットがあると考えていらっしゃるのか伺います。","respondent":"久保田行財政改革担当課長","answer":"環境への負荷の軽減が図れるということが２点目、３点目としましては、教育現場としてもそういったメリットがあるです。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"ごみ問題について、環境教育の基本はあくまでも資源化の推進とごみの削減であるということを再度確認させてほしいと求めました。ごみ発電礼賛にならないよう、学習現場では十分に留意することをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"２６５ページ、それと最後に２９１ページの収集運搬車ということで、３つ聞かせてほしいと求めました。金額だけなんですけれども、３００万円ぐらい多くなっているんですけれども、これはどのようなことがあって多くなったのか説明を求めました。","respondent":"山岡健康課長","answer":"多くなった理由ですが、これは私ども保健関係のほうで、いろいろとシステムの導入を図っております。そのリース代で増えているところです。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"本題であります武蔵小山創業支援センターについてお伺いします。２月３日に説明会があって、４日に審査会があったということで、そこに至るまでの経過の説明をお願いいたします。","respondent":"福島ものづくり・経営支援課長","answer":"提案説明会が２月３日に行われました。中身ですとか経営方針、あるいはどういったことを支援するのか、翌日ある１者に決めたというものです。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"どのようなことを委託されているのか、委託の内容もあわせて教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"この創業支援センターの施設の運営管理、また入居者等の支援、自立するような支援等を行います。さらには地域および区内商店街との連携および交流、さらには入居者の選定等、さまざまなことについて委託をする予定です。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"前回の歳入のところでもお伺いしたと思うんですけれども、非常に私たちも心強く、また喜んでいるところであります。これは８月にここのセンターが開設ということですけれども、どのようなときに子どもたちが入居できるのか教えていただきたいです。","respondent":"福島ものづくり・経営支援課長","answer":"この武蔵小山創業支援センターにおきます認証保育所ですが、６月から募集を開始するです。そのほか一時預かりの保育、商店街を利用される方などに対する一時預かり保育も６名程度で行っていく予定です。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"その周知方法というのはどのような形でされていくのでしょうか、説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"認証保育所の周知ですけれども、これはやはり広報しながわを中心にと考えています。事業者そのものも自分のところでホームページ等を持っておりますので、そちらのほうでも募集をするというふうに考えてあります。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"広報しながわを通じてということで、重要なメディア媒体ですけれども、商店街振興であるのであれば、近隣の商店街にも飾るというか、告知をするような協力をしたほうが、私は効果があるのではないかと思うんですけれども、いかがか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"近隣商店街での周知ですけれども、これは認証保育所だけではなく、この武蔵小山創業支援センターのオープンも含めて大々的にＰＲし、近隣商店街の皆様に、認証保育所だけではなく、さまざまなことで利用される施設にしていきたいと考えています。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"前回のときにチャレンジショップ、３名の定員のところ２７名の応募、それと貸しオフィスについては８つのところ１６人応募ということがありました。最終的に選考は３月の下旬ということで心得ておりますけれども、主な選考基準、どのようなことを主眼にして選考が行われるのか説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの選考ですけれども、まずは将来性、あるいは事業計画を見まして、この事業計画が妥当であるかということ、さらには近隣に既に商店街がありますので、そことのバッティングがないようにですとか、そういうことを考慮しながら決めていきたいと思います。","id":"exchange-079"},{"speaker":"大沢委員","kind":"意見","question":"今、バッティングがないということ、バッティングはある程度はしようがないと思いますので、そこらは柔軟に、せっかくの施設が、それがあるがために生きなくなってきてしまうと困りますので、多少のバッティングは私はあっても構わないと思いますので、お願いしたいと思いますとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"確かにあそこの商店街はかなり規模も広く、さまざまなことをやっていますので、すべてバッティングがないというのは難しいと思います。あるいは育児といったものを中心に事業展開を考えておりますので、その辺の視点も踏まえまして、入居者の選定を行っていきたいと考えています。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほどお話をしました収集運搬のことなんですが、収集運搬車についてお伺いします。いろいろな道路事情、非常にこれは大変なこと、ここに関して事故を防ぐような取り組みがどのように行われているのか教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"その中で出てまいりますのは、一つ一つの作業を確実に実施していこうということ、みんなで復唱しながら出ていくということで実施しております。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"いろいろな事情の中で作業をされて、本当にご苦労はわかりますけれども、やはり事故はあるよりないほうがいいわけであります。ですから、事故ゼロに向けた取り組みの充実をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"本間委員","kind":"意見","question":"２８１ページと２９１ページに絡む問題で、２９３ページから２９５ページにかけて産業経済費、歩行者観光案内標識設置等についてです。最初に公衆便所は区内に何カ所あるのか、また設置基準というものがあるのかどうか、あったらどのような中身かについてお知らせくださいとの意見を述べました。","respondent":"齋藤道路公園課長","answer":"公衆便所の数は現在３７カ所あります。設置の基準というものはございませんけれども、廃棄物処理法に、市町村は適正に公衆便所を配置しなさいという規定があるです。","id":"exchange-083"},{"speaker":"本間委員","kind":"質問","question":"次にお伺いしたいのは、１カ所設置するのに、大小といいますか、置かれた地域の状況によって多少変化があるかとは思いますが、平均で設置するのに必要な経費はどのくらいかかるのか、そしてそれを維持管理していくのは大体どのくらいかかるのか、おおよその見当で結構ですが、説明を求めました。","respondent":"齋藤道路公園課長","answer":"便器の数、いろいろ種類がありますが、大体３,５００万円から４,０００万円相当かかります。公衆便所は１日に２回清掃するところと１日１回の場所がありますが、平均にならすと１カ所当たり年間１００万円弱経費がかかってしまいます。","id":"exchange-084"},{"speaker":"本間委員","kind":"質問","question":"これはすばらしいことであるなと思いましたものですから、周りの品川区の足元からもう１度点検してみようということでお尋ねさせていただきました。というふうにしていただけたら、お互いの組織の活性化、健康づくりの部分で芽生えていくのではないかと思いますが、ご意見をお伺いします。","respondent":"山岡健康課長","answer":"それを区が後押しをする形で、より一層継続して健康づくりに取り組んでいただく。それがひいては皆さん健康で、最終的には医療費の削減等にもつながると考えておりますので、ぜひ皆さん応援していただきたいと思います。","id":"exchange-085"},{"speaker":"本間委員","kind":"質問・要望","question":"２９１ページはカラス対策費で、黄色い袋の効果がどうのこうのというのが１度ごみ出しの際にあったように思いますが、その件はどうなっているのか。それからカラスの巣の撤去の費用はどのようなことになっているのか、自己負担はあるのかどうかということでお願いします。","respondent":"太田品川区清掃事務所長、工藤環境課長","answer":"アンケートを実施して集約したところ、区民の方から１５８人、商店街の２０１店舗から回答があったです。それらを踏まえて収納する袋の特例認定という要綱を制定して、業者に認定をして、リボン等で販売をしているという経緯です。攻撃などを行うため、私どもも平成１７年度よりカラスの被害を受けている区民に対しまして、カラスの巣や落下ひなの撤去をやっているところです。","id":"exchange-086"},{"speaker":"本間委員","kind":"質問・要望","question":"今、どういう状況で切ったのかわかりませんけれども、決してそのようなことのないようにしていただきたいということを要望しておきます。意外と品川区の近隣にこれは勉強なるなというところがありましたものですから、周辺に目配せができるかどうか、ご意見がありましたらお願いします。","respondent":"諸岡商業・観光課長","answer":"広域連携ということで、大田区を中心に近隣区との連携を図っているところですが、このようなことも個別には始まっております。今後とも近隣区等の周辺と連携いたしまして、観光振興を図っていきたいと考えています。","id":"exchange-087"},{"speaker":"本間委員","kind":"質問・要望","question":"朝の部分でほとんど解決されてしまってどうしようもないという部分と、あるいは企業、事業者みたいな形がどうも見えてなりません。どうかひとつその辺の部分、もう少し防犯の意味も兼ねてかもしれませんが、一言その辺について決意ということをお願いしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"資源抜き取り防止パトロールですけれども、平成２２年度については体制を強化して、専任体制をつくっていきたいと考えていますので、早朝６時半から出てありますので、十分こまめに回って対応していきたいと考えています。","id":"exchange-088"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは２６７ページの新型インフルエンザ対策経費１,９９７万２,０００円に関連いたしまして何点か教えていただきたいと思うんですが。所管として今、どのようなご判断をされているのか、その辺を確認させてほしいと求めました。","respondent":"吉田保健予防課長","answer":"先週が４.２、今週が１.５という形で、順次落ちている。ただＢ型のインフルエンザ、東京都よりも若干高いですけれども、実際の流行については鎮静化しているのではないかと思われるところです。","id":"exchange-089"},{"speaker":"堺委員","kind":"質問・要望","question":"両医師会の集団接種を行った実数を教えていただきたいのと、個別接種と集団接種の考え方の違いと、これについてちょっと教えていただきたいんですが。行政が勧奨するものではないと、このような一文もありますけれども、ちょっとその辺の全体の仕組みを教えていただきたい。","respondent":"吉田保健予防課長","answer":"荏原医師会とも実施しておりますけれども、品川区医師会実施分が６２５人、荏原医師会実施分が４４５人となっております。臨時接種に新しい枠組みを設けて、勧奨はするけれども、接種の義務はないという位置づけに今後はなっていくだろうといった内容です。","id":"exchange-090"},{"speaker":"堺委員","kind":"確認","question":"区のほうで１回につき１,５００円助成してくださるということになったので、確認したら、教えていただきました。ですから、おそらくこのことを今とって、今後そういうことも含めて検討というお話かと思うんですが、もう１回、その辺を確認しておきたいと思います。","respondent":"吉田保健予防課長","answer":"この件につきましては、今、厚生科学審議会でも議論されたことを受け、閣議決定を今日明日中ぐらいにされるのではないかと言われております。今後は新型インフルエンザの予防接種につきましては、おそらく市区町村事務になってまいるです。","id":"exchange-091"},{"speaker":"菊地委員","kind":"質問","question":"私のほうは２９９ページから３００ページにかけてありますものづくり支援の問題についてお聞きしたいと思います。先日、月の初めぐらいか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区にとってのものづくりですけれども、日本同様、ものづくり産業というものは非常に大切なものであると考えています。産業そのものも、また福祉施策等の基盤となるものですので、ものづくり産業をはじめとした産業発展のために力を入れていくものです。","id":"exchange-092"},{"speaker":"菊地委員","kind":"意見","question":"それからもう１つ、この１,５２４の工場で１人から４人という製造工場の比率に違いが出ているのかどうか、お聞かせ願いたいです。２０人以下が小規模企業という位置づけのようですけれども、ここで働く従業員数も、わかりましたらお聞かせ願いたいと思いますとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"１～４人という数字、１～３人の規模が従業員が８４４人、４人～９人が４４６人という数字です。小規模全体におきましては１,４２７人で、全体に占めましては９３.６％が小規模事業者ということになります。","id":"exchange-093"},{"speaker":"菊地委員","kind":"質問","question":"ファブレス企業のことをお聞きしているわけではなくて、品川の製造業者が培ってきた技術をどう守っていくかということなんだと思うんですね。品川の地域経済を好転させる、こういう手当をどういうふうに講じることができるのか、この辺で考えているものがあればお聞かせ願いたいんです。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくりの火を守る、これは区としても重要な課題だと認識しています。技術を実際に見せて、商談をするという事業も行いまして、業績が伸びているです。","id":"exchange-094"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、今並べていただいた支援策、ここを超えてどういうことができるのかということをお聞きしたかったんです。こういうところにどんな支援を求めていくのかということも、必要なのではないかと思うんですけれども、その辺どのように考えますか。","respondent":"福島ものづくり・経営支援課長","answer":"そういったことについて技術的な支援をしながら、アドバイスをしながら、国の支援策に乗っかれるようにということで支援しております。そういう中で品川が持つ基盤産業の発展に努めていきたいと考えています。","id":"exchange-095"},{"speaker":"菊地委員","kind":"提案","question":"こうした横暴さ、身勝手さで大手の企業が栄えてきたわけですから、少なくとも区内にある大手の企業に応分の負担をしてもらう。同時に何度も私ども提案をしていますけれども、こういう流れをつくり出すべきではないかと思うんですけれども、もう１度説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"こういった直接的な支援というものは区としては考えていないということで、そういう形でさまざまな支援策を行っているものです。これらのさまざまな支援策を総合して行うことによりまして、区内の産業の力を入れて、また基盤産業を守っていきたいと考えているものです。","id":"exchange-096"},{"speaker":"菊地委員","kind":"質問","question":"大企業に吸い上げられるような形でなくなってきているわけですから、本当に首相が言った日本の宝、こういうことなんだと思うんですよ。だからやっぱりそこはしっかりとものづくりというのは一体何なのか、このことをしっかりと頭に置いてほしいんです。","respondent":"福島ものづくり・経営支援課長","answer":"そういった面で支援を進めていきたいと思います。ご理解いただければと思います。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問","question":"それがあまりにもみすぼらしい石だものですから、地域の議員さん、何とかしてくださいという話がありました。となれば、そういう理論的なことはわかるんだけれども、もう少し品川区は考えたらどうか尋ねました。","respondent":"諸岡商業・観光課長","answer":"観光協会とも連携して、龍馬も１つの観光資源ということで活用していこうという方向で、いろいろ案をつくっているところです。浜川一体周辺を案内した、できるところから観光ということで盛り立てていこうということで、さまざまな連携を図りながら進めているところです。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"質問","question":"もっと期待して安心して見られるような仕組みをさらにつくっていくということ、これも立派な観光政策じゃないでしょうかという観点なんですね。ですからもう１回聞きますけれども、あそこは護岸ですから、確かにわかるんですよ。","respondent":"諸岡商業・観光課長","answer":"現状の場所が東京都の下水道局の管理のもとにあるということで、いろいろ限界はあると思いますけれども、いろいろ観光の面からも工夫して、何とかもう少し見せ方等、見ていただく方々に対して見やすいように工夫は考えていきたいと考えております。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"大砲をつけるという話もあるぐらい、やっぱりそれぐらい、観光地に行けばそうじゃないですか。この浜川砲台というものをもっと戦略的に売り出していくというか、検討してくださいということでいいんだけれども、もう一言いただけないですかね。","respondent":"宮地地域振興事業部長","answer":"龍馬のことにつきましては、今ちょうど盛り上がってきております。食べたいな、数多くメニューをつくっていくことが大事かなと考えていますので、そのように取り組んでいきたいと考えています。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問","question":"いろいろデータを聞いてみますと、５０代を中心とした１,２００名の方々が、女性が特に来るようになるということを聞きました。品川区がどのように関与して、どう具体化していくかということについて、現状をまず説明を求めました。","respondent":"諸岡商業・観光課長","answer":"区はそういったご相談に応じて支援をさせていただきたいと考えています。まちづくりの観点から、あるいは文化芸術の面からも、品川区と連携を図りながら進めていきたいと思っているところです。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問","question":"１回の公演で１,２００名、しかも５０代の女性を中心に来られるわけでありますから、これはいろいろなところで活用できるじゃないですか。ですから、具体的に品川区は何をしていこうかということについてはまだ見えていない感じがしますね。","respondent":"久保田行財政改革担当課長","answer":"全庁的な連絡会をつくりまして、それぞれの今進んでいる状況等の確認をしながら、今後どういう展開で進めていこうかといったところを検討しています。","id":"exchange-102"},{"speaker":"伊藤委員","kind":"質問","question":"繰り返しますけれども、それから品川区をあらわすキャラクターの作成等について、検討してみてはいかがでしょうか。ご答弁をお願いいたします。","respondent":"諸岡商業・観光課長、中川原広報広聴課長","answer":"観光ＰＲ事業の一環として検討していますが、観光も含めた部分でのＰＲを進めていくように、協議検討を進めていきたいと考えています。 私どもとしても最大限、テレビ番組とかいろいろな雑誌について協力をして、発信力を高めています。紙だけでも８００件情報提供をしているところですし、いろいろなことをやっていきたいと思いますので、どうぞよろしくお願いいたします。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"これは午前中、方法はこれから考えていきますよということですが、認識等々、要望もあわせてしますが、接種回数はどう考えているのか。やはり区の関与が何らか必要なのではないか、整理するということを誘導するという形に持っていくべきではないかなと考えますが、いかがか尋ねました。","respondent":"吉田保健予防課長、工藤環境課長、諸岡商業・観光課長","answer":"品川区では個々の事情も考慮して、そういう慢性疾患をお持ちという方も考慮いたしまして６５歳からというふうに考えております。… 時々行うという方が３５％ということで、７５％におよぶ方が持っていただくという部分で、浸透が図れていると考えています。… １つのブロックではもう始められる状況にあるということで、そちらのほうもご案内しながら、ご相談に乗っているところです。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、その方たちも少し視野に入れていただきたいなと考えています。そこのお考えを少しいただきたいです。","respondent":"吉田保健予防課長、工藤環境課長","answer":"品川区で死亡が増えるのが実は７５歳以上なんですね。それを拡大して６５歳からやろうです。 レジ袋の削減の運動ですけれども、こちらは国のほう、環境省が推奨しています全国的な運動です。そういった中で展開されているものですので、私どもとしても引き続きその方針の中で啓発を図っていきたいと考えています。","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"私は２９４ページ、中小企業対策費全般についてお聞きしたいと思います。実際やっていることに対しては、今、経済状況は別として、実際に何か成果というのは出ているんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"私どもが行っているものづくり支援の成果ですけれども、個々事業を上げますと、すべて成果が上がっていると確信しておりますので、今後もその成果がより上がるよう続けていきたいと思ってあります。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問","question":"企業が一番困っているのは何なんでしょうかと思えば、まず資金不足、そしてやはり営業力の不足というのが圧倒的なんですね。皆さん一緒に行きましょうと、そういう体制を区のほうでも積極的に支援することが必要じゃないかと思うんですが、どう思われますか。","respondent":"福島ものづくり・経営支援課長","answer":"１つとしましては、こういう技術力があるので活用できませんかという働きかけを、中規模の企業に対して行っています。そちらとも連携をして進めているところです。","id":"exchange-107"},{"speaker":"須貝委員","kind":"質問","question":"ということは、たくさん品川区内にものづくりの企業はありますが、そういうところと実際会った実績、実際何件なんですか。そういうふうに長年やってこられたということならば、例えば何百件、何千件という企業とコンタクトをとれたんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区内といいますか、私どものほうにはビジネスカタリストという者が９０名ほどおります。これらにつきましても、販路拡大あるいは技術力支援に向けて活躍しておりますので、そういった面も進めながら今後展開していきたいと考えています。","id":"exchange-108"},{"speaker":"須貝委員","kind":"質問・要望","question":"それはいいと思いますが、そこで、この共通商品券が実際使われている分析というんですか。その辺は前も私はお聞きしたと思うんですが、簡単でいいですけれども、どんな状況ですか、説明を求めました。","respondent":"諸岡商業・観光課長","answer":"例えば婦人服店、ブティック等、商店街の中の家電販売店、それから商店街の中の旅行代理店等です。促進効果といいますか、消費拡大に向けての大きな効果があったものということを実感しています。","id":"exchange-109"},{"speaker":"須貝委員","kind":"意見","question":"１０％プレミアムをつけて、その地域にお金を落としてもらう。ちょっと時間がなかったので、意見として終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"武内委員","kind":"質問・要望","question":"猫については、平成２１年度の現在までのこの助成の申請数と実績を教えていただきたいのと、この２点をまずお伺いしたいと思います。そういうお声と、あと区のほうの評価というんですかね、これについてお伺いします。","respondent":"荒井生活衛生課長、諸岡商業・観光課長","answer":"１０月、１２月というふうに区切らせていただきまして、年５回に分けて申請を受け付けているところです。平成２２年度につきましては、できるだけそちらの方向で実施したいというふうに、検討しています。商店街の現状調査等を行い、２年目ということで、その調査に基づく事業ということで実施をしてまいりました。","id":"exchange-111"},{"speaker":"武内委員","kind":"質問・要望","question":"それから商店街につきましては、やっていらっしゃった内容はよく伺ったのでわかっております。そこにどうこう口を挟むことはないんですけれども、その辺について教えていただきたいのと、決まっているのか決まっていないのか説明を求めました。","respondent":"荒井生活衛生課長、諸岡商業・観光課長","answer":"本来このタイミングで手術をしたいという方に対しての十分な対応ができていなかったのではないかということもありまして、年間を通じた申請を受けて。その様子を見ながら… これから検討して決めていくところです。平成２１年度につきましては、中延の昭和通り商店街をモデル地区として、現在、事業を進めているところです。","id":"exchange-112"},{"speaker":"武内委員","kind":"質問・要望","question":"それから商店街につきましても、せっかくいい事業を始められたので、まず第一歩を踏み出されたことが非常に大事なことだと思います。課題があったら課題、それを明確にした上で次のステップにつなげていただきたいということで、要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問","question":"２９０ページの廃棄物対策費についてお尋ねいたします。ここは非常勤職員費というので１,６００万円上げてきているというのは、組織自体が何か違ってきているのかどうか、説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"臨時職員経費については約９５０万円余で、これについては平成２１年度と平成２２年度で変更はございません。平成１２年度から、派遣職員については好ましくないということがわかりましたので、１２月から非常勤職員という形の直接職員に変更したところです。","id":"exchange-114"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから動物死体処理費というところがありますけれども、このものについてはどういう仕組みになっているのか教えてほしいと求めました。同じように動物病院も手数料を払って、そこにお願いしなければいけないのかどうか、そのあたりを説明するよう求めました。","respondent":"太田品川区清掃事務所長","answer":"区で手数料２,６００円を徴収して、渡して、供養までしていただけるという形でやっているものです。処理については、今申し上げたものと同様です。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"死体処理手数料というのはどういうことで取るわけか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"持ってきたものを、今度委託しています事業者に渡します。個々ではなくて、全体でその骨等を管理していただいて供養をしていただく、こういうことになってあります。","id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"もっと極端に言えば、手数料もへったくれもなくなっちゃうと思うんだけれども、そのあたりはどういうふうになるんでしょうか。動物病院の方が知っている事業者にお願いをしてという仕組みができるんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"週１回ですが、仏教平和会というところへ処理委託をいたします。それから動物病院からの委託については、私どもではあくまでもご家庭から出た動物の死体ということで受けているところです。","id":"exchange-117"},{"speaker":"須藤委員","kind":"質問","question":"そのあたり、それはそれでできると思うんだけれども、いかがでしょうか。それともう１つ、入りのほうでは全然書いていないんだけれども、雑入に入れちゃっているのかどうなのか説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"１点目の仏教平和会へお願いしているというのは、本来、それを仏教平和会に事業委託をしているという考え方です。それから処理券については、廃棄物手数料の中に入ってあります。","id":"exchange-118"},{"speaker":"須藤委員","kind":"質問","question":"有料ごみ処理券の経費が事務系だと幾らで売っていますよね。それの入りがどこに入るのか、雑入に入るのかどうか説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"８４ページの廃棄物処理手数料のところに入ってあります。","id":"exchange-119"},{"speaker":"川西委員","kind":"質問・要望","question":"これはどうしようもないから、これはお答えは結構ですから、かわいがっている人に対しての助成をしていただきたいということで終わります。若いときに食生活が悪いとか、そういうことに起因するものなのかどうか伺います。","respondent":"矢野品川保健センター所長、山岡健康課長","answer":"未受診者への対策ですが、これは乳児健診と同じように、電話あるいは訪問等をまず行います。回答していただいて、さらに対応が必要な方については… 未熟児は一般的には２,０００ｇ以下と言われておりますが、２,０００ｇを超えていても、この医療費を公費負担でということになっております。… むくみが出てきたりということで、ひどいものに関して子癇を起こしたりするようなことがありますので、入院治療等が必要になってまいります。","id":"exchange-120"},{"speaker":"川西委員","kind":"質問・要望","question":"ちょっと勉強不足で確認したいんですが、結果的には親の負担なしという確認でよろしいですね。せんだって２月の消費生活展と一緒に開催されました環境フェアというんですかね。","respondent":"工藤環境課長","answer":"振動規制法、悪臭防止法、環境確保条例等のさまざまな規制があります。それに対しまして審査、指導し、公害の未然を図るためにかかる費用です。","id":"exchange-121"},{"speaker":"南委員","kind":"質問","question":"区長の思いというのを伺ったわけですけれども、今はもう本当に空いているところがいっぱいあって、あそこに住む者の１人として非常に心配なんです。したがって、区長がああいう状況をどのようにご覧になっているか、ぜひとも区長のご見解をまず伺っておきたいと思います。","respondent":"諸岡商業・観光課長","answer":"八潮の皆さんのことも考え、パトリアの活性化も含めて考えて、そのような措置をしているものです。そういったことで、八潮の大切な商業施設と認識しているものです。","id":"exchange-122"},{"speaker":"南委員","kind":"質問・要望","question":"パトリアの皆さんにちょっとお話を伺ったことがありまして、そのときにお話を伺ったのは、どうやって人を寄せるかということで非常に苦労していると。ですから、２４時間都市化の問題も含めて、開発と低炭素のまちづくりという点でどんな議論がされているのかを教えてほしいと求めました。","respondent":"諸岡商業・観光課長、工藤環境課長","answer":"平成２１年度におきましても、２回にわたってイベントを行っておりますので、区はそのために支援をさせていただいているところです。そのあたり、そういうこととも連携を図りながら… 先ほど委員がお話ししましたように、小水力、波力発電等の研究も進められているという部分も十分認識しております。","id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"１０分のところで買い物ができる、そういう施設があるわけですから、廃れさせない努力を本当にしていただきたいと思うんです。さっき申し上げた開発による数字と、いろいろな対策をとった上での数字がどういう事態になっているのかをちょっと教えてほしいと求めました。","respondent":"工藤環境課長","answer":"大きな総量としては、品川区の総量の約四十数パーセント、２分の１近くなっているです。今後私どもも、業務部門の数字は、引き続き把握に努めてまいりたいと考えておりますので、その中で対応をとりたいと考えています。","id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"せっかく低炭素社会実現に向けてという項を起こして、きちんとされているし、ですから、私は数字をしっかりつかむべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"三上委員","kind":"質問","question":"職員の皆さんの中でどなたでも結構ですから、ここへ行かれているかどうか、ちょっといかがでしょうか。やられているかどうかということで、何か付加価値をつけるというようなことをやられているかどうか、ちょっとお伺いしたい。","respondent":"山岡健康課長、阿部経理課長、工藤環境課長、太田品川区清掃事務所長、諸岡商業・観光課長","answer":"ただ、そういう健康情報のサイトを立ち上げてやっていこうという動きは、地方の幾つかのところで起きているということは承知しております。… ＬＥＤの検討状況についてですけれども、まず、来年度予算に第二庁舎の３階のロビーの部分のダウンライトをＬＥＤ化するという形で予算を組んです。… ビックサイトで行われた展示ですけれども、私どもの職員で行っているかどうかというのは把握してございません。","id":"exchange-126"},{"speaker":"三上委員","kind":"質問・要望","question":"私もぜひ４月以降には行って、それは確認してこようと考えています。いろいろなドアにでも活用できるということがあったわけですから、そういった点についてのご検討をしてほしいと求めました。","respondent":"工藤環境課長、太田品川区清掃事務所長、諸岡商業・観光課長、山田副区長","answer":"温暖化対策における新しい技術のいろいろなご提案だです。私どもも振動発電、先ほど委員ご提案の遮熱塗装における消熱塗料につきましては研究してま… 現況を確認して、適切に対応していきたいと考えています。 プレミアム付商品券の件につきましては今後十分研究をさせていただきたいと思ってあります。 区長が本会議等でもご答弁しているとおり、個店の振興ということで今回進めしていますので、ぜひご理解いただきたいと思います。","id":"exchange-127"},{"speaker":"鈴木委員","kind":"質問","question":"産業経済費が１項しかないというのは、３０１ページ、品川技術ブランドＰＲ事業の点について簡単にお聞きしたいと思っています。その中で特定健診というのは、区が保険者としてやっていく部分だと思うんですが、この健診について簡単にご説明いただけないか尋ねました。","respondent":"山岡健康課長","answer":"平成２０年度から、それまで私どもが区民健診でやっていた部分も含めて、各医療保険者が特定健診を実施するということになりました。ここの２６９ページの健康診査のところに、数字がぐっと減っている、そういうものです。","id":"exchange-128"},{"speaker":"鈴木委員","kind":"質問","question":"区として新しい政策をつくったことをどう判断していくかということで、実際４人で行かせていただいて、事業が変わっているんです。この点は、なぜここで変わってきたのかなと、ちょっとそこを説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"委員がおっしゃいましたように、今年平成２１年度につきましては、海外進出事業ということで行いました。区内２つ、海外１つということで、そちらの経費の中で海外進出も含めた支援を行っていくという形に変えたものです。","id":"exchange-129"},{"speaker":"鈴木委員","kind":"質問・要望","question":"継続的にやっていただきたいというお声、それと区内の技術力をしっかり海外に伝えていきたいという思いも大分お聞きしました。すべてが一緒ではなかったですし、１つ私のほうで気になっているのは、向こうで現地の企業の方と我々のほうでお話しさせていただきました。","respondent":"山田副区長","answer":"今回思い切って、ＪＥＴＲＯの中の１室をお借りして、マッチング等を具体的に進めさせていただきたいと考えています。今年度また新たにやりますけれども、より広くお声をかけながら、進めさせていただきたいと思っています。","id":"exchange-130"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう１点のほう、二十三区清掃一部事務組合について簡単にお聞きしたいと思います。品川区は今後どう考えていくのか、二十三区清掃一部事務組合をそのまま続けていくんだと認めていくかどうかということを確認したいと思っています。","respondent":"久保田都市環境事業部長","answer":"今お話に出ていた１１５％余力云々については、二十三区清掃一部事務組合等を踏まえて、やはり今後の検討になるかとは思っております。区としては、当面の間は今の体制を維持しながら、その辺のことについても考えていくということになるかと思います。","id":"exchange-131"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":117169,"voices":335}},{"id":"h22-20100315-3","meetingId":"h22-c-budget","date":"2010年3月15日","dateIso":"2010-03-15","committee":"予算特別委員会","time":"午後５時５１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件整理しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"１目河川総務費の中の、この２点について、お伺いいたします。多分これは河川管理費の中に入ってくると思うんですけれども、３２１ページの目黒川のことについて、ちょっとお伺いしたいと考えています。","respondent":"青木都市開発課長","answer":"ご説明しましたとおり、平成１７年３月から近隣の方に説明をいたしまして、市街地再開発事業を施行しているというものです。目黒川における、より水に親しむ空間ということで、両岸で整備をしてきたものです。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問","question":"答弁の中で、地元の方との調整等とあったと思うんですけれども、昨年、目黒川の水位が急激に上がった際に、この場所が浸水したと聞いているんですけれども、それについての見解と、今後のあり方、安全性も含めてお伺いしたいと思います。","respondent":"青木都市開発課長","answer":"これは、水が引いた後、清掃して衛生を保っていくということを、管理の中でやっていく予定です。６月の全面オープンに向けて最終的な調整をやっているんですけれども、現在、最終的な設計協議を進めているところです。","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひ、目黒川においては、そこのあたりの管理をしっかりとやっていただきたいと思っておるんです。安全性というところは、非常に念には念を入れて考えていかなければいけないと思うんですが、そこのあたり、もう一度、お願いいたします。","respondent":"青木都市開発課長","answer":"最終的に整備して、オープンするまでには品川区のシステムを、ここにも警報を発報するものを設置してまいります。なおかつ、人的にも注意を喚起するという形で、ほかの護岸と同様、あるいは、ここはより念入りな対策をしていくつもりです。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問・要望","question":"３１５ページの涼のみち整備事業についてなんですけれども、今、何カ所ぐらいで行われているのでしょうか。今後、このような整備を増やしていく予定はあるのか尋ねました。","respondent":"齋藤道路公園課長","answer":"平成１８年、豊商店会、平成１９年、平和坂通り商店会、今年度、宮前商店街の３カ所で実施いたしました。約１０カ所ほどピックアップしておりますので、商店街のお声を聞きながら、１年か２年おきで順次整備をしていきたいと考えています。","id":"exchange-004"},{"speaker":"井桁委員","kind":"質問","question":"そこのところも、ちょっとお伺いしたいと考えています。大体、一般の整備舗装と比べると、どのぐらいの額が高くなるのかということを説明するよう求めました。","respondent":"齋藤道路公園課長","answer":"再開発の関係で、大崎で４カ所ほど、遮熱性舗装の道路整備をしております。遮熱性舗装だと１万７,０００円、５割増し、２倍という形で大変高額なものになっております。","id":"exchange-005"},{"speaker":"井桁委員","kind":"意見","question":"ですので、歩いていて実感をするのかなとは思うんですが、やっていることのＰＲが、やはり必要だと思うんです。そこのあたりの考え方をお願いいたしますとの意見を述べました。","respondent":"齋藤道路公園課長","answer":"整備箇所には看板を設置しておりまして、ご案内申し上げております。もう少し発信をしなければいけないと考えていますので、今後、取り組んでまいります。","id":"exchange-006"},{"speaker":"井桁委員","kind":"意見","question":"品川区は涼のみちでかなりいろいろとやっているんだと、環境についても考えているんだということをＰＲするいい機会だと思いますので、看板もそうなんですが、やはり、もうちょっと目立つような形でのＰＲをぜひともお願いしたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"私の記憶が間違いでなければ、設置していただいて１０年近く経つでしょうか。エレベーターに関してのご意見とか、ご要望とか、何か所管に届いておりますか尋ねました。","respondent":"松代都市計画課長、齋藤道路公園課長","answer":"大井町駅につきましては、平成１４年に設置をして、ご利用いただいております。ご質問にありました、その利用に当たっての利用者の声、区民の声ということでは、私どものところには、直接まいってはございません。 それを少しずつ改良して、段差を解消して、車いすや乳母車の方が入れるようにということで、事業を進めております。今、２１０カ所の未整備のところのうち８１カ所が終わっております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"ご見解をお伺いいたします。どうしても段差ができてしまうということはあるかと思うんですが、どれぐらいの割合でされているものなのでしょうか、説明を求めました。","respondent":"松代都市計画課長、齋藤道路公園課長","answer":"いろいろとそういった形で、電動車いすの方の利用等に何らかの形で対応ができると思いますので、要請をしてまいりたいと思います。構造等が許せば、なるべくそのような形で進めるように、こちらも考えていきたいと考えています。 一つの公園に、月２回巡回しておりますので、そのたびにいろいろ確認をします。それから、年に１回、内部の段差があるか、ないかの確認をして、点検、補修をしています。","id":"exchange-009"},{"speaker":"金野委員","kind":"提案","question":"どうしても流れて落ちるということであれば、これは一つの提案なんですが、こういったことはどうなんでしょうか。外でも使えるという、高さの低いスロープを見たことがあるんですが、そういったものを活用するという考え方はどうなんか尋ねました。","respondent":"齋藤道路公園課長","answer":"それは何かというと、地下に水脈があって、１００本を超える見事な桜が咲きます。委員にアイディアをいただきながら、維持管理の充実に努めてまいります。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"改定のときは、関係ないという話なのか、その辺の手続の流れを教えていただきたい。それから、西口の整備検討委託については、簡単に概要を説明してほしいと求めました。","respondent":"松代都市計画課長、青木都市開発課長","answer":"市街地整備基本方針というものを持ってまちづくりを進めてまいりましたが、平成２２年度には、まずやろうです。素案をつくる中で、都市計画審議会に諮問をいたしまして、答申をいただくというような形で進めたいと考えています。下のほうにいっていただきまして、下から３行目、大崎駅西口地区周辺区域整備検討委託というものがあります。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"都市計画審議会にも諮問をかけていくということですから、住民の皆さん、区民の皆さんの意見を聞くことになっていくんだろうなと思います。この６０haの線引きから外れた地域で、あわせてそういうものを、これから開発計画としてつくり上げていくということなんか尋ねました。","respondent":"松代都市計画課長、青木都市開発課長","answer":"今回のまちづくりマスタープランの計画ですけれども、市街地整備基本方針と同様に、住宅マスタープランも、平成１３年に見直しを行っております。そういったものを検討していきたいと考えているところです。地元の方々の思いを踏まえて、あるべき方向、一定の共有できるまちづくりの方針を定めていこうということで検討するものです。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"１,０２６人中７７２人、７５％ぐらいの方たちが、高さ制限を設けてほしいという声を出していらっしゃるんです。線を外れた地域の中で、区として積極的に支援をしていくという体制になっていくのかどうか、その辺もお聞かせ願いたいと思います。","respondent":"松代都市計画課長、青木都市開発課長","answer":"地域の方々の総意に基づいて、いろいろ議論をしていただいて、絶対高さを定めております。そういったことを踏まえまして、一つの検討課題だと考えていますので… 必要に応じてより積極的に開発を進めていくべきところ、ここは抑制するべきところというのは、それぞれその事情によって変わってまいります。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"ぜひ、その辺の検討をしっかりとやってほしいと求めました。それに伴って品川区でも同じような開発が行われていくわけですから、やっぱり改めて、再開発に対する考え方を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"稲川委員","kind":"質問","question":"それから、３３３ページの密集住宅市街地整備促進事業の中の、広場整備等工事費について、お伺いいたします。おおむね５年おきということですから、この次は平成２３年に行われると思うんですが、どうなのか。","respondent":"松代都市計画課長、小野土木管理課長、吉川防災整備担当課長","answer":"委員からもお話がありましたように、５年に一度、実施するものです。この実施の中身ですけれども、調査方法としては、現地調査、調査員による目視で… 地目、境界等を明らかにして、公図の正確性を期すという形でやっているものです。東京都の地域危険度調査ですが、この調査は、現況を知る上で、一定の参考とすべきものと考えております。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"何か、僕のイメージとしては、現況調査というのは、ある意味、品川区がずっと蓄積されてきたデータをもとに、また品川区が自ら地域を回って、変化がどのようになっているかというのを調べるのが土地利用現況調査だと思っていたんですが、その都度、新たにやるということでよろしいのか尋ねました。","respondent":"松代都市計画課長","answer":"これは、東京都が全域を対象にして調査をかけているものでございまして、それが５年に一度ということでまいってまいります。それを東京都がまとめて、全都民に公開するというような形ですので、毎年つくっているものではございません。","id":"exchange-016"},{"speaker":"稲川委員","kind":"意見","question":"毎年つくっていない、５年に一度というのはよくわかっているんです。５年に１回、また一からやり直していくのか、どうなのかということだけを聞きたいとの意見を述べました。","respondent":"片田建築課長、吉川防災整備担当課長","answer":"土地利用現況調査は、区が東京都から委託を受けて実施する、それが都市計画化になるわけです。構造体別とか、地域にどのような分類がされているのかということも総合的に含めて… 地域危険度の平成１３年度のデータをもとにしているということの信頼性ということについてですが、若干古いデータということになりますので、一定の参考とすべきものととらえております。","id":"exchange-017"},{"speaker":"稲川委員","kind":"提案","question":"遮熱性塗装を提案させていただき、第２庁舎の駐車場の遮熱性舗装をやるということなんですが、どうなのか。４点、お伺いしますとの意見を述べました。","respondent":"齋藤道路公園課長","answer":"ここで固まっていけば、意識啓発だけではなく、環境とビジネスを結びつけて、区内の方たちの仕事を増やせることができないかと考えたものです。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"１点、お伺いしたいのは、アスファルトに何かを混ぜて新たに舗装するという感覚ではないですよね。遮熱性舗装と書いてあるので、その辺ちょっと改めてお伺いしたいと思います。","respondent":"齋藤道路公園課長","answer":"道路でやる場合は、アスファルトからやり直しをして、アスファルトを１０cmぐらい敷き直しをして、その上に塗ります。今回の駐車場につきましては、表面に塗るだけです。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問・要望","question":"３３３ページ、そうなのか、どうなのか。その２点をお願いします。","respondent":"吉川防災整備担当課長","answer":"防災広場と名付けておりますのは、密集事業および防災生活圏促進事業でつくっている公園のことです。それから、広場整備工事費で対象にしておりますのは、二葉四丁目のＪＴ跡地のほか３カ所、計４カ所の整備を予定しております。","id":"exchange-020"},{"speaker":"稲川委員","kind":"意見","question":"それが公園と広場になってしまうと、どうすみ分けをするのか。そういうのは法律的にオーケーなのか、どうなのかだけ説明を求めました。","respondent":"小野土木管理課長","answer":"公園と広場の法的な違いということですけれども、都市公園法、それから品川区の公園条例、こういうものに基づいて、一定の規模において区分けしておりまして、そういう点で、広場と公園という形で決めております。","id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、仮定的に、どんな感じでいくのかというのと、また今後についてお聞きしたいというのが、目黒川のことです。先ほど申し上げた４番目の質問として、３０年後を、河川の両脇がどうなっているかという形でお答えをほしいと求めました。","respondent":"藤田水とみどりの課長、青木都市開発課長","answer":"平成２２年度についても、目黒区もまた実験をしたいと言っておりますので、その辺あわせて進めていければと考えています。それから、景観のほうですけれども、まず認定のスケジュールですが、この３月、４月に… 品川区の固有職員だけでは、一時的な事業量に対応し切れないということで、専門的な立場からの独立行政法人を活用しているものです。１０年、２０年先には、私ども期待しています。","id":"exchange-022"},{"speaker":"高橋委員","kind":"確認","question":"これに対応するものは、総務費の運動公園施設費の１億９４２万円でよろしいのでしょうか。これは確認なんですが、このランニングコストは７５％という形で、利用者の方々の使用料で負担されているという理解でよろしいか尋ねました。","respondent":"齋藤道路公園課長","answer":"それ以外の月曜日から金曜日の放課後は野球、土日も、全日少年野球の皆さんがお使いです。利用の歳出、歳入の関係ですが、委員のご指摘のとおりで、利用率の７５％相当を利用者にご負担をいただいて、維持管理を行っております。","id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"とすると、７５％というのは、鈴木委員も指摘されていましたが、品川区の使用料の割合が大きいと。テニス等でしょうか、少年野球の使用料収入がわかれば、説明するよう求めました。","respondent":"齋藤道路公園課長","answer":"南ふ頭公園を例にしますと、野球が６５％で、ミニサッカーが３５％になります。サッカーが１,２８０万円、テニスが３,３４５万円で、少年野球は８６万４,０００円になります。","id":"exchange-024"},{"speaker":"高橋委員","kind":"質問・要望","question":"このグラウンドを、これまでと同じように利用したいとお考えになるのは、非常に大きなご要望だと思います。７５％がカバーできているというお話を伺いましたが、おおむね３０％前後、受益者負担として利用者にお願いするとあります。","respondent":"齋藤道路公園課長","answer":"人工芝で野球が４面もできるようになりますけれども、こういった区はほかにありませんので、施設の充実ということで還元を図りたいと思います。青少年の健全育成という視点で、免除ということの検討については、横断的に庁内で議論をさせていただきたいと考えています。","id":"exchange-025"},{"speaker":"高橋委員","kind":"質問・要望","question":"明日の「輝く笑顔住み続けたいまちしながわ」をつくる、子どもたちからの熱い要望を代弁させていただきました。下水道に関する政策に力を入れているところなども、お願いしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる２３区で１９番目ぐらいに位置しておりまして、耐震化をもっと促進する必要があるだろうと考えましたので、新たに事業化した次第です。職員も、地元との意思疎通も図ることが十分にできますので、今回、受託して、東京都と一緒に促進しようということになりました。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"私も３２７ページの、次のページの３２９ページの仮称鮫洲入江埋立公園整備実施設計ということで、お伺いします。もう少し具体的に、子どもたちにどのようなアイディアを出していただいているのか、教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"子どもたちが全方向に自由に滑りおりられるような滑り台の設置や、そういったアイディアもありましたので、採用できるのではないかと考えております。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"もうちょっと具体的にお聞きしたかったのは、実は、午前中は幼児たちがこの公園を利用しています。学校が終わった小学生たちが帰ってきたときに、使えるような遊具があるのか、その辺の詳細といいますか、教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"具体的な内容につきましては、これから地域の方々とも意見交換を行いますので、その中で、また配置については詳細に検討してまいりたいと思います。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"これからいろいろなことを地元の方たちから伺いながら、これはちょっと要望なんですが、ぜひ設置してほしいと求めました。すごく素敵な公園になるので、ブルーシートを敷いてお花見ができるようなスペースはあるのか、教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"ただ、中で、桜を見ながら、いわゆる見晴らしがいいような形で楽しめるように、ちょっとした机等の配置も工夫する予定です。地面におきましても、ちょっとしたスペースで、広げて花見ができるような空間は、一応、確保しています。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"実は、今度はその隣のグラウンドのことで、ちょっとお伺いいたします。それから、この平面図を見ますと、自転車置き場をお考えになっていらっしゃるのかどうか、ちょっと教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"お尋ねのＡＥＤについては、設置する方向で検討しております。それから、自転車の駐輪場ですけれども、グラウンドと遊戯コーナーの間のところに、今の台数よりも少し多くなるような形での確保を検討しています。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"その辺、ちょっとご配慮ほしいと求めましたので、よろしくお願いしたいと思います。その辺のお考えがありましたら、どのような自転車置き場を考えていらっしゃるのか、教えていただけますか。","respondent":"藤橋都市整備下水道課長","answer":"自転車置き場の具体的な配置と、出入りのしやすいような形については、これからの設計の中で検討させていただきたいと思います。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"どうか、地元の皆さんも楽しみにしておりますので、よろしくお願いしたいと思います。今後の計画予定を教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長","answer":"鮫洲入江埋立公園につきましては、現在、東京都下水道局が、埋め立てた部分に下水の水をためる雨天時の貯留池を築造しています。東京都下水道局の工事が、平成２２年度までかかる予定でございまして、それが終わり次第、平成２３年度から工事を進める予定で考えております。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"これも、これからいろいろと計画が出てくると思いますが、周りの方たちへの周知の方法といいますか、今後、どのようにお考えになっていらっしゃるのか、教えていただけますか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"これまでも、下水道局の工事の際に、地域の方々への工事説明会を行ってまいりました。引き続き、公園の整備に当たりましても、その計画等につきましては、地域の方々との意見交換を行いながら進める予定です。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"周りの方は楽しみと同時に、不安をお持ちになっておりまして、その辺、地元の方によくご意見を聞いていただいて、お話を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"この金額なんですけれども、１４３ページの収入のところから引いて、８,７９９万４,０００円が区の持ち出しだと考えていいのでしょうか。３３９ページの環境共生住宅助成なんですけれども、なぜこれは二本立てでいっているのか、説明を求めました。","respondent":"藤田水とみどりの課長、柏原住宅担当課長","answer":"歳出については１億７,６００万円ということで、差し引き４,６００万円ほどのマイナスになっているという形になってあります。差し引いた金額で、残りがあった分について分配をするということで、その際には、区に７割… ですので、太陽光パネル等も、工事等が伴いますので、こちらは大きなほうでやらせていただいております。省エネルギー設備導入については、今のところ、器具の扱いですので、平成２２年度については別々の計上にしています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"それはなぜかといいますと、中期、長期的にどう考えていくかということをお伺いしたいんです。その分岐点について、お伺いしたいんです。","respondent":"藤田水とみどりの課長、柏原住宅担当課長","answer":"レジャー産業の動向がよくわかる業者に入っていただいて、そういう中で検討をしていきたいということで、中長期的な考え方を整理していく考えです。ありませんが、幾らかかってもいいとは思ってございませんので… 平成２２年度につきましては、内部で調整しまして、なるべく一本化できるような形で窓口をやっていきたいと考えています。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"共生のほうですけれども、では、確認ですけれども、一本化するということでよろしいのですね。私は存続していただきたいという気持ちで質問させていただいていますし、その辺の答弁をもう１回、お願いいたします。","respondent":"柏原住宅担当課長、藤田水とみどりの課長","answer":"一本化できるような形に内部で調整したいと考えております。委員から、先ほどもお話がありましたとおり、社会貢献の面でも、しながわ水族館のある意義というのは非常に大きくあります。","id":"exchange-037"},{"speaker":"山内委員","kind":"質問","question":"３１１ページの街路樹等維持管理費、３２７ページの子ども達のアイディアを活かした公園整備について、この２点で伺います。その辺の２点を、伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"保存樹という形である本数は２７３本、保存樹林ということで、一定程度の面積があるといったところを指定しているところが１４カ所あります。区指定の天然記念物等の指定をした大きな木、いわれがあるような木、こういったものもあります。","id":"exchange-038"},{"speaker":"山内委員","kind":"質問・要望","question":"ところが、予算書には、数字を記載しているというところで、会派を代表いたしまして、その場所はどこなんだと、ずっと伺ってきました。やっぱり知っておくべきではないかと思いまして、これはちょっとしっかりとした答弁をいただきたいと考えています。","respondent":"藤橋都市整備下水道課長","answer":"できるだけ活かしていこうという考えで、今回、そこを選定した次第です。全体の模型で出している公園については、引き続き、用地の確保に努めて、実現していくという対応で臨みたいと考えています。","id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"新たな土地を求め、伺ったように思うんですけれども、もちろんまず場所が大事な部分になってくると思うんです。いつできるんですかというようなことに、第３弾と、やっぱりこれは続けていかれるべきだと思うんです。","respondent":"藤橋都市整備下水道課長","answer":"第２号といった話ですけれども、できるだけアイディアを生かしていこうというふうな方針で、進めております。積極的に活用するという方法で、今後、検討してまいりたいと思っています。","id":"exchange-040"},{"speaker":"石田委員","kind":"質問・要望","question":"３１１ページ、３３１ページ、五反田駅周辺地区コーディネート業務委託についてお伺いします。時間があったら、３３３ページの防災生活圏促進事業もお聞かせほしいと求めました。","respondent":"柏原住宅担当課長、齋藤道路公園課長、青木都市開発課長","answer":"世帯にしますと、１８世帯程度ですけれども、月数が多くなっておりまして、約２５０月程度ありますので、そういったものを徴収していきたい。もう退去して… 昨年度は、６万円、７万円までいってしまいまして、１,０００万円足りませんでした。今年度は落ち着きましたので… にぎわいゾーンの検討ということで、どうあるべきかというのを検討してきたものが、平成２１年度までの作業です。","id":"exchange-041"},{"speaker":"石田委員","kind":"質問・要望","question":"平成２２年度、約４億円の予算を組んで、ＬＥＤ化に向けて取り組むということを伺いました。防災の場所にしてほしいとか、そういった要望等もありますので、また地域の声を聞いていただきたいと考えています。","respondent":"齋藤道路公園課長","answer":"ですから省エネ効果、ＣＯ2排出効果は遜色ありません。毎年１億円のコスト増というのはなかなか厳しいので、価格動向を見ながら、適切な時期にＬＥＤに切り替えたいと考えています。","id":"exchange-042"},{"speaker":"石田委員","kind":"質問","question":"あまり時間がないので、防災生活圏促進事業の部分で１点だけお伺いします。約１３４万円というのが出ているんですが、品川区で用地を獲得するのに１３４万円でどの辺が買えるのかなと示すよう求めました。","respondent":"吉川防災整備担当課長","answer":"防災生活圏促進事業の用地取得費ですが、これは、大原通りの拡幅用地です。","id":"exchange-043"},{"speaker":"石田委員","kind":"意見","question":"今も、ここ何日か地震が相続いていますし、ほんとうにいつ来るかわからないので、そういった意味でも、防災生活圏促進事業も、今もう既にしっかりと進んでいるとは思うんですが、今後、さらに進んでいただけるようにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"若林委員","kind":"質問・要望","question":"去年のいつごろですからか、ほんとうに動いているのかどうかというのを、一つお話を聞かせてください。どのように設置を行っていくのか、遊具の選定も含めて、お話を伺えればと思います。","respondent":"齋藤道路公園課長、藤田水とみどりの課長、藤橋都市整備下水道課長","answer":"業者と路線ごとに決めまして、木によっては、毎年やらなければならない木と、３年に１回でいい木もありますので、見ながら行います。… 溶存酸素量が２から５とか、実験前はほとんど０の状態だったのが、生物が生育できるような状況まで数値が増えてきているところです。… 区の総合実施計画の中で、平成２０年度に、鈴ケ森公園の一部に健康遊具を設置した経緯があります。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問・要望","question":"たしか、今、目黒区のほうでやっていたのは雅叙園の前あたりですかね、あの距離は、ほんとうに２００ｍないぐらいですかね。ちょっと大きなところで、お答えをほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"その活動を通じて、地域のコミュニティにまた広がっていくと考えております。目黒区も協力しながらやっていかなければいけないことだと考えていますので、地域の皆、その後の活用につなげていきたいと考えているところです。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問","question":"私は、３０５ページ、交通安全啓発のところ、３２５ページ、品川浦周辺地区まちづくり推進費と、東急大井町線沿線まちづくり調査費のことを伺います。それから、東急大井町線沿線、これも幅広く、数多くの駅がありますが、どのあたりを想定されているのか、対象と内容を伺えればと思います。","respondent":"諸石交通安全担当課長、松代都市計画課長","answer":"それから、スタントマンの教育の規模ですけれども、来年度も、区内で４回実施をしたいと考えておりまして、予算の計上をしています。こうした教材を購入して教室を開催しておりますが、区といたしましても… 区としても支援をしていきたいということと、すべての事業手法の検討や、基礎調査を行っていきたいというものです。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"質問・要望","question":"バランス感覚を持って話が進んでいるのではないかと思うので、この２点とも、いい方法で継続をされたらいいのかなと思いました。視聴覚も検討されるという話だったので、うまく活用されたらいいという要望を含めて、ご答弁をほしいと求めました。","respondent":"諸石交通安全担当課長","answer":"視聴覚の関係は、今、いろいろな内容の教材が出ていることを承知しております。その中で、自転車と歩行者に係わる事故の関係、そうした教材を、区のほうで導入について積極的に検討していきたいと考えています。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、３３７ページの住宅・建築物耐震化支援事業の中で、マンションへの支援について伺いたいと思います。生活再建、時間軸に応じてそれぞれ課題があるんですけれども、とりわけマンションについて伺いたいと思います。","respondent":"吉川防災整備担当課長","answer":"マンションの耐震化の支援ですけれども、耐震改修促進計画で、区内マンションは現時点で、９２％の耐震化率に達しておりますが、今後、さらに促進する必要があるということで、耐震化アドバイザー派遣、耐震化診断の助成事業などを実施しています。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"マンションの分野では、どんな教訓があるのか、伺いたいと思います。区内では７２２棟とありましたけれども、その進んでいるマンションは何件なのか、ご説明ほしいと求めました。","respondent":"片田建築課長、吉川防災整備担当課長","answer":"阪神・淡路大震災があった後、国のほうでは、耐震改修促進法を平成７年に制定しています。耐火建築物ということでは、燃えにくいという中で、そういう状況を認識してきたです。 マンションに係わる耐震化支援事業の実績ですけれども、平成２０年度から事業を実施しておりまして、１３回行っています。平成２０年度からの事業ですので、追跡調査を、木造住宅と一緒にやる予定です。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"どういう状況なのか、現状の把握について、いかがでしょうか。耐震とあわせて、補強工事への助成支援もしっかりやっていく必要があると思うんですけれども、この点はいかがか尋ねました。","respondent":"吉川防災整備担当課長","answer":"マンションの追跡調査ですが、平成２０年度、２１年度で、アドバイザーを派遣した１５棟については、来年度、行う予定です。９２.１％という耐震化率を達成しておりますので、現時点におきましては、助成対象にしていないです。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"マンションに対してもしっかりとアンケート調査を行って、まず実態をつかむ必要があるのではないかと思いますけれども、いかがでしょうか。そういうところをしっかり教訓を踏まえて、計画に反映すべきだと思うんですけれども、いかがか尋ねました。","respondent":"片田建築課長","answer":"私どものほうの限度が１５０万円ほどの支援を行いますので、診断費用の大体３分の１、これは逆に、これまで支援してきているという状況です。どういう支援の仕方があるのかというところもありますので、そんな中で、検討項目の中で考えることもあり得るのかなと考えております。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局何もしないか、この意見の三分化して、折り合いがつかなくなってしまったという話もありました。検討すべきだと思うんですけれども、課題をどう考えているのか、ご説明ほしいと求めました。","respondent":"片田建築課長","answer":"単に工事費用を助成するというお金の問題だけではないと考えています。確かに、どのような支援のあり方があるのかということをあわせて、方策についてはローリングの中で考えていきたいと考えています。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"３２４ページ、３２９ページ、お伺いいたします。１点目は、３３７ページの耐震シェルター等設置助成とありますが、１,２００万円の内訳を示すよう求めました。","respondent":"吉川防災整備担当課長","answer":"それから、その他のシェルターなどの設置助成が、３０万円上限で２０件、６００万円ずつで１,２００万円になるです。それから、耐震シェルター等の「等」ですが、東京都が紹介しております工法・装置ということですので、シェルター以外にも若干含まれているです。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"２件ということだったのですが、どういうことで進まないのか、区民の声がどういうものなのかということを教えてほしい。それから、品川シェルター開発にかかった費用というのは、総額幾らになっているのか、お伺いします。","respondent":"吉川防災整備担当課長","answer":"現在のところ、品川シェルター実用化、平成２１年度は実施に至ったのが１件、相談は５件ほどきています。多くの実施に至らなかった声といたしましては、１部屋、助成対象が高齢者等に限られているというところが若干不満の声がございました。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"わりと対象はそんなに大人数の家族ではないだろうと思うと、そんなに調整がつかなかったというのは、どういうことかなと思うんです。その１部屋で、荷物を運ぶということにすごく二の足を踏む世帯があるのではないかと思うんですが、そういった状況はないのか尋ねました。","respondent":"吉川防災整備担当課長","answer":"実は、若いご夫婦で、ご夫婦で家のインテリアの関係で意見が合わなかったです。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"お伺いしたところによると、実際に、部屋の中に木枠がそのまま残る。それとも、パトロールだけの委託なのかというところを、ちょっとお伺いしたいと思います。","respondent":"齋藤道路公園課長","answer":"ただ、土日、祝日は１１０日ぐらいはありますけれども、民間との契約関係がありませんでしたので、今回、土日もやりたいということです。ほとんど９割方の工事はできますが、うちの区の職員が現場を見て、対応方を考えるです。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"土日、休日で、そういう事例事故発生件数というのがどのぐらいあったものなのか。こういった事業をするに当たっての根拠だと思いますが、そちらを、５年間ぐらいの推移で伺います。","respondent":"齋藤道路公園課長","answer":"過去５年間の推移という数字はございませんが、年平均で３０件から３５件の事故があります。一つの便器から水がずっと２日間流れ続けるかと、こういうことがございましたので、予算化をさせていただいたです。","id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"年間を通して３０件とかというのが、２３区初ということで、そのことでどうなのかなということは一言意見としてお伝えしたいんです。こういうところは区が率先してやるべきと思うんですが、そのことについて、お考えがあれば説明を求めました。","respondent":"齋藤道路公園課長","answer":"それを、きちんと対応しますということが一つです。８００万円ほど予算計上させていただきましたが、安心・安全の視点という形で言うと、決してむだなお金だとは考えておりません。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"３２４ページの景観まちづくりなんですけれども、先ほど当初予定とのスケジュールということで、私も伺いたいと思いましたが、わかりました。以前にお聞きしたときに、都の計画を超えた計画をつくるつもりはないというお話を伺っていましたけれども、伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"東京都は景観計画を持ち行政を進めているわけですが、こうしたエリアの中で、ほとんどが一般地域という扱いになっております。一部分、私どもが景観行政団体になって景観計画をつくる際には、こうした地域性を十分に考慮した景観計画をつくりたいと考えているものです。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"その辺を、今まで区民にどういうふうに投げかけてきたのかということを、お伺いしたいと思います。これは、具体的にはどういう内容のものなのか、一緒にお願いします。","respondent":"藤田水とみどりの課長","answer":"これまでの検討の経緯、それから、地域へのご説明という部分ですけれども、昨年、パブリックコメントを実施しました。私どもが考えていますのは、もう少し誘導をきっちりやっていこうというようなことで考えていまして、こういった制度を検討していくというものです。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう人たちの声をたくさん聞いてほしいとは思うんですけれども、まちづくり条例になるのか、検討していっていただきたいと思っています。広報で出しましたということではできないと思うので、その辺の具体的な取り組みを考えていらっしゃるかどうか、お伺いしたいと思います。","respondent":"藤田水とみどりの課長","answer":"もう一つは、重点地区に定めるような地域については、本当に顔を突き合わせながら説明をしていかなければいけないと思ってあります。この３月下旬にも、地域の方々とのお話し合いを予定していますので、そういう中で進めていきたいと考えています。","id":"exchange-062"},{"speaker":"山路委員","kind":"質問・要望","question":"３点ほど、お伺いします。３点目が、３２７ページ、お伺いいたします。","respondent":"藤橋都市整備下水道課長","answer":"バリアフリー対策と、さまざまな課題がございまして、歩行者空間等の改善の検討を区では進めております。全体２.４kmのうちの、通りの南側の部分の延長２００ｍの部分につきまして、基本の設計作業を進めたいです。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"まちの整備に関しましては、住民の皆様のご意見を聞いて、実施に当たっていただきたいことをお願いしておきます。２点目の、山元議員が新馬場駅エレベーター設置の件につきましてお伺いいたしましたが、どういうものを設置されるのかお伺いいたします。","respondent":"松代都市計画課長","answer":"設置基数は３基を予定しておりまして、道路面から入りまして、１階部分の改札まで上がるエレベーターがまず１基です。このエレベーターと合わせまして、エスカレーターに音声誘導装置をつけるように考えてございまして、そういったものの助成をするものです。","id":"exchange-064"},{"speaker":"山路委員","kind":"質問・要望","question":"いつごろ工事に入って、完成するんでしょうか。あるいはエレベーターの要望があると思うんですけれども、具体的にいつごろの予定になるのか、わかっていたらお聞かせほしいと求めました。","respondent":"松代都市計画課長","answer":"予定では、平成２２年３月中旬から工期に入りまして、来年の３月下旬に完成するという形で進めてまいります。今後、この整備を進める、残り４駅ということで、まずはこの４駅の設置に向けて検討したいと思っています。","id":"exchange-065"},{"speaker":"山路委員","kind":"質問・要望","question":"利用者からの要望は、乳幼児の用具をもう少し安全で、変化あるものを何か考えていただけないかという要望なんです。１カ所の水道しかありませんので、大変混むので、もう少し何か考えていただきたいという要望もあるのですが、どのようにお考えか尋ねました。","respondent":"齋藤道路公園課長","answer":"遊具につきましては、安全、かつクリアランスの関係がありますので、それを見ながら検討させてください。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"東京都に進言をしていくのか、それをまず１点、お伺いしたいと思います。以上、３点、教えてほしいと求めました。","respondent":"諸石交通安全担当課長、藤橋都市整備下水道課長","answer":"２点目の高齢運転者等専用駐車区間制度というんだそうですが、７０歳以上の方とか、警視庁のほうで検討されているようです。こうした駐車区間に駐車する場合にあっても、高齢運転者等標章ということで… 平成２０年の公園の改修に合わせて設置したものでございましたので、項目として予算の中に１項目、新規に計上しているものではございませんでした。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問・要望","question":"それから、駐車制度のところは、周知徹底をよろしくお願いしたいと思います。十分に心得ておりますけれども、公園の本来の姿というのも十分に斟酌をしていただきながら、この事業を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"本間委員","kind":"質問・要望","question":"まず最初にお聞きしたいと思いますが、屋外広告物取締事務というのが予算計上されておりますが、この中身を教えていただきたい。活動の内容と、人員体制等について、お願いします。","respondent":"小野土木管理課長","answer":"現在、シルバー人材センターに委託しておりまして、撤去しております。そのための経費です。","id":"exchange-069"},{"speaker":"本間委員","kind":"質問・要望","question":"もっともっと踏み込んだ形で、地域の中に入った部分でたくさんある場合もありますので、取り組みを進めてほしいと求めました。ご意見をいただければ。","respondent":"小野土木管理課長","answer":"現在、区内を１０区分いたしまして、月に１７日か１５日ぐらい、年間２０２日、１チーム３人でずっと行動しておりまして、今、委員ご指摘のありましたような看板等については、積極的に撤去をしてまいりたいと考えております。","id":"exchange-070"},{"speaker":"本間委員","kind":"質問・要望","question":"今回の専決処分の承認を求めるという土地収用事件に関する和解の件が５件出ておりました。手前の補助１６３号線もかなり進んできておりますが、簡単で結構ですから、説明を求めました。","respondent":"冨久増用地担当課長、藤橋都市整備下水道課長","answer":"ただ、１期工事部分につきましては、まだ何カ所かお話し合いを継続している部分もあります。今後、完成に向けてしかるべく対応してまいりたいと考えております。 来年度も引き続き仮設道路等の整備を進めることになりますので、何とか平成２３年度中に完了させる予定で、進めているところです。","id":"exchange-071"},{"speaker":"本間委員","kind":"質問","question":"その中には、保育園が入るというような情報がございましたが、その件についてお尋ねします。最近の大井町駅を利用する乗降客の推移について、ここ四、五年で結構ですが、どのようになっていますか尋ねました。","respondent":"松代都市計画課長","answer":"ところが、平成１９年に、始発から９時の段階で閉めるという形になってまいりました。引き続き何とか終電まで開けるようにということを、再三申し上げておりますし、今後も申し上げていきたいと考えています。","id":"exchange-072"},{"speaker":"本間委員","kind":"質問・要望","question":"どうかその辺を取り組みながら、ひとつ何とかいい解決につなげてほしいと求めましたので、よろしくお願いします。地域の陳情も伺っておりますので、まず、お聞かせ願いたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"桜の広場につきましては、これまでの議会におきまして、見通しが悪いので改善をという声も伺ってまいりました。それから広場については、今ある山を少し平坦を形にして、広場をもう少し広い形で使えるような工夫をしてまいりたいと考えています。","id":"exchange-073"},{"speaker":"須貝委員","kind":"質問","question":"もしそうでないならば、何か対応策ってあるんですか。東京都も、国も、品川区も、こういうふうにうたってきましたが、実際、どうなんか尋ねました。","respondent":"吉川防災整備担当課長","answer":"耐震化率９割を達成するという目標は、これを変える予定は、区としてもございません。来年度は、この支援制度を少しでも促進剤になるようにということで、見直しに取り組む予定です。","id":"exchange-074"},{"speaker":"須貝委員","kind":"質問","question":"行政が耐震化率９０％達成というものを挙げておいて、お願いします、でも全然進まないんですというのは通らないかと思うんです。こういうことを考えているんですっていうものを、今の時点では、何かあるんか尋ねました。","respondent":"吉川防災整備担当課長","answer":"繰り返しになってしまいますが、支援制度の見直しに、来年度早急に取り組むということが一つ。密集事業等で行っておりますので、その中で、耐震化についても意識啓発をどんどん地域の方に図っていきたいと考えております。","id":"exchange-075"},{"speaker":"須貝委員","kind":"質問・要望","question":"この景気低迷の中でどういうふうにしたらいいんだろうということがあると思いますが、できるだけ早めに何かいい方策を考えてほしいと求めました。区内の大半の地域のまちづくりについてですが、現時点で、これからどうやっていくんだという構想、そういうものはあるのか尋ねました。","respondent":"松代都市計画課長","answer":"市街地整備基本方針の見直しと合わせて、そういうハード、ソフトを合わせてつくっていこうと考えているところです。今回の新しいプランの中にきちんと盛り込んで、向こう１０年、２０年先の品川区というものをつくっていきたいと考えております。","id":"exchange-076"},{"speaker":"須貝委員","kind":"質問・要望","question":"商店街の周り、やっぱり若いファミリー層が居住できるようなマンション建設を誘導するべきではないか、それが必要ではないかと思うんです。残念ながら時間がなかったんですが、次世代の品川区民の定着を図る政策を、ぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"伊藤委員","kind":"確認","question":"３２１ページ、河川管理費、立会川に関連して、それから、３２９ページ、都市開発費に関連して、質問いたします。この防災まちづくり事業部長発言の真意の確認と、それから、現時点での立会川浄化に対する品川区の考え方の見通しを説明するよう求めました。","respondent":"岩田防災まちづくり事業部長","answer":"そのときに、東京都のほうの説明を聞きますと、第二立会川幹線全計画の竣工年度が若干ずれておるようです。それに比べて、目黒川のほうは先が長いです。","id":"exchange-078"},{"speaker":"伊藤委員","kind":"確認","question":"確認は、護岸の中に建築物を一切つくってはいけないのでしょうか。つまり、浜川砲台の跡地を、今の場所から移動することなく、何かしらつくることはできますかということを、まず確認したいと思います。","respondent":"藤田水とみどりの課長","answer":"護岸の中の関係ですけれども、護岸の中ということは、当然水が上がってくることが前提になります。水に流されてしまうとか、そういった事象につながることですので、許可はできないということになります。","id":"exchange-079"},{"speaker":"伊藤委員","kind":"質問","question":"整備もされていない、夜は電気もつかない、こういうことでいいのでしょうかという意見をたくさん聞きます。新浜川公園がたしか近くにあるはずですから、もっと突っ込んだ具体的な対応ができると思いますが、いかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"現在の位置に浜川砲台の石があるということで記載をしておりますので、もう少し様子を見ていきたいということで、お話がありました。地権者にもご了解いただいて、児童遊園の中に置くなど、地域の方々と一緒に地域を盛り上げるために努めているところです。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"意見","question":"いろいろな部と連携しながら浜川砲台という観光資源を、どういうふうにしていくかという明確なニュアンスがまだないと、私は思います。地域の皆様と十分に協議をしながら、前進していくべきと思いますが、改めてご答弁をお願いいたしますとの意見を述べました。","respondent":"藤田水とみどりの課長","answer":"私ども、地域の方とお話をしたときには、別ルートでも、当然、商業観光等の部署のほうとも連携を図りながら調整をしています。新水とみどりのネットワーク構想も、お互いに地域を盛り上げるための策ですので、十分に連携を図りながら進めていきたいと考えています。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、去年の１０月でしたか、決算特別委員会の審議の中で、大体１,０００名ぐらいのお客さんが来られると。そういうことも十分に協議されて、こういう答弁をされたと思いますので、今の現状の考え方を説明するよう求めました。","respondent":"青木都市開発課長","answer":"１,０００人規模のお客様が、理屈の上では、支障なく歩けるというデータ上の数値は把握しております。現段階では、これ以上の詳しいことは、まだご報告できない状況です。","id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問","question":"だから、そういうことも十分に考えていくと、今のお考えでは少し寂しい気がするんですよ。もう少し立体的で具体的な品川区の考え方はないのでしょうか、説明を求めました。","respondent":"本間副区長","answer":"これから十二分に検討をし、万全を期していきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-083"},{"speaker":"堺委員","kind":"確認","question":"この二つ合わせてお尋ねしたいんです。次は３１５ページの、その辺の進捗状況を、ちょっと確認だけさせていただけばと思います。","respondent":"松代都市計画課長、藤橋都市整備下水道課長","answer":"施工法などの検討を行っておりましたが、事業認可が一応平成２１年度ということでございましたが、５年間の延伸をするということを聞いてあります。引き続き安全対策には対応していきますが、補助２６号線がすべて完成を見て… 引き続き、配線工事、それから踏切の両側にあります電柱の移設の工事を進める予定です。２０日の夜につきましても、ＪＲのほうで引き続き拡幅工事を行う予定でございまして、何とか年度内に完了できるように進めているところです。","id":"exchange-084"},{"speaker":"堺委員","kind":"質問","question":"ですから、計画されている補助２６号線の上のほうの下神明駅側といいましょうか、あいているんです。その辺について、いかがか尋ねました。","respondent":"松代都市計画課長","answer":"朝の８時台に、私ども、認識しております。タコ公園の前の防護柵についても、第二建設事務所と協議をしてみたいと考えています。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年の第４回定例会で、お伺いしたんですが、事後計測の報告を求めた。質問ですけれども、この問題で、最終報告はあったのか尋ねました。","respondent":"青木都市開発課長","answer":"事業者が説明する風の環境、コンサルタントともいろいろ議論している中で、足りないところがあるのでないかという議論に至ったのが１点。風の環境の変わり方についての説明の仕方については、正直言って、なかなかわかりやすい答えを見出していないというのが現状です。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問・要望","question":"今までのやり方ですけれども、区は何を風害と、今の時点で考えているんでしょうか。何を風害と考えているのか尋ねました。","respondent":"青木都市開発課長","answer":"広場を取ったりすると、その部分だけに風が抜けやすくなりますので、そういった部分にはランク２になってしまうという部分もあります。私どもが進めているまちづくりにおいては、防災安全性の向上等を考えますと、現在の私どものまちづくりの進め方です。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"少し具体的にお伺いしたいんですが、再三、我が党の飯沼議員も追求していますが、武蔵小山事業者実施調査。１９階建てのマンションの問題ですが、この資料は、区はご存じか尋ねました。","respondent":"青木都市開発課長","answer":"はい、先ほど申し上げましたように、私どもが事業者にお願いして事後調査をやっていただいたというのは、委員、ご指摘の武蔵小山の物件です。もちろん、承知しております。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問","question":"これを、区はどう分析し、どうとらえたのか、お伺いします。この調査報告書によって、風害はある、ない、どちらに考えているのか尋ねました。","respondent":"青木都市開発課長","answer":"ただ、１点、先ほどもちょっと答弁が漏れましたけれども、この結果でも、風向きが変わるところがあります。指導していくべきなんだろうということは、私ども、知見として得たところです。","id":"exchange-089"},{"speaker":"安藤委員","kind":"質問・要望","question":"ランク２を風害と見なさないというところが最大の問題だと思いますし、専門家の方も、ランク１の条件を満足することが求められる。住民にとってどうなのかということで、突っ込んで分析してほしいんですけれども、いかがか尋ねました。","respondent":"岩田防災まちづくり事業部長","answer":"そういう状態で、八潮の１万５,０００人は日常生活をしているわけです。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"次に、３１１ページの道路安全施設費になるのでしょうか、自転車走行レーン。そして、ここは児童もそこを通るという形になるのでしょうか、その指導方法についても、お聞きします。","respondent":"諸石交通安全担当課長、齋藤道路公園課長、青木都市開発課長、吉川防災整備担当課長","answer":"最初の１時間は無料にできないかとか、１年かけて来年度に見直しを行いたい、と考えております。その中で… 自転車走行レーンの今後の拡大予定ですが、補助２０５号線が開通しますと、十分な車道幅員が取れます。補助２０５号線は立会道路と並行していますの… 都市再生総合整備事業におけますコーディネートについて、簡単にご説明申し上げます。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、別々に業務委託ですから、民間に頼むんでしょうけれども、これは１カ所ではなくて、３カ所別々なのでしょうかということです。１件、何か工夫があるのかどうかを、お聞きしたいと思います。","respondent":"諸石交通安全担当課長、青木都市開発課長、吉川防災整備担当課長","answer":"途中、自転車と歩行者の事故というのも危惧されているところでありますので、あそこに自転車の走行レーンを整備した一つの目的もそこにあるわけです。… あるいは、実際にシンクタンクだけで考えられるものは、その単純な人件費で済むということで値段が違っております。現在の見込みでは… まちづくりの観点から、商店街として、どう考えるかということも、今後話し合いをしていくことになると思います。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"これは、しっかりとまちづくりという観点で協力し合いながら、コラボレーションを取りながらやってほしいと求めました。整理するべきところは整理するとか、安全で、ちょっと活気あるところも含めて考えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"松澤委員","kind":"確認","question":"３点、お伺いいたします。自分としては平成２３年度中に完成させるんだという意気ごみなのか、どうか、そこを確認しておきたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"供用開始を平成２４年度と目標にしておりまして、今のところ、工事につきましては、平成２３年度末までには何とか完了させたいという思いで進めてあります。","id":"exchange-094"},{"speaker":"松澤委員","kind":"質問","question":"２３年度２年間ということですが、部分的に途中までやれるということはできないんですか、早めに。その辺について、お聞きしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"２３年度につきましては、各ご家庭との接続工事等を行う予定でございまして、すべての区間で工事を行うようになります。最終的には平成２３年度の途中から、工程上、全工事を一日も早く完了させるように頑張って取り組んでまいりたいと考えております。","id":"exchange-095"},{"speaker":"松澤委員","kind":"質問・要望","question":"戸越幹線貯留管中流部整備工事は、どこか他の款でも、ほかの委員が質問したんですけれども、これの完成予定日はいつなんでしょうか。それから、切廻復旧補償費とありますけれども、どんな補償をするのか、これはどういうことなのかについて、お聞きしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"１点目の、完成予定日という話ですけれども、今のところ、７月末には工事が完了する予定で、今、進めております。最後の工事が終わった段階には、もとの位置に戻すような計画をしておりまして、これに伴う費用として２,０００万円計上しております。","id":"exchange-096"},{"speaker":"松澤委員","kind":"質問","question":"この工事が完成すると、５０mm対応ができるというお話も伺っています。５０mm対応と、５０mmの降雨量というのは、予測的にはどのように考えているんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる５０mm以上を超える降雨が頻発していますが、何年に１回という形では申し上げられませんで、３年に１回降る雨という形で進めております。おおむね１時間５０mmに対応したような形になりまして、流域全体では、今のところは進めております。","id":"exchange-097"},{"speaker":"松澤委員","kind":"質問","question":"これが公表されるときには、１５分２５mm、１時間当たり１００mmという形で報告されます。我々としては、そのぐらいの集中豪雨がぱっと１５分間降ったらあふれちゃうのかという思いがするんですが、その辺との関係はいかがか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"考えにくいんですが、いわゆる１０分間の降雨量が例えば１０mmですと、単純計算しますと１時間６０mmという形になります。数年前に台風２２号、２３号という二つの台風が来たときには、まずひと雨降雨を想定した施設でつくってあります。","id":"exchange-098"},{"speaker":"松澤委員","kind":"質問","question":"夕方、どさっと降る雨には対応できるという話を伺ったと理解しておきます。どのような歩道橋ができるのかについて示すよう求めました。","respondent":"青木都市開発課長","answer":"その場で架け替えるので、ちょっと仮設等にお金がかかる見込みです。歩ける幅が約３.６ｍほど、それぞれ両側にエレベーターをつけまして、自転車の持込みができるようなものを計画しております。","id":"exchange-099"},{"speaker":"渡部委員","kind":"質問・要望","question":"１点、これは確認が多くなるんですが、３２９ページのしながわ区民公園北側ゾーン改修実施設計のところで伺いたいと思います。ヒアリングは要望なんですが、ここは実際に２年かかるのかというところを説明するよう求めました。","respondent":"藤橋都市整備下水道課長、齋藤道路公園課長","answer":"工事の安全を司る私としては、安全が最優先だと考えています。２年間それを使わないという形でも、できるだけ来年度の早い段階で、今後の工事スケジュールについては示してまいりたいと考えています。 団体の数は５隊で、変更はありませんが、そんな形で５隊が維持されております。毎月１回、うちの区の職員が対応させていただいて、これが成果です。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問・要望","question":"ほんとうにこれは要望ですけれども、いろいろ話し合いを進めてほしいと思いますので、よろしくお願いします。いかがか尋ねました。","respondent":"齋藤道路公園課長","answer":"周知の方法については、充実をさせていただきたいと思います。なかなかなり手がいないというのが実情ですが、いろいろ広報活動については充実に努めてまいりたいと思います。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"ちょっと聞き方がまずかったんですが、人数を増やしていくということに対するお考えがありますか尋ねました。","respondent":"齋藤道路公園課長","answer":"マニュアルを配付しておりまして、維持管理の手順については、統一的なものをお渡ししております。区民の協働を図りたいと考えていますので、区民の皆さんの手を借りて、よりよいものにしたいと考えております。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問・要望","question":"意外と求めてくださっている方もいると思いますので、こういうのがある、やってみませんかという声かけもしていきたいと思います。今回、これをちょっと質問させていただいて、またいろいろなところで紹介していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"武内委員","kind":"質問","question":"私は、２点お伺いします。３１７ページの立会川緑道整備工事費、それから、３３３ページ、密集住宅市街地整備促進事業、２点お伺いします。","respondent":"藤橋都市整備下水道課長、片田建築課長","answer":"立会川緑道整備についてです。平成２２年度につきましては、国道１号線と原っぱ公園前までの延長約２００ｍ区間におきまして、工事を行う予定です。 具体的には、行き止まりの私道であっても、細街路の拡幅の助成対象とするなど、そのようなやり方をやってきています。隅切りを設ける等を含めて、細街路の拡幅整備の際に、あわせて支援しているといったような状況です。","id":"exchange-104"},{"speaker":"武内委員","kind":"質問・要望","question":"前にちょっとどこかで質問させていただいて、その辺がどのぐらい解消できるのか、ちょっと教えていただきたい。その辺の状況というんですか、そこまで把握しているのかどうかも含めて、教えてほしいと求めました。","respondent":"藤橋都市整備下水道課長、吉川防災整備担当課長","answer":"考えてありますのは、少し工夫いたしまして、今よりも小さくできないかという形で検討を進めております。その話を進めまして、平成２２年度の７月ぐらいから工事を進める予定で、今、考えてあります。 各地区５件、全部で２０カ所ほど細街路整備を実施しておりまして、個別にかなりデータを取っているところです。","id":"exchange-105"},{"speaker":"武内委員","kind":"質問・要望","question":"４ｍ以下のところでも、そういう対策というのは、何か今やっているのか。どうしても火事とか起きますと、あわせて、教えてほしいと求めました。","respondent":"片田建築課長","answer":"２項道路、助成制度の対象として、建物の建て替えにあわせて指導している状況です。そんなところについては、今、指定道路の関係で、台帳整備を行ってきてありますので、徐々に、状況をまず把握しておきたいという状況です。","id":"exchange-106"},{"speaker":"武内委員","kind":"質問・要望","question":"そうすると、大分消防車が入れるようになるということが、現実、あるのではないかと思います。とりあえず、検討で結構なんですけれども、ちょっと考え方も含めて、要望させていただきたいんですけれども、お答えをほしいと求めました。","respondent":"片田建築課長、岩田防災まちづくり事業部長","answer":"行きどまりの道等々でセットバックする必要があるものについては、それは助成の対象として、建築確認行為の中で指導しているという状況です。 角地の家が建築行為をされるとき、道幅が６ｍ未満の道路が交差する角地のところは、条例で隅切りを義務づけています。セットバック経費、塀の築造工事費も、区が助成するということになっております。","id":"exchange-107"},{"speaker":"武内委員","kind":"質問・要望","question":"時間がないので、要望だけですけれども、６ｍ以下のところも検討していただきたいということで、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"土木費全体で６項あって、１５目あるんですけれども、項とか目の表題は、自治体で決められているんですか。こういう表題にしなさいということが決められているのか、否か。","respondent":"金子企画財政課長","answer":"款項目のあたりのご質問ですけれども、款は指定されておりますけれども、項と目については、それぞれの自治体で工夫して定められるものです。","id":"exchange-109"},{"speaker":"須藤委員","kind":"意見","question":"目のところだけずっと拾っていくと、建築費だけ、建築行政費となっていて、あとは何とか総務費になっているんですけれども、何で建築行政費だけ。河川総務費でつくっているんだけれども、そのあたり、何か建築行政のほうは何かあるからそういう表現したのかとの意見を述べました。","respondent":"金子企画財政課長","answer":"建築に関しましては、昔から、建築確認が主たる業務になっていまして、そういう意味では、非常に権力的な行政を執行している部分で、そういう意味での表記を継続しているという趣旨と考えております。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問","question":"そんなところがうまくスムーズにいけるようになるかどうか、ちょっと懸念しているんですが、いかがでしょうか。新たに復旧するんですから、商店会長さんとかのご意見を伺って、そういう方向にする考えはありますか。","respondent":"藤橋都市整備下水道課長","answer":"それについては、説明会でもご説明申し上げましたけれども、技術的な検討が必要なので、１カ月ぐらいお時間をいただきたいと考えています。説明会でも配置の見直し等の要望を承ってありますので、より詳細な検討をしていく中で、検討させていただき。","id":"exchange-111"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりはきちんと設計する方に、全体がバリアフリーのまちにしてあるというようなことは、きちんとお伝えしてあるのかどうか。１回つくっちゃったら、町会長とかに要望を聞いていただいて、いかがか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"今後、きちんと整理をいたしまして、対応してまいります。設置する予定ですが、地域の方々とお話し合いをしながら、丁寧に説明して対応してまいります。","id":"exchange-112"},{"speaker":"須藤委員","kind":"質問","question":"この間はあまり質問がなかったんですけれども、これから委託をして、設計委託みたいなものをしてくるところから来るような健康遊具なんですか。もう今、品川区で対応しているというものを、そこに置くという考え方なのか。","respondent":"藤橋都市整備下水道課長","answer":"面積的に小さいので、鈴ケ森公園でやっていたような健康遊具をつけるという形は、今のところ考えてございません。ほかの健康遊具の形がありましたので、それを少し見直しするようなものを考えたいと考えています。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問・要望","question":"平成２２年度も、同じように流すことによって実験が続けられるのか。そのあたりを説明するよう求めました。","respondent":"藤田水とみどりの課長","answer":"平成２２年度、私どものほうで考えています目黒川の浄化の関係ですが、そこに悪さをするような泥がたまっております。国、あるいは東京都の動きとも連携しながら、この事業をどうするかを決めなければいけないと考えています。","id":"exchange-114"},{"speaker":"須藤委員","kind":"質問・要望","question":"前年度に、これが足りなかったということを是正しながら、また、ステップを進めていってもらいたいと思います。いろいろやっていただいて、今度は少しでもいい結果が見えているので、それに対して足りないところは何かということを続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"川西委員","kind":"質問","question":"この５億円のほかは、児童遊園の改良費、公園新設改良費というのはここに出ているだけなんでしょうかね。この敷地内の緑化については、今後、どこが維持管理をして、だめにならないようにしていただくのか、この辺で伺います。","respondent":"齋藤道路公園課長、藤橋都市整備下水道課長、吉川防災整備担当課長、青木都市開発課長、片田建築課長","answer":"場所は、関地下道、南三ツ木地下道で、新しく塗るところを予定しています。区に所有権を移転してまいりまして、２カ所、それを補修をいたします。いわゆる区内の施設に雨水タンクを設置するものでございまして、毎年２カ所ずつ、おおむね５００ｌの雨水利用タンクの設置工事をしてまいりました。… 今後の公園をつくる予定ということですが、密集事業および防災生活圏促進事業でつくる防災広場は、条例上、児童遊園という位置づけになります。","id":"exchange-116"},{"speaker":"川西委員","kind":"確認","question":"出てくるということで、５億円のほかに、品川保育園跡だけしか書いてないというのはどういうことでしょうか。先にちょっと伺います。","respondent":"齋藤道路公園課長","answer":"整備したものは、次は道路公園課が引き続きまして維持管理をいたします。","id":"exchange-117"},{"speaker":"川西委員","kind":"質問","question":"それから、今、５億円の用地取得というのは、大変困難なんでしょうかね、目標が出てこないということは。努力して、品川区内全域を回って、せっかく組んでいただいた予算だから、早く実現してほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"川西委員","kind":"質問","question":"そんな程度の金額ですから、もっと積極的に事業ができるのではないかと思いますので、補正予算も含めて期待をいたしたいと思います。そういう二つの点についてのお考えを説明するよう求めました。","respondent":"小野土木管理課長","answer":"これは、国から移管した財産を、区としても、財産管理をきちっとするということで、管理人の規定も設けまして、今後、きちっと管理をしていこうです。あるいは所管換え等も含めて対応していくということで、今後、きちっと整理をして対応してまいりたいと考えております。","id":"exchange-119"},{"speaker":"川西委員","kind":"質問・要望","question":"月に２回、しているんですかね。ではその辺について、ちょっと具体的に伺います。","respondent":"齋藤道路公園課長","answer":"街路樹、月２回、巡視点検をいたしますし、季節、季節に週に３回、あるいは２回、水まきをしております。それから、散水栓の確保はなかなか難しいんですけれども、区の職員も含めて水まきをして、維持管理の充実に努めてまいろうと思います。","id":"exchange-120"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、そういう点からしますと、ぜひお願いしたいと思います。そういう点で、フラワーポットみたいなものを、予算は大してかからないと思いますから、今後、お考えいただくといいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"宮崎委員","kind":"質問","question":"私は、３３３ページの目黒駅前の再開発について、伺いたいと思います。そこら辺のところを、まず伺いたいと思います。","respondent":"青木都市開発課長","answer":"斜線規制からはみ出したものも構わないという形の制度が変わってまいりますので、背の高い建物は、計画上可能になってきているという現実があります。そういった形で、この地区では、１４５ｍの建物が計画上、可能であるです。","id":"exchange-122"},{"speaker":"宮崎委員","kind":"質問","question":"通常、再開発ですと、大体２０％程度、税金投入していたと思うんですけれども、そこら辺がどういうふうになるのかということを伺いたいと思います。それから、参加組合員、現在、どうなっているのか、予定も含めて、伺いたいと思います。","respondent":"青木都市開発課長","answer":"東京都と協議をしている最中で、用途地域の変更がなされれば、約３分の２ぐらいまでが商業地域に変更されます。結果としまして、この計画どおりに進みますと、全体の容積率は、平均して８９０％ぐらいになる見込みです。","id":"exchange-123"},{"speaker":"宮崎委員","kind":"質問","question":"そもそも７００％ということと、変更されると、もっと容積の大きなものができるということになってくるんでしょうか。今、出てきている計画とは変わってくるということになるんか尋ねました。","respondent":"青木都市開発課長","answer":"１点、答弁漏れがございました。既に東京都との協議によって、用途地域を商業地域に大部分変更する前提でつくられておりますので、用途地域の変更を前提とした計画案です。","id":"exchange-124"},{"speaker":"宮崎委員","kind":"質問","question":"この需要は、どこで、どういうふうに決めるのでしょうか。これだけあるんだということが判断されて、こういう計画になっているのではないかと思うんですけれども、どうなんか尋ねました。","respondent":"青木都市開発課長","answer":"行政側のまちづくりの考え方としましては、繰り返しになりますけれども、目黒駅前地区は、品川区においては地域生活拠点です。事業協力者、東京都が進める都市づくりビジョンにおけるセンターコアの一端を成していますので、十分に需要はあるだろうと見込んでいるところです。","id":"exchange-125"},{"speaker":"宮崎委員","kind":"意見","question":"２割投入というと２００億円ということですよね。私はこの考え方が、さっぱりわかりません、ちょっと説明願いたいと思いますとの意見を述べました。","respondent":"青木都市開発課長","answer":"認可権者たる東京都も認可しないという形になってまいりますので、それなりの手続を踏んで、需要を見込んでつくっているものです。ご理解いただきたいと思います。","id":"exchange-126"},{"speaker":"宮崎委員","kind":"質問","question":"それなら、伺いますけれども、中地区は、最初から６割程度しか売れないということを予想していたんですか。子育て支援施設をつくるからと言いながら、近所の幼稚園に日影をしてしまうということは、どういうことなのか尋ねました。","respondent":"青木都市開発課長","answer":"６割程度とおっしゃっていますけれども、１,０００戸に至る巨大な住宅供給ですので、権利者の方々に説明していたところです。時間をかけてやっていくということは、参加組合員のほうで言っているものでございまして、必ずしも破綻しているということでは決してございません。","id":"exchange-127"},{"speaker":"宮崎委員","kind":"意見","question":"しかしやっぱり、結局売れていないというのは、再開発そのものの事業としては成り立っていないということを言っておきたいと思います。それから、やっぱり幼稚園に日影を落とすというやり方は見直してほしいということを強調しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-128"},{"speaker":"三上委員","kind":"提案","question":"そういった点でのお考えが、改善されるのかどうかということについて、ちょっとお伺いしたい。消熱塗料ということで提案をしたわけですけれども、積極的に取り入れるという姿勢があるのか、どうかということについてお伺いしたいとの意見を述べました。","respondent":"諸石交通安全担当課長、齋藤道路公園課長、藤田水とみどりの課長、青木都市開発課長","answer":"今後、これをどういうふうにしていくかは、これから検討してまいりたいと思います。銀行側には、歩行者が滞留するような場所が全くありませんので… 把握しておりませんので、今後、研究をします。目黒区と、中央区のほうで、平成２２年度から開始をするということで、私どもも確認しています。","id":"exchange-129"},{"speaker":"三上委員","kind":"質問・要望","question":"チラシでもいいですから、その人がきちっと取り組めるようなことを、やっぱり充実させていっていただきたいとお願いしておきます。そういった先進技術について、入手する努力というものについては、ぜひ取り組んでいただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう少し、その辺、密に連絡を取るべきではないかと、私は考えますけれども、その辺のお考えをひとつ教えてください。その中で、先ほど、大井町ですとＮＰＯがつくっていますけれども、その関連について、今の状況を、ちょっとご説明をほしいと求めました。","respondent":"藤橋都市整備下水道課長、青木都市開発課長","answer":"縦断構造をどうするかという検討を行いまして、設置してあるところに、これに時間を費やしている状況です。基本設計を進める中で、まとまった部分につきましては、地域の方々に丁寧に説明してまいりたいと考えております。３月に入ってしまったのですけれども、品川区は、現段階でこんなことを考えているというものをお披露目しています。","id":"exchange-131"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、元なぎさ通りにこだわっていませんので、全体的な区としての考えとして持ってもらいたいということでのお願いです。そこら辺について、お考えを先にほしいと求めました。","respondent":"青木都市開発課長","answer":"それについては、今、申し上げましたまちづくり構想の中で、長期的な課題として位置づけて、今後、検討のたたき台をつくっているところです。非常に苦しい対応を迫られるんですけれども、各課で情報を共有しながら対応を練っているところありますので、何とか。","id":"exchange-132"},{"speaker":"鈴木委員","kind":"確認","question":"それからもう１点は、これは前にも言ったかもしれないんですけれども、区の職員の方が２,５００人います。その時点で伝わる、横串というか、この辺が伝わっているのかということを、ちょっと確認をします。","respondent":"齋藤道路公園課長","answer":"委員のご提案のように、幅広く聞けるように、職員にも周知をしてまいりたいと思います。第二京浜国道とか、品川駅方面とか、表示を改めします。","id":"exchange-133"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区の職員については、ちょっとお答えができないと思いますけれども、その辺意識してもらいたいと思います。そういう連絡が伝わるようにしてほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/998976?Template=document&Id=938#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":118728,"voices":339}}]);
